window.TXB=window.TXB||{};TXB["alab/Psa"]={"1:1":"طوبى للإنسان الذي لا يتبع مشورة الأشرار، ولا يقف في طريق الخاطئين، ولا يجالس المستهزئين.","1:2":"بل في شريعة الرب بهجته، يتأمل فيها نهارا وليلاَ.","1:3":"فيكون كشجرة مغروسة عند مجاري المياه، تعطي ثمرها في حينه، وورقها لا يذبل، وكل ما يصنعه يفلح.","1:4":"ليس كذلك حال الأشرار، بل إنهم مثل ذرات التبن التي تبددها الريح.","1:5":"لذلك لا تقوم لهم قائمة في يوم القضاء، ولا يكون للخطاة مكان بين جماعة الأبرار،","1:6":"لأن الرب يحفظ طريق الأبرار، أما طريق الأشرار فمصيرها الهلاك.","2:1":"لماذا ضجت الأمم؟ ولماذا تتآمر الشعوب باطلاَ؟","2:2":"اجتمع ملوك الأرض ورؤساؤها، وتحالفوا ليقاوموا الرب ومسيحه، قائلين:","2:3":"«لنحطم عنا قيودهما، ونتحرر من نير عبوديتهما».","2:4":"لكن الجالس على عرشه في السماوات يضحك. الرب يستهزيء بهم.","2:5":"عندئذ ينذرهم في حمو غضبه، ويروعهم بشدة سخطه،","2:6":"قائلاَ: «أما أنا فقد مسحت ملكي، وأجلسته على صهيون، جبلي المقدس».","2:7":"وها أنا أعلن ما قضى به الرب: قال لي الرب: «أنت ابني، أنا اليوم ولدتك.","2:8":"اطلب مني فأعطيك الأمم ميراثا، وأقاصي الأرض ملكا لك.","2:9":"فتكسرهم بقضيب من حديد، وتحطمهم كآنية الفخار».","2:10":"والآن تعقلوا أيها الملوك، واحذروا ياحكام الأرض.","2:11":"اعبدوا الرب بخوف، وابتهجوا برعدة.","2:12":"قبلوا الابن لئلا يغضب، فتهلكوا في الطريق، لئلا يتوهج غضبه سريعا. طوبى لجميع المتكلين عليه.","3:1":"رب ما أكثر خصومي! كثيرون يتألبون علي.","3:2":"كثيرون يقولون عني: لا خلاص له بإلهه…","3:3":"ولكنك أنت يارب ترسي. إنك مجدي ورافع رأسي.","3:4":"بملء صوتي أدعو إلى الرب فيجيبني من جبله المقدس.","3:5":"رقدت فنمت، ثم استيقظت من غير أن يصيبني شر، لأن الرب يسندني.","3:6":"لن أخشى عشرات الألوف من البشر الملتفين حولي، المحتشدين لمحاربتي.","3:7":"قم يارب. خلصني ياإلهي! فإنك قد ضربت جميع أعدائي على فكوكهم، فهشمت أسنان الأشرار.","3:8":"أنت وحدك المخلص يارب. فلتفض بركتك على شعبك.","4:1":"استجب لي عندما أدعوك ياإله بري، فقد أفرجت لي دوما في الضيق، فأنعم علي وأصغ إلى صلاتي.","4:2":"إلى متى يابني البشر تحولون مجدي عارا؟ وإلى متى تحبون الأمور الباطلة، وتسعون وراء الأكاذيب؟","4:3":"اعلموا أن الرب قد ميز لنفسه تقيه؛ الرب يسمع عندما أدعوه.","4:4":"ارتعدوا ولا تخطئوا. فكروا في قلوبكم على مضاجعكم معتصمين بالصمت.","4:5":"قدموا ذبائح البر، واتكلوا على الرب.","4:6":"ما أكثر المتسائلين: «من يرينا خيرا؟» أشرق علينا أيها الرب بنور وجهك.","4:7":"غرست في قلبي فرحا أعظم من فرح من امتلأت بيوتهم وأجرانهم بالحنطة والخمر الجديدة.","4:8":"بسلام أضطجع وأنام، لأنك أنت وحدك يارب تنعم علي بالطمأنينة والسلام.","5:1":"رب أصغ إلى كلامي وأنصت إلى تنهدي،","5:2":"اسمع إلى نداء استغاثتي ياملكي وإلهي، فإني إليك أصلي.","5:3":"في بواكير الصباح تصغي إلى صوتي يارب، وفي الصباح أتوجه إليك منتظرا إياك.","5:4":"فإنك إله لا يسر بالشر. وليس للشرير أن يقيم في حضرتك.","5:5":"لا يمثل المتغطرسون أمامك، فإنك تبغض جميع فاعلي الإثم،","5:6":"وتهلك الناطقين بالكذب، لأنك تمقت سافك الدماء والماكر","5:7":"أما أنا فبفضل رحمتك العظيمة أدخل بيتك. أسجد في خشوع ورعدة في هيكلك المقدس.","5:8":"يارب أرشدني لعمل برك عند مواجهة أعدائي لي، وسهل أمامي طريقك.","5:9":"إذ ليس في أفواههم صدق وداخلهم مفاسد، حناجرهم قبور مفتوحة وألسنتهم أدوات للمكر.","5:10":"احكم عليهم اللهم، ولتكن مؤامراتهم فخا لهم يسقطون فيه. طوح بهم لكثرة معاصيهم فإنهم قد تمردوا عليك.","5:11":"ويبتهج جميع المتكلين عليك. إلى الأبد يترنمون، لأنك تظللهم بحمايتك، فيفرح بك الذين يحبون اسمك.","5:12":"لأنك أنت يارب تبارك البار وتطوقه بترس رضاك.","6:1":"يارب لا توبخني في إبان غضبك، ولا تؤدبني في احتدام سخطك.","6:2":"ارحمني يارب لأني ضعيف. اشفني يارب لأن عظامي راجفة،","6:3":"ونفسي مرتعدة جدا. وأنت يارب فإلى متى (تنتظر)؟","6:4":"ارجع يارب وحرر نفسي، أنقذني بفضل رحمتك.","6:5":"إذ ليس في عالم الموت من يذكرك، أو في مقر الأموات من يسبحك.","6:6":"لقد أرهقني تنهدي، فأغرق سريري في كل ليلة بدموعي وأبلل بها فراشي.","6:7":"وهنت عيناي من فرط الغم، وكلتا بسبب جميع خصومي.","6:8":"ابتعدوا عني ياجميع فاعلي الإثم، لأن الرب قد سمع صوت بكائي.","6:9":"سمع الرب تضرعي. الرب يتقبل صلاتي.","6:10":"ليخز جميع أعدائي ويرتاعوا جدا، وليتراجعوا إذ لحق بهم العار فجأة.","7:1":"أيها الرب إلهي، إليك التجأت، فأنقذني ونجني من جميع مطاردي،","7:2":"لئلا يفترس العدو نفسي كالأسد، ولا من ينقذني.","7:3":"أيها الرب إلهي، إن كنت قد اقترفت هذه الإساءة، وكانت يداي قد ارتكبتا هذا الإثم،","7:4":"إن كنت قد أسأت لمن أحسن إلي وسلبت عدوي من غير سبب،","7:5":"إذن فليطارد العدو نفسي وينزعها مني، وليدس في الأرض حياتي، ويعفر في التراب شرفي.","7:6":"انهض يارب في احتدام غضبك، وانتصب في وجه سخط خصومي، يامن أوصيت بالعدل.","7:7":"لتحط بك جماعة الشعوب فتحكمها من منصة القضاء العالية.","7:8":"إن الرب يدين الأمم. اقض لي يارب كحقي، بحسب ما في من كمال.","7:9":"ضع حدا لشر الأشرار، وأثبت براءة الأبرار، أيها الإله العادل فاحص القلوب والدخائل.","7:10":"ملجإي عند الله مخلص مستقيمي القلوب.","7:11":"الله قاض عادل، وهو إله يسخط على الأشرار في كل يوم.","7:12":"صقل سيفه ليضرب به الشرير الذي لا يتوب. وتر قوسه وهيأها.","7:13":"أعد له الأسلحة القتالة، وجعل سهامه محرقة.","7:14":"هوذا العدو يتمخض بالإثم، يحبل بالأذى، ويلد كذبا.","7:15":"حفر بئرا وعمقها، فسقط فيها.","7:16":"شره يرتد على رأسه، وظلمه يهبط على هامته.","7:17":"إني أحمد الرب من أجل عدالته، وأترنم لاَسم الرب العلي.","8:1":"أيها الرب سيدنا، ما أعظم اسمك في كل الأرض، به بسطت جلالك فوق السماوات.","8:2":"من أفواه الأطفال والرضع أسست حمدا، لإفحام خصومك، وإسكات عدو ومنتقم.","8:3":"عندما أتأمل سماواتك التي أبدعتها أصابعك، والقمر والنجوم التي رتبت مداراتها","8:4":"أسائل نفسي: من هو الإنسان حتى تهتم به؟ أو «ابن الإنسان» حتى تعتبره؟","8:5":"جعلته أدنى قليلا من الملائكة إلى حين، ثم كللته بالمجد والكرامة","8:6":"وأعطيته السلطة على كل ما صنعته يداك. أخضعت كل شيء تحت قدميه.","8:7":"الغنم والبقر وجميع المواشي، ووحوش البرية أيضا،","8:8":"والطيور والأسماك وجميع الحيوانات المائية.","8:9":"أيها الرب سيدنا، ما أعظم اسمك في كل الأرض!","9:1":"أحمد الرب بكل قلبي. أحدث بجميع معجزاتك.","9:2":"أفرح بك وأبتهج. أرنم لاَسمك أيها العلي.","9:3":"عندما يتقهقر أعدائي إلى الوراء، يتعثرون ويهلكون أمام وجهك،","9:4":"لأنك برأتني ودافعت عن قضيتي، إذ جلست على عرشك لتقضي بالعدل.","9:5":"زجرت الشعوب وأهلكت الشرير، محوت اسمهم إلى أبد الدهور.","9:6":"أفنيت العدو إفناء. دمرت مدنهم حتى باد ذكرهم.","9:7":"أما الرب فإلى الأبد يملك. ثبت عرشه للقضاء.","9:8":"يدين العالم بالعدل ويقضي بين الشعوب بالإنصاف.","9:9":"ويكون الرب ملجأ للمظلوم، حصنا في أزمنة الضيق.","9:10":"ويتكل عليك الذين يعرفون اسمك، لأنك يارب لم تخذل طالبيك.","9:11":"أشيدوا بالحمد للرب المتوج في صهيون، أذيعوا بين الشعوب أعماله العظيمة.","9:12":"فهو الذي يثأر للدماء. لا ينسى ولا يتجاهل صراخ المتضايقين.","9:13":"ارحمني يارب. انظر مذلتي التي يسومني إياها مبغضي، يامنقذي من أبواب الموت،","9:14":"لكي أحدث بجميع تسابيحك في أبواب ساكني صهيون، مبتهجا بخلاصك.","9:15":"لقد هوت الشعوب في أعماق الحفرة التي حفروها، وأطبق الفخ الذي نصبوه على أرجلهم.","9:16":"الرب معروف بعدله، قضى أن يقع الشرير في شرك أعماله.","9:17":"مآل الأشرار إلى الجحيم. وكذلك جميع الأمم الناسين الله .","9:18":"أما المحتاج المتضايق فلن ينسى إلى الأبد. ورجاء المساكين لن يخيب إلى الدهر.","9:19":"قم يارب. لا تدع الإنسان يسود، ولتحاكم الأمم أمام حضرتك.","9:20":"ألق في قلوبهم الرعب فتعلم الأمم أنهم ليسوا سوى بشر.","10:1":"رب، لماذا تقف بعيدا وتحتجب في أزمنة الضيق؟","10:2":"الشرير، بعجرفة، يجد في تعقب المسكين، غير أن الأشرار يسقطون في مؤامرتهم التي فكروا فيها.","10:3":"الشرير يفتخر بشهوات نفسه، والرجل الطماع يلعن ويجدف على الله.","10:4":"في تكبره وتشامخه لا يلتمس الله ، ولا مكان لله في أفكاره كلها،","10:5":"ومع ذلك فإن مساعيه تبدو ناجحة، ويستخف بجميع أعدائه. ولكن أحكامك عالية أسمى منه","10:6":"قال في نفسه: «لن يزحزحني شيء، ولن ينالني مكروه قط».","10:7":"فمه مملوء لعنة وغشا وظلما. تحت لسانه الأذى والإثم.","10:8":"يتربص في كمائن الديار ليقتل البريء. عيناه تترصدان المسكين.","10:9":"يكمن في الخفاء، كأسد في عرينه ليخطف المسكين ويجره في شبكته.","10:10":"يسحق المساكين ويدوسهم حين يسقطون بين مخالبه القوية.","10:11":"يقول في قلبه: الله غافل. قد حجب وجهه، ولن يرى ما يجري","10:12":"قم يارب، ارفع يدك ياالله ، لا تنس المساكين.","10:13":"لماذا يستهين الشرير بالله قائلا في قلبه: إنك لا تحاسبه؟","10:14":"ولكنك قد رأيت. عاينت ما أصاب المساكين من المشقة والغم، فتجازي الشرير بيدك. يسلم إليك المسكين أمره، فأنت دائما معين اليتيم.","10:15":"حطم ذراع الشرير والفاجر. حاسبه على شره، حتى إذا طلبته لا تجده.","10:16":"الرب ملك إلى أبد الدهور، قد بادت من أرضه الأمم (التي تعبد آلهة سواه)","10:17":"أنت يارب تستجيب طلبة الودعاء، تشدد قلوبهم إذ تصغي (إلى تأوهاتهم).","10:18":"تنصف اليتيم والمقهور، فلا يعود إنسان في الأرض يرعبهم.","11:1":"إلى الرب التجأت، فكيف تقولون لنفسي: «اهربوا إلى جبالكم كعصفور؟»","11:2":"هوذا الأشرار يشدون أقواسهم، فوقوا سهاما في أوتارها، ليطلقوها في الظلام على ذوي القلوب المستقيمة.","11:3":"إذا تقوضت الأساسات، فماذا يعمل الصديق؟","11:4":"مازال الرب في هيكله المقدس. الرب في السماء عرشه. تبصر عيناه بني آدم، وتتقصاهم أجفانه.","11:5":"يمتحن الرب الصديق، ولكن نفسه تمقت الشرير ومحب الظلم.","11:6":"يمطر على الأشرار جمرا وكبريتا وتكون الريح المحرقة نصيبهم.","11:7":"لأن الرب عادل، ويحب الإنصاف، ويبصر المستقيمون وجهه.","12:1":"أغث يارب لأنه قد انقرض التقي، واختفى الأمناء من بين بني البشر.","12:2":"كل إنسان يخاطب صاحبه بالباطل: بشفاه ملقة وقلوب منافقة يتحادثون.","12:3":"يقطع الرب كل الشفاه الملقة، وكل لسان متبجح.","12:4":"الذين قالوا: ألسنتنا لنا وبها نسود. فمن يتحكم فينا؟","12:5":"ولكن الرب يقول: إنقاذا للمساكين، واستجابة لتنهدات المظلومين، أهب الآن لأفرج كربة المتضايقين.","12:6":"أقوال الرب خالصة لا شائبة فيها، كالفضة المنقاة المصفاة سبع مرات في بوتقة محماة.","12:7":"أنت يارب تحفظ الأبرار، وتقيهم إلى الأبد من جيل الأشرار.","12:8":"يتجول الأشر ار أحرارا في كل ناحية، عندما يتبوأ أراذل الناس المقامات الرفيعة.","13:1":"إلى متى يارب تنساني؟ أإلى الأبد؟","13:2":"إلى متى أرعى هموما في نفسي وحزنا في قلبي كل يوم؟ إلى متى يتشامخ عدوي علي؟","13:3":"انظر إلي أيها الرب إلهى واستجب لي. أنر عيني لئلا أنام نومة الموت،","13:4":"فيقول عدوي: قد قهرته؛ ويبتهج خصومي بسقوطي.","13:5":"غير أني توكلت على رحمتك، فيبتهج قلبي حقا بخلاصك.","13:6":"أرنم للرب لأنه غمرني بإحسانه العميم.","14:1":"قال الجاهل في قلبه: لا يوجد إله! قد فسد البشر وارتكبوا الموبقات، وليس بينهم من يعمل الصلاح.","14:2":"أشرف الرب على بني آدم ليرى هل هناك أي فاهم يطلب الله ؟","14:3":"فإذا الجميع قد ضلوا على السواء. كلهم فسدوا، وليس بينهم من يعمل الصلاح، ولا واحد.","14:4":"أليس لدى جميع فاعلي الإثم معرفة؟ أولئك الذين يأكلون شعبي كما يأكلون خبزا، والرب لا يطلبون.","14:5":"هناك استولى عليهم خوف عظيم، لأن الله في جماعة الأبرار.","14:6":"تسفهون رأي المسكين، لأنه جعل الله ملجأه.","14:7":"ليت من صهيون خلاص إسرائيل. عندما يرد الرب سبي شعبه، يبتهج يعقوب، ويفرح بنو إسرائيل.","15:1":"يارب من يقيم في مسكنك؟ ومن يأوي إلى جبلك المقدس؟","15:2":"السالك بالاستقامة، الصانع البر، والصادق القلب.","15:3":"الذي لا يشوه سمعة الآخرين، ولا يسيء إلى صاحبه، ولا يلحق بقريبه عارا.","15:4":"يحتقر الأراذل ويكرم خائفي الرب. لا ينقض حلفه ولو فيه أذى له.","15:5":"لا يستثمر ماله بالربا، ولا يقبض رشوة للإيقاع بالبريء. الذي يصنع هذا لا يتزعزع أبدا.","16:1":"احفظني ياالله ، فإني متوكل عليك.","16:2":"قلت للرب: أنت سيدي، ولا خير لي بمعزل عنك.","16:3":"كل بهجتي في قديسي الأرض وأفاضلها.","16:4":"تتكاثر أوجاع المتهافتين وراء غيرك. أما أنا فتقدمات سكائبهم الدموية لا أقدم، ولا أذكر أسماء أوثانهم بشفتي.","16:5":"الرب نصيبي وميراثي وكأس ارتوائي. أنت حافظ قسمتي.","16:6":"في أرض بهيجة وقعت قسمة حصتي. فما أفضل هذا الميراث عندي!","16:7":"أبارك الرب ناصحي، وفي الليل أيضا يرشدني ضميري.","16:8":"جعلت الرب أمامي دائما فإنه عن يميني لئلا أتزعزع.","16:9":"لذلك فرح قلبي وتهلل لساني حتى إن جسدي سيرقد على رجاء،","16:10":"لأنك لن تترك نفسي في هوة الأموات ولن تدع وحيدك القدوس ينال منه الفساد.","16:11":"هديتني سبل الحياة: فإن ملء البهجة في حضرتك، وفي يمينك مسرات أبدية.","17:1":"اسمع يارب دعوى الحق. أنصت إلى صراخي، وأصغ إلى صلاتي الصاعدة من شفتين صادقتين.","17:2":"ليخرج من أمامك قضائي، ولتلاحظ عيناك استقامتي.","17:3":"اختبرت قلبي إذ افتقدتني ليلا، وامتحنتني فلم تجد في سوءا. لم تخالف أقوالي أفكاري.","17:4":"ما شأني بأعمال الناس الشريرة؟ فبفضل كلام شفتيك تفاديت مسالك العنيف.","17:5":"ثبت خطواتي في طرقك فلم تزل قدماي.","17:6":"إليك دعوت اللهم، لأنك تستجيب، فأرهف إلي أذنك وأصغ لكلامي.","17:7":"أظهر روعة مراحمك يامن تخلص بيمينك من يلتجئون إليك من مطارديهم.","17:8":"احفظني كحدقة عينك، واسترني بظل جناحيك.","17:9":"احفظني من الأشرار الذين يخربونني، من أعدائي القتلة المحدقين بي.","17:10":"عواطفهم متحجرة لا تشفق. أفواههم تنطق بالكبرياء.","17:11":"حاصرونا من كل جهة، ووطدوا العزم على طرحنا أرضا.","17:12":"الشرير كأسد متلهف للافتراس، وكالشبل الكامن في مخبئه.","17:13":"قم يارب تصد له. اصرعه. وبسيفك نج نفسي من الشرير.","17:14":"أنقذني بيدك يارب من الناس. من أهل الدنيا الذين نصيبهم هو في هذه الحياة. أنت تملأ بطونهم من خيراتك المخزونة، فيشبع أبناؤهم، ويورثون أولادهم ما يفضل عنهم.","17:15":"أما أنا فبالبر أشاهد وجهك. أشبع، إذا استيقظت، من بهاء طلعتك.","18:1":"أحبك يارب، يا قوتي.","18:2":"الرب صخرتي وحصني ومنقذي. إلهي صخرتي به أحتمي. ترسي وركن خلاصي، وقلعتي الحصينة.","18:3":"أدعو الرب الجدير بكل حمد فيخلصني من أعدائي.","18:4":"قد أحدقت بي حبال الموت، وأفزعتني سيول الهلاك.","18:5":"حاقت بي حبال الهاوية، وأطبقت علي فخاخ الموت.","18:6":"في ضيقي دعوت الرب وصرخت إلى إلهي، فسمع صوتي من هيكله، وصعد صراخي أمامه، بل دخل أذنيه.","18:7":"عندئذ ارتجت الأرض وتزلزلت. ارتجفت أساسات الجبال واهتزت، لأن الرب غضب.","18:8":"نفث أنفه دخانا، وانقذفت نار آكلة من فمه، وكأنها جمر ملتهب.","18:9":"طأطأ السماوات ونزل، فكانت الغيوم المتجهمة تحت قدميه.","18:10":"امتطى مركبة من ملائكة الكروبيم، وطار مسرعا على أجنحة الرياح.","18:11":"جعل الظلمة ستارا له، وصار ضباب المياه وسحب السماء الداكنة مظلته المحيطة به.","18:12":"من بهاء طلعته عبرت السحب أمامه. حدثت عاصفة برد وبرق كالجمر الملتهب.","18:13":"أرعد الرب في السماوات، أطلق العلي صوته فانهمر برد، واندلعت نار!","18:14":"أطلق سهامه فبدد أعدائي، وأرسل بروقه فأزعجهم.","18:15":"ظهرت مجاري المياه العميقة، وانكشفت أسس المسكونة من زجرك يارب، ومن أنفك اللافحة.","18:16":"مد الرب يده من العلى وأمسكني، وانتشلني من السيول الغامرة.","18:17":"أنقذني من عدوي القوي، ومن مبغضي، لأنهم كانوا أقوى مني.","18:18":"تصدوا لي في يوم بليتي، فكان الرب سندي،","18:19":"وا قتادني إلى مكان رحيب. أنقذني لأنه سر بي.","18:20":"يكافئني الرب بمقتضى بري ويعوضني حسب طهارة يدي،","18:21":"لأني سلكت دائما في طرق الرب ولم أعص إلهي.","18:22":"جعلت أحكامه دائما نصب عيني، ولم أحد عن فرائضه.","18:23":"وأكون معه كاملا وأصون نفسي من إثمي.","18:24":"فيكافئني الرب وفقا لبري، بحسب طهارة يدي أمام عينيه.","18:25":"مع الرحيم تكون رحيما، ومع الكامل تكون كاملا،","18:26":"ومع الطاهر تكون طاهرا، ومع المعوج تكون معوجا.","18:27":"لأنك أنت تخلص الشعب المتضايق، أما المترفعون فتخفض عيونهم.","18:28":"لأنك أيها الرب إلهي تضيء مصباحي، وتحول ظلامي نورا","18:29":"لأني بك اقتحمت جيشا، وبمعونة إلهي اخترقت أسوارا.","18:30":"ما أكمل طريق الرب! إن كلمته نقية، وهو ترس يحمي جميع الملتجئين إليه.","18:31":"فمن هو إله غير الرب؟ ومن هو صخرة سوى إلهنا؟","18:32":"يشدني الله بحزام من القوة، ويجعل طريقي كاملا،","18:33":"يثبت قدمي كأقدام الإيل ويصعدني على مرتفعاتي الوعرة.","18:34":"يدرب يدي على فن الحرب، فتشد ذراعاي قوسا من نحاس.","18:35":"تجعل أيضا خلاصك ترسا لي، فتعضدني بيمينك، ويعظمني لطفك.","18:36":"وسعت طريقي تحت قدمي، فلم تتقلقل عقباي. أطارد أعدائي فأدركهم، ولا أرجع حتى أبيدهم.","18:37":"","18:38":"أسحقهم فلا يستطيعون النهوض. يسقطون تحت قدمي.","18:39":"تمنطقني بحزام من القوة تأهبا للقتال. تخضع لسلطاني المتمردين علي.","18:40":"يولون الأدبار هربا أمامي. وأفني الذين يبغضونني.","18:41":"يستغيثون ولا مخلص. ينادون الرب فلا يستجيب لهم.","18:42":"فأسحقهم كالغبار في مهب الريح، وأطرحهم مثل الطين في الشوارع.","18:43":"تنقذني من ثورات الشعب، وتجعلني سيدا للأمم، حتى صار شعب لم أكن أعرفه عبدا يخدمني.","18:44":"فما إن يسمعوا أمري حتى يلبوه. الغرباء يتذللون لي","18:45":"الغرباء يخورون، يخرجون من حصونهم مرتعدين.","18:46":"حي هو الرب، ومبارك صخرتي، ومتعال إله خلاصي،","18:47":"الإله المنتقم لي، يخضع الشعوب لسلطاني،","18:48":"منقذي من أعدائي، رافعي على المتمردين علي، ومن الرجل الطاغي تخلصني.","18:49":"لهذا أعترف لك بين الأمم وأرتل لاَسمك.","18:50":"يامانح الخلاص العظيم لملكه، وصانع الرحمة لمسيحه، لداود ونسله إلى الأبد.","19:1":"السماوات تحدث بمجد الله، والفلك يخبر بعمل يديه","19:2":"بذلك تتحادث الأيام أبلغ حديث، وتتخاطب به الليالي.","19:3":"لا يصدر عنها كلام، لكن صوتها يسمع واضحا.","19:4":"انطلق صوتهم إلى الأرض كلها وكلامهم إلى أقاصي العالم. جعل للشمس مسكنا فيها،","19:5":"وهي مثل العريس الخارج من مخدعه، كالعداء المبتهج للسباق في الطريق.","19:6":"تنطلق من أقصى السموات، وتدور إلى أقاصيها، ولا شيء يحتجب من حرها.","19:7":"شريعة الرب كاملة تنعش النفس. شهادة الرب صادقة تجعل الجاهل حكيما.","19:8":"وصايا الرب مستقيمة تفرح القلب. أمر الرب نقي ينير العينين.","19:9":"مخافة الرب طاهرة ثابتة إلى الأبد، وأحكام الرب حق وعادلة كلها.","19:10":"إنها أشهى من الذهب النقي، وهي أحلى من العسل بل القطر السائل من أقراص الشهد.","19:11":"عبدك يهتدي بها، وفي صونها ثواب عظيم.","19:12":"من يتنبه إلى سهواته؟ من الخطايا الخفية خلصني،","19:13":"ومن الكبائر أيضا احفظ عبدك، ولا تدعها تتسلط علي. عندئذ أكون كاملا وأتبرأ من ذنب عظيم.","19:14":"لتكن أقوال فمي وخواطر قلبي مقبولة لديك يارب، ياصخرتي وفادي.","20:1":"ليستجب لك الرب في يوم ضيقك. ليحرسك اسم إله يعقوب.","20:2":"ليرسل لك عونا من مقدسه، وأزرا من صهيون.","20:3":"ليتذكر جميع تقدماتك، ويتقبل محرقاتك.","20:4":"ليعطك بغية قلبك، ويتمم لك كل مقاصدك.","20:5":"نهتف مبتهجين بخلاصك، وباسم إلهنا نرفع رايتنا، ليحقق لك الرب كل ملتمسك.","20:6":"الآن أدركت أن الرب يخلص مسيحه، ويستجيب من سماواته المقدسة، بقدرة يمينه المخلصة.","20:7":"يتكل هؤلاء على مركبات الحرب، وأولئك على الخيل. أما نحن فنتكل على اسم الرب إلهنا.","20:8":"هم خروا وسقطوا، أما نحن فنهضنا وانتصبنا.","20:9":"خلص يارب! ليستجب الملك حين ندعوه.","21:1":"رب بقوتك يفرح الملك، وما أعظم بهجته بخلاصك!","21:2":"لقد وهبته بغية قلبه ولم تحرمه من طلبة شفتيه.","21:3":"بادرته ببركات الخير، ووضعت على رأسه تاجا من الذهب النقي!","21:4":"طلب منك الحياة فوهبتها له، إذ أطلت عمره إلى أبد الدهور.","21:5":"عظيم مجده بفضل خلاصك، بالعزة والبهاء كللته.","21:6":"لأنك جعلته أكثر المباركين إلى الأبد. تغمره بفيض الفرح في حضرتك.","21:7":"لأن الملك يتوكل على الرب، وبنعمة العلي لا يتزعزع.","21:8":"يدك حتما تنال جميع أعدائك، ويمناك حقا تظفر بمبغضيك.","21:9":"حين يتجلى وجهك تحرقهم كما بتنور مشتعل. تلتهمهم في غضبك فتأكلهم النار.","21:10":"تبيد ذريتهم من الأرض ونسلهم من بين بني آدم.","21:11":"لقد تآمروا للإساءة إليك، ودبروا مكيدة شريرة لم يفلحوا فيها.","21:12":"لأنك تجعلهم يدبرون للهرب، عندما تشد وتر القوس نحو وجوههم.","21:13":"ارتفع يارب بقوتك، فنترنم ونتغنى بقدرتك.","22:1":"إلهي، إلهي، لماذا تركتني؟ لماذا تباعدت عن خلاصي وعن سماع صوت تنهداتي؟","22:2":"إلهي، أصرخ إليك مستغيثا في النهار فلا تجيبني، وفي الليل فلا راحة لي،","22:3":"مع أنك أنت القدوس الذي أقمت عرشك في وسط شعبك الذي يسبحك.","22:4":"عليك اتكل آباؤنا، وبك وثقوا، وأنت قد نجيتهم.","22:5":"إليك صرخوا فنجوا، وعليك اتكلوا فلم يخزوا.","22:6":"أما أنا فدودة لا إنسان. عار في نظر البشر، ومنبوذ في عيني شعبي.","22:7":"جميع الذين يرونني يستهزئون بي، يفتحون شفاههم علي بالباطل، ويهزون رؤوسهم قائلين:","22:8":"سلم إلى الرب أمره، فلينجده. لينقذه مادام قد سر به».","22:9":"أنت أخرجتني من الرحم. أنت جعلتني أنام مطمئنا وأنا مازلت على صدر أمي.","22:10":"أنت متكلي من قبل ميلادي، فأنت إلهي منذ كنت جنينا.","22:11":"لا تقف بعيدا عني، لأن الضيق قريب ولا معين لي.","22:12":"حاصرني أعداء أقوياء، كأنهم ثيران باشان القوية.","22:13":"فغروا علي أشداقهم كأنهم أسود مفترسة مزمجرة.","22:14":"صارت قوتي كالماء، وانحلت عظامي. صار قلبي كالشمع، وذاب في داخلي.","22:15":"جفت نضارتي كقطعة الفخار، والتصق لساني بحنكي. إلى تراب الأرض تضعني.","22:16":"أحاط بي الأدنياء. جماعة من الأشرار طوقتني. ثقبوا يدي ورجلي.","22:17":"صرت لهزالي أحصي عظامي، وهم يراقبونني ويحدقون في.","22:18":"يتقاسمون ثيابي فيما بينهم، وعلى لباسي يلقون قرعة.","22:19":"يارب، لا تتباعد عني. ياقوتي أسرع إلى نجدتي.","22:20":"أنقذ من السيف نفسي، ومن مخالب الأدنياء حياتي.","22:21":"خلصني من فم الأسد، ومن بين قرون الثيران الوحشية استجب لي.","22:22":"أعلن اسمك لإخوتي، وأسبحك في وسط الجماعة.","22:23":"سبحوا الرب ياخائفيه. مجدوه ياجميع نسل يعقوب، واخشوه ياجميع ذرية إسرائيل.","22:24":"فإنه لم يحتقر بؤس المسكين، ولا حجب عنه وجهه، بل استجاب له عندما صرخ إليه.","22:25":"أنت تلهمني تسبيحك في وسط الجماعة العظيمة، فأوفي بنذوري أمام جميع خائفيه.","22:26":"يأكل الودعاء ويشبعون، وطالبو الرب يسبحونه. تحيا قلوبكم إلى الأبد.","22:27":"تتذكر جميع أقاصي الأرض وترجع إلى الرب، وتتعبد أمامك جميع قبائل الأمم.","22:28":"لأن الملك للرب، وهو يتسلط على الأمم.","22:29":"جميع عظماء الأرض يحتفلون ويسجدون. ينحني أمامه الهابطون إلى التراب والفانون،","22:30":"يتعبد نسلهم لله، ويتحدثون عن الرب للجيل الآتي.","22:31":"يأتون ويخبرون ببره وبمعجزاته شعبا لم يولد بعد.","23:1":"الرب راعي فلست أحتاج إلى شيء.","23:2":"في مراع خضراء يربضني، وإلى مياه هادئة يقودني.","23:3":"ينعش نفسي ويرشدني إلى طرق البر إكراما لاَسمه.","23:4":"حتى إذا اجتزت وادي ظلال الموت، لا أخاف سوءا لأنك ترافقني. عصاك وعكازك هما معي يشددان عزيمتي.","23:5":"تبسط أمامي مأدبة على مرأى من أعدائي. مسحت بالزيت رأسي، وأفضت كأسي.","23:6":"إنما خير ورحمة يتبعانني طوال حياتي، ويكون بيت الرب مسكنا لي مدى الأيام.","24:1":"للرب الأرض وكل ما فيها. له العالم، وجميع الساكنين فيه.","24:2":"لأنه هو أسس الأرض على البحار، وثبتها على الأنهار.","24:3":"من يحق له أن يصعد إلى جبل الرب، ويقف في بيته المقدس؟","24:4":"إنه صاحب اليدين الطاهرتين والقلب النقي. ذاك الذي لا يحمل نفسه على الباطل، ولا يحلف منافقا.","24:5":"يتلقى البركة من الرب، والبر من عند الله مخلصه.","24:6":"هذا هو الجيل الساعي وراء الرب، الطالب وجهك ياإله يعقوب.","24:7":"ارفعي رؤوسك أيتها الأبواب، وارتفعي أيتها المداخل الأبدية، فيدخل ملك المجد.","24:8":"من هو ملك المجد هذا؟ إنه الرب القدير الجبار، الرب الجبار في القتال.","24:9":"ارفعي رؤوسك أيتها الأبواب، ارفعيها أيتها المداخل الأبدية، فيدخل ملك المجد","24:10":"من هو ملك المجد هذا؟ إنه رب الجنود، هو ملك المجد.","25:1":"إليك أيها الرب أرفع نفسي.","25:2":"عليك ياإلهي توكلت فلا تخزني، ولا تدع أعدائي يشمتون بي.","25:3":"فإن كل من يرجوك لن يخيب. أما الغادرون بغيرهم من غير علة، فسيخزون.","25:4":"يارب عرفني طرقك، علمني سبلك.","25:5":"دربني في حقك وعلمني، فإنك أنت الإله مخلصي، وإياك أرجو طوال النهار.","25:6":"رب، اذكر مراحمك وإحساناتك لأنها منذ الأزل.","25:7":"لا تذكر خطايا صباي التي ارتكبتها، ولا معاصي، بل اذكرني وفقا لرحمتك ومن أجل جودتك يارب.","25:8":"الرب صالح ومستقيم لذلك يهدي الضالين الطريق.","25:9":"يدرب الودعاء في سبل الحق ويعلمهم طريقه.","25:10":"مسالك الرب كلها رحمة وحق لمن يحفظون عهده وشهاداته.","25:11":"فمن أجل اسمك أيها الرب اصفح عن إثمي فإنه عظيم.","25:12":"من هو الإنسان الذي يخاف الرب؟ إياه يدرب في الطريق التي يختارها له،","25:13":"فتنعم نفسه في الخير وتمتلك ذريته الأرض.","25:14":"يطلع الرب خائفيه على مقاصده الخفية، ويتعهد تعليمهم.","25:15":"تتجه عيناي دائما نحو الرب، لأنه يحرر رجلي من فخ الشرير.","25:16":"التفت نحوي وارحمني، فأنا وحيد ومسكين.","25:17":"قد تكاثرت متاعب قلبي، فأنقذني من شدائدي.","25:18":"انظر إلى مذلتي ومعاناتي، واصفح عن جميع خطاياي.","25:19":"انظر كيف تكاثر علي أعدائي وهم يبغضونني ظلما.","25:20":"صن نفسي وأنقذني، ولا تدعني أخيب، فإني عليك توكلت.","25:21":"يحفظني الكمال والاستقامة، لأني إياك انتظرت.","25:22":"افد إسرائيل ياالله من جميع ضيقاته.","26:1":"رب أظهر براءتي لأني قد سلكت بكمالي، وعليك توكلت فلا أتزعزع","26:2":"افحصني أيها الرب واختبرني. امتحن دخائلي وقلبي،","26:3":"لأن رحمتك نصب عيني، وقد سلكت في حقك.","26:4":"لم أجالس أهل الباطل ومع المنافقين لا أشترك.","26:5":"بل أبغضت معشر فاعلي الإثم، ولم أجلس مع الأشرار.","26:6":"أغسل يدي عربون براءتي وأنضم إلى المجتمعين حول مذبحك يارب.","26:7":"مترنما بصوت الحمد وأحدث بأعمالك العجيبة كلها.","26:8":"رب، قد أحببت الإقامة في بيتك، حيث يحل مجدك.","26:9":"فلا تجمع نفسي مع الخاطئين، ولا حياتي مع سافكي الدم،","26:10":"الذين أيديهم ملوثة بالسوء، ويمينهم ملأى بالرشوة.","26:11":"أما أنا فبكمالي أسلك، فافدني وتحنن علي.","26:12":"قدماي منتصبتان على طريق مستوية، وأرنم للرب جهرا في محافل العبادة.","27:1":"الرب نوري وخلاصي، ممن أخاف؟ الرب حصن حياتي ممن أرتعب؟","27:2":"عندما هجم فاعلو الإثم، خصومي وأعدائي، ليلتهموا لحمي، تعثروا وسقطوا.","27:3":"إن اصطف ضدي جيش، لا يخاف قلبي. إن نشبت علي حرب، أظل في ذلك مطمئنا.","27:4":"أمرا واحدا طلبت من الرب وإياه فقط ألتمس: أن أقيم في بيت الرب كل أيام حياتي، لأشاهد جمال الرب وأتأمل في هيكله.","27:5":"لأنه يحميني في يوم الشر تحت سقف بيته ويحرسني آمنا في خباء خيمته. إذ على صخرة عالية يرفعني.","27:6":"حينئذ أفتخر على أعدائي المحيطين بي، وأقدم له في خيمته ذبائح هتاف، فأغني بل أرنم حمدا للرب.","27:7":"اسمع يارب ندائي لأني بملء صوتي أدعوك! ارحمني واستجب لي.","27:8":"قلت: اطلبوا وجهي! فوجهك يارب أطلب.","27:9":"لا تحجب وجهك عني. لا تطرد بغضب عبدك، فطالما كنت عوني. لا ترفضني ولا تهجرني ياالله مخلصي.","27:10":"إن أبي وأمي قد تركاني، لكن الرب يتعهدني برعايته.","27:11":"علمني يارب طريقك، وقدني في طريق مستقيمة لئلا يشمت بي أعدائي.","27:12":"لا تسلمني إلى مرام مضايقي، لأنه قد قام علي شهود زور ينفثون الظلم في وجهي.","27:13":"غير أني قد آمنت بأن أرى جود الرب في أرض الأحياء.","27:14":"انتظر الرب. تقو وليتشجع قلبك. وانتظر الرب دائما.","28:1":"يارب إليك أصرخ، فلا تتصامم عني ياصخرتي، لئلا أكون، إذا سكت عني، مثل المنحدرين إلى الهاوية.","28:2":"استمع صوت تضرعي عندما أستغيث بك، رافعا يدي نحو محراب قداستك.","28:3":"لا تطرحني مع الأشرار وفاعلي الإثم، الذين يظهرون الود لأصحابهم، وهم يكنون لهم الشر في قلوبهم.","28:4":"جازهم وفقا لفعلهم وشر أعمالهم. أعطهم ما يستحق صنيع أيديهم، ورد عليهم جزاءهم.","28:5":"ولأنهم لا يبالون بأفعال الرب ولا بصنيع يديه، فإنه يدمرهم ولا يعيد بناءهم.","28:6":"مبارك الرب فقد سمع صوت تضرعي.","28:7":"الرب قوتي وترسي. عليه اتكل قلبي، فنلت الغوث. لذلك يبتهج قلبي وأحمده بنشيدي.","28:8":"الرب قوة شعبه، وهو حصن خلاص مسيحه.","28:9":"خلص يارب شعبك وبارك ميراثك. كن راعيا لهم واحملهم إلى الأبد.","29:1":"قدموا للرب ياأبناء الله، قدموا للرب مجدا وعزا.","29:2":"قدموا للرب مجدا لاَسمه. اسجدوا للرب بثوب الإجلال والقداسة.","29:3":"هوذا صوت الرب يدوي فوق الميا ه. إله المجد أرعد. مجد الرب فوق المياه الغزيرة.","29:4":"صوت الرب قوي جدا. صوت الرب يفيض بالجلال.","29:5":"صوت الرب يكسر شجر الأرز. نعم، إن الرب يكسر أرز لبنان.","29:6":"فيجعل لبنان يفر كالعجل، وجبل حرمون يقفز كالثور الوحشي الفتي.","29:7":"صوت الرب يقدح وميض برق،","29:8":"صوت الرب يزلزل البرية، ويزلزل الرب برية قادش،","29:9":"صوت الرب يجعل الوعول تلد قبل الأوان، ويحول الغابات إلى عراء، وفي هيكله الكل يهتف: مجدا.","29:10":"جلس الرب ملكا فوق الطوفان، ويتربع على عرشه إلى الأبد.","29:11":"الرب يعطي شعبه عزا. الرب يبارك شعبه بالسلام.","30:1":"أمجدك يارب لأنك انتشلتني ولم تجعل أعدائي يشمتون بي.","30:2":"يارب إلهي استغثت بك فشفيتني","30:3":"يارب، أنت انتشلت نفسي من شفا الهاوية. وأنقذتني من بين المنحدرين إلى عالم الأموات.","30:4":"ياأتقياء الرب رنموا له، وارفعوا الشكر لاسمه المقدس،","30:5":"فإن غضبه يدوم للحظة، أما رضاه فمدى الحياة. يبقى البكاء لليلة، أما في الصباح فيعم الابتهاج.","30:6":"وأنا قلت في أثناء طمأنينتي: لا أتزعزع أبدا.","30:7":"أنت يارب قد وطدت برضاك قوتي كالجبل الراسخ، لكن حين حجبت وجهك عني ارتعبت.","30:8":"يارب إليك صرخت، وإليك ياسيدي تضرعت.","30:9":"ماذا يجديك موتي ونزولي إلى القبر؟ أيستطيع ترابي أن يحمدك أو يحدث بأمانتك؟","30:10":"اسمعني يارب، وارحمني. كن معينا لي.","30:11":"حولت نوحي إلى رقص. خلعت عني مسح الحداد وكسوتني رداء الفرح.","30:12":"لتترنم لك نفسي ولا تسكت، يارب إلهي إلى الأبد أحمدك.","31:1":"يارب، إليك التجأت فلا تدعني أخيب مدى الدهر. بعدلك نجني.","31:2":"أدر أذنك نحوي وأنقذني سريعا. كن لي صخرة تحميني ومعقلا حصينا يخلصني،","31:3":"إذ إنك صخرتي وقلعتي. ومن أجل اسمك تقودني وتهديني.","31:4":"أطلقني من الشبكة التي أخفاها الأشرار لي، لأنك أنت ملجأي.","31:5":"في يدك أستودع روحي. فديتني أيها الرب إله الحق.","31:6":"لقد أبغضت المتعبدين للأصنام الباطلة. أما أنا فعلى الرب توكلت.","31:7":"أفرح وأبتهج برحمتك لأنك قد نظرت إلى مذلتي، وعرفت ألم نفسي المبرح.","31:8":"لم تسلمني إلى قبضة العدو بل أوقفتني في أرض فسيحة.","31:9":"ارحمني يارب فأنا في ضيق: كلت عيناي غما، واعتلت نفسي ودخيلتي أيضا.","31:10":"لأن حياتي قد فنيت بالحزن وسني حياتي بالتنهد. خارت قواي من قصاص إثمي.","31:11":"صرت محتقرا من كل أعدائي ومصدر رعب لجيراني. الذين يرونني في الشارع يتهربون مني.","31:12":"صرت منسيا كما لو كنت ميتا، وأصبحت كإناء محطم،","31:13":"لأني سمعت المذمة من كثيرين، حتى بات الخوف يطوقني، إذ يتآمرون جميعا علي، عازمين على قتلي.","31:14":"غير أني يارب عليك توكلت، وقلت: أنت إلهي،","31:15":"آجالي في يدك. نجني من يد أعدائي ومن مطاردي.","31:16":"ليشرق وجهك على عبدك وخلصني برحمتك.","31:17":"لا تدعني يارب أخزى، فإني دعوتك. ليخز الأشر ار ولينزلوا إلى هوة الموت ويسكتوا إلى الأبد.","31:18":"لتخرس الشفاه الكاذبة، الناطقة بكبرياء وازدراء ووقاحة على الصديق.","31:19":"يارب، ما أعظم صلاحك الذي ذخرته لخائفيك، وأظهرته للواثقين بك على مرأى جميع البشر،","31:20":"فإنك تصونهم في خباء حضرتك، في مأمن من مؤامرات الناس. في خيمة واقية تحرسهم من لدغات ألسن خصومهم.","31:21":"مبارك الرب لأنه أحاطني برحمته العجيبة وكأني في مدينة محصنة.","31:22":"تسرعت في رعبي وقلت: «قد تخلى الرب عني» ولكنك سمعت صوت تضرعي عندما استغثت بك.","31:23":"أحبوا الرب ياجميع أتقيائه، فإن الرب يحفظ الأمناء، ويجازي بعدله المتكبرين أشد الجزاء.","31:24":"لتتقو ولتتشجع قلوبكم ياجميع المنتظرين الرب.","32:1":"طوبى للذي غفرت آثامه وسترت خطاياه.","32:2":"طوبى للرجل الذي لا يحسب له الرب خطيئة، وليس في روحه غش.","32:3":"حين سكت عن الاعتراف بالذنب بليت عظامي في تأوهي النهار كله،","32:4":"فقد كانت يدك ثقيلة الوطأة علي نهارا وليلا، حتى تحولت نضارتي إلى جفاف حر الصيف","32:5":"أعترف لك بخطيئتي، ولا أكتم إثمي. قلت: أعترف للرب بمعاصي، حقا صفحت عن إثم خطيئتي","32:6":"لهذا ليعترف لك كل تقي بخطاياه وقتما يجدك فلاَ تبلغ إليه سيول التجارب الطامية.","32:7":"أنت ستر لي، في الضيق تحرسني. بترانيم بهجة النجاة تطوقني.","32:8":"يقول الرب: أعلمك وأرشدك الطريق التي تسلكها. أنصحك. عيني ترعاك.","32:9":"لا تكونوا بلا عقل كالحصان والبغل؛ الذي لا يطيع إلا إذا ضبط باللجام وقيد بالحبل.","32:10":"كثير ة هي أوجاع الأشرار. أما الواثق بالرب فالرحمة تحيط به.","32:11":"افرحوا بالرب أيها الأبرار وابتهجوا. اهتفوا ياجميع المستقيمي القلوب.","33:1":"سبحوا الرب أيها الأبرار، فإن الحمد يليق بالمستقيمين.","33:2":"اشكروا الرب على العود، رنموا له بربابة ذات عشرة أوتار.","33:3":"اعزفوا أمهر عزف مع الهتاف، رنموا له ترنيمة جديدة.","33:4":"فإن كلمة الرب مستقيمة وهو يصنع كل شيء بالأمانة.","33:5":"يحب البر والعدل. ورحمته تغمر الأرض.","33:6":"بكلمة من الرب صنعت السماوات وبنسمة فمه كل مجموعات الكواكب.","33:7":"يجمع البحار ككومة واللجج في أهراء.","33:8":"لتخف الرب الأرض كلها، وليوقره جميع سكان العالم.","33:9":"قال كلمة فكان. وأمر فصار!","33:10":"الرب أحبط مؤامرة الأمم. أبطل أفكار الشعوب.","33:11":"أما مقاصد الرب فتثبت إلى الأبد، وأفكار قلبه تدوم مدى الدهور.","33:12":"طوبى للأمة التي الرب إلهها، وللشعب الذي اختاره ميراثا له:","33:13":"ينظر الرب من السموات فيرى بني البشر أجمعين.","33:14":"ومن مقام سكناه يراقب جميع سكان الأرض.","33:15":"فهو جابل قلوبهم جميعا والعليم بكل أعمالهم.","33:16":"لا يخلص الملك بالجيش العظيم، ولا الجبار بشدة القوة.","33:17":"باطلا يرجو النصر من يتكل على الخيل، فإنها لا تنجي رغم قوتها.","33:18":"هوذا عين الرب على خائفيه، المتكلين على رحمته،","33:19":"لينقذ نفوسهم من الموت ويستحييهم في المجاعة.","33:20":"أنفسنا تنتظر الرب. عوننا وترسنا هو.","33:21":"به تفرح قلوبنا، لأننا على اسمه القدوس توكلنا.","33:22":"لتكن يارب رحمتك علينا بمقتضى رجائنا فيك.","34:1":"أبارك الرب في كل حين. تسبيحه دائما في فمي.","34:2":"تفتخر نفسي بالرب، فيسمعني الودعاء ويفرحون.","34:3":"مجدوا الرب معي، ولنعظم اسمه معا.","34:4":"التمست الرب فأجابني، وأنقذني من كل مخاوفي.","34:5":"الذين تطلعوا إليه استناروا، ولم تخجل وجوههم قط.","34:6":"هذا المسكين استغاث، فسمعه الرب وأنقذه من جميع ضيقاته.","34:7":"ملاك الرب يخيم حول خائفيه، وينجيهم.","34:8":"ذوقوا وانظروا ما أطيب الرب. طوبى للرجل المتوكل عليه.","34:9":"اتقوا الرب ياقديسيه، لأنه ليس عوز لمتقيه.","34:10":"تحتاج الأشبال وتجوع، وأما طالبو الرب فلا يعوزهم شيء من الخير.","34:11":"تعالوا أيها البنون وأصغوا إلي، فأعلمكم مخافة الرب.","34:12":"فمن أراد أن يتمتع بحياة سعيدة وأيام طيبة،","34:13":"فليمنع لسانه عن الشر وشفتيه عن كلام الغش","34:14":"ليتحول عن الشر ويفعل الخير. ليطلب السلام ويسع للوصول إليه","34:15":"لأن الرب يرعى الأبرار بعنايته ويستجيب إلى دعائهم.","34:16":"ولكن يقف ضد الذين يعملون الشر ليستأصل من الأرض ذكرهم.","34:17":"يستغيث الأبرار، فيسمع لهم الرب وينقذهم من جميع ضيقاتهم.","34:18":"الرب قريب من كسيري القلب، ويخلص مسحوقي الروح.","34:19":"ما أكثر مصائب الصديق، ولكن من جميعها ينقذه الرب.","34:20":"يحفظ عظامه كلها، فلا تكسر واحدة منها.","34:21":"الشر يميت الشرير، والذين يبغضون الصديق يعاقبون.","34:22":"الرب يفدي نفوس عبيده، وكل من اعتصم به ينجو.","35:1":"يارب كن خصما لمن يخاصمونني، وحارب الذين يحاربونني.","35:2":"تقلد الترس والدرع وهب لنجدتي.","35:3":"جرد رمحا وتصد لمطاردي، وقل لنفسي: خلاصك أنا.","35:4":"ليخز وليخجل الساعون إلى قتلي. لينهزم ويخجل المتواطئون على أذيتي.","35:5":"ليكونوا مثل ذرات التبن في مهب الريح. وليدحرهم ملاك الرب.","35:6":"لتكن طريقهم مظلمة وزلقة، وليتعقبهم ملاك الرب.","35:7":"فإنهم من غير سبب أخفوا لي شبكة فوق الهوة، ومن غير علة حفروا لي حفرة.","35:8":"ليطبق الهلاك فجأة على عدوي، ولتمسك به الشبكة التي أخفاها، فيهلك فيها.","35:9":"أما نفسي فتفرح بالرب وتبتهج بخلاصه.","35:10":"جميع عظامي تقول: يارب من مثلك، المخلص المسكين ممن هو أقوى منه ومنقذ الفقير والبائس من يد ناهبه؟","35:11":"يقوم علي شهود زور يتهمونني ظلما بما لا أعلم.","35:12":"يجازونني عن الخير شرا إتعاسا لنفسي.","35:13":"أما أنا فقد لبست المسح حزنا على مرضهم، وأذللت نفسي بالصوم، ولكن صلاتي كانت ترتد إلى صدري من غير استجابة.","35:14":"لقد عاملت كلا منهم كأنه صديقي وأخي، وأطرقت حزنا كمن يندب أمه.","35:15":"وأما هم فشمتوا فرحا عند سقطتي، وتجمعوا علي شاتمين، وشرع غرباء لا أعرفهم يضربونني. مزقوني ولم يرتدعوا.","35:16":"كفجار ماجنين مجتمعين حول وليمة حرقوا علي أسنانهم.","35:17":"ياسيد، حتى متى تظل متفرجا؟ نج نفسي من مهالكهم وخلص حياتي من بين الأشبال.","35:18":"أشكرك في جماعة العابدين، وأحمدك في وسط حشود كثيرة.","35:19":"لا يشمت بي أعدائي بحجة باطلة، ولا يتغامز مبغضي علي، بغير علة.","35:20":"فإنهم لا يتكلمون بالسلام، ولكنهم يتآمرون بمكر للإيقاع بالمسالمين الساكنين في الأرض.","35:21":"فغروا علي أفواههم على وسعها، وقالوا: «هه! هه! قد رأينا بأعيننا (ما فعلت)»","35:22":"قد رأيت يارب ذلك. لا تسكت ولا تبتعد عني.","35:23":"انهض ياإلهي وسيدي واستيقظ لإحقاق حقي وإنصاف دعواي.","35:24":"احكم ببراءتي يارب إلهي حسب عدلك، ولا تدعهم يشمتون بي.","35:25":"لئلا يقولوا في أنفسهم: «هه! قد ظفرنا به» أو يقولوا: «قد ابتلعناه!»","35:26":"ليخز ويخجل جميع الشامتين بي في مصيبتي. ليرتد المتعظمون علي لباس الخزي والعار.","35:27":"وليهتف المسرورون ببري بهتاف الفرح والابتهاج، قائلين في كل حين: «ليتمجد الرب الذي يبتهج بنجاح عبده».","35:28":"فيذيع لساني عدلك، ويتر نم بحمدك النهار كله.","36:1":"ينبئني قلبي في داخلي بمعصية الشرير، الذي لا يرتدع خوفا من الله.","36:2":"فإنه يتملق نفسه (ليقنعها) أن خطيئته الممقوتة لن تكتشف وتدان.","36:3":"كلام فمه إثم ونفاق، وقد كف عن التعقل لأجل عمل الخير.","36:4":"يتفكر في الباطل على سريره ليلا. ويسلك في سبيل السوء لا يستنكر الشر.","36:5":"يارب، إن رحمتك في السماوات، وأمانتك تبلغ الغيوم.","36:6":"عدلك ثابت مثل الجبال الشامخة، وأحكامك كالغور السحيق. وأنت يارب تحفظ الناس والبهائم جميعا.","36:7":"اللهم، ما أثمن رحمتك، فإن بني البشر يحتمون في ظل جناحيك.","36:8":"يرتوون من خيرات بيتك، ومن نهر نعمك تسقيهم.","36:9":"لأن عندك نبع الحياة، وبنورك نرى النور.","36:10":"أدم رحمتك لعارفيك، وعدلك لذوي القلوب المستقيمة.","36:11":"لا تدع قدم المتكبر تبلغني، ويد الأشرار تزحزحني.","36:12":"هناك سقط فاعلو الإثم، طرحوا، عجزوا عن النهوض.","37:1":"لا يقلقك أمر الأشرار، ولا تحسد فاعلي الإثم،","37:2":"فإنهم مثل الحشيش سريعا يذوون، وكالعشب الأخضر يذبلون.","37:3":"توكل على الرب واصنع الخير. اسكن في الأرض (مطمئنا) وراع الأمانة.","37:4":"ابتهج بالرب فيمنحك بغية قلبك.","37:5":"سلم للرب طريقك وتوكل عليه فيتولى أمرك.","37:6":"يظهر براءتك كالنور، وحقك ظاهرا كشمس الظهيرة.","37:7":"اسكن أمام الرب وانتظره بصبر، ولا تغر من الذي ينجح في مسعاه، بفضل مكائده.","37:8":"كف عن الغضب، وانبذ السخط، ولا تتهور لئلا تفعل الشر.","37:9":"لأن فاعلي الشر يستأصلون. أما منتظرو الرب فإنهم يرثون خيرات الأرض.","37:10":"فعما قليل (ينقرض) الشرير، إذ تطلبه ولا تجده.","37:11":"أما الودعاء فيرثون خيرات الأرض ويتمتعون بفيض السلام.","37:12":"يكيد الشرير كثيرا للصديق ويصر عليه بأسنانه.","37:13":"ولكن الرب يضحك منه لأنه يرى أن يوم عقابه آت.","37:14":"قد سل الأشرار سيوفهم ووتروا أقواسهم ليصرعوا المسكين والفقير، ليقتلوا السالكين طريقا مستقيمة.","37:15":"لكن سيوفهم ستخترق قلوبهم وتتكسر أقواسهم.","37:16":"الخير القليل الذي يملكه الصديق أفضل من ثروة أشرار كثيرين،","37:17":"لأن سواعد الأشرار ستكسر، أما الأبرار فالرب يسندهم.","37:18":"الرب عليم بأيام الكاملين، وميراثهم يدوم إلى الأبد.","37:19":"لا يخزون في زمان السوء، وفي أيام الجوع يشبعون.","37:20":"أما الأشرار فيهلكون وأعداء الرب كبهاء المراعي بادوا، انتهوا؛ كالدخان تلاشوا.","37:21":"يقترض الشرير ولا يفي، أما الصديق فيترَأف ويعطي بسخاء.","37:22":"فالذين يباركهم الرب يرثون خيرات الأرض، والذين يلعنهم يستأصلون.","37:23":"الرب يثبت خطوات الإنسان الذي تسره طريقه.","37:24":"إن تعثر لا يسقط، لأن الرب يسنده بيده.","37:25":"كنت صبيا، وأنا الآن شيخ، وما رأيت صديقا متروكا، ولا ذرية له تستجدي خبزا.","37:26":"يترَأف اليوم كله، ويقرض الآخرين. وتكون ذريته بركة لغيرهم.","37:27":"حد عن الشر واصنع الخير، فتسكن مطمئنا إلى الأبد.","37:28":"لأن الرب يحب العدل، ولا يتخلى عن أتقيائه، بل يحفظهم إلى الأبد. أما ذرية الأشرار فتفنى.","37:29":"الصديقون يرثون خيرات الأرض ويسكنون فيها إلى الأبد.","37:30":"فم الصديق ينطق دائما بالحكمة، ويتفوه بكلام الحق","37:31":"شريعة إلهه ثابتة في قلبه، فلا تتقلقل خطواته.","37:32":"يتربص الشرير بالصديق ويسعى إلى قتله.","37:33":"لكن الرب لا يدعه يقع في قبضته، ولا يدينه عند محاكمته.","37:34":"انتظر الرب واسلك دائما في طريقه، فيرفعك لتمتلك الأرض، وتشهد انقراض الأشرار.","37:35":"قد رأيت الشرير مزدهرا وارفا كالشجرة الخضراء المتأصلة في تربة موطنها،","37:36":"ثم عبر ومضى، لم يوجد. فتشت عنه فلم أعثر له على أثر.","37:37":"لاحظ الكامل وانظر المستقيم، فإن نهاية ذلك الإنسان تكون سلاما.","37:38":"أما العصاة فيبادون جميعا. ونهاية الأشرار اندثارهم،","37:39":"لكن خلاص الأبرار من عند الرب، فهو حصنهم في زمان الضيق.","37:40":"يعينهم الرب حقا، وينقذهم من الأشرار، ويخلصهم لأنهم احتموا به.","38:1":"يارب لا توبخني بغضبك، ولا تؤدبني بسخطك،","38:2":"لأن سهامك قد أصابتني وضرباتك قد ثقلت علي.","38:3":"اعتل جسدي لفرط غضبك علي. وبليت عظامي بسبب خطيئتي.","38:4":"طمت آثامي فوق رأسي. وصارت كعبء ثقيل لا طاقة لي على حمله.","38:5":"أنتنت جراحي وسال صديدها بسبب جهالتي.","38:6":"انحنيت والتويت. ودام نحيبي طول النهار.","38:7":"امتلأ داخلي بألم حارق، فلا صحة في جسدي.","38:8":"أنا واهن ومسحوق إلى الغاية، وأئن من أوجاع قلبي الدفينة.","38:9":"أمامك يارب كل تأوهي، وتنهدي مكشوف لديك.","38:10":"خفق قلبي وفارقتني قوتي، واضمحل في نور عيني.","38:11":"وقف أحبائي وأصحابي مستنكفين مني بسبب مصيبتي، وتنحى أقاربي عني.","38:12":"نصب الساعون لقتلي الفخاخ، وطالبو أذيتي توعدوا بدماري، وتآمروا طول النهار للإيقاع بي.","38:13":"أما أنا فقد كنت كأصم، لا يسمع، وكأخرس لا يفتح فاه.","38:14":"كنت كمن لا يسمع، وكمن ليس في فمه حجة.","38:15":"لأني قد وضعت فيك رجائي، وأنت تستجيبني يارب إلهي.","38:16":"قلت: «لا تدعهم يشمتون بي فحالما زلت قدمي تغطرسوا علي»","38:17":"لأني أكاد أتعثر، ووجعي دائما أمام ناظري.","38:18":"أعترف جهرا بإثمي، وأحزن من أجل خطيئتي.","38:19":"أما أعدائي فيفيضون حيوية. تجبروا وكثر الذين يبغضونني ظلما.","38:20":"والذين يجازون الخير بالشر يقاومونني لأني أتبع الصلاح.","38:21":"لا تنبذني يارب. ياإلهي لا تبعد عني.","38:22":"أسرع لنجدتي يارب يامخلصي.","39:1":"قلت: «أحرص على حسن المسلك فلا يخطيء لساني القول. سأكم فمي عن الكلام مادام الشرير أمامي».","39:2":"صمت صمتا. أمسكت حتى عن الخير، فثار وجعي.","39:3":"التهب قلبي في داخلي، وفي تأملي اشتعلت في النار، فأطلقت لساني بالكلام.","39:4":"يارب عرفني متى تكون نهايتي، وكم تطول أيامي فأدرك أنني إنسان زائل.","39:5":"هوذا قد جعلت حياتي قصيرة، وعمري كلا شيء أمامك. كل إنسان حي ليس سوى نفخة!","39:6":"إنما كخيال يتمشى الإنسان، فعبثا يكافح الناس. يجمع الواحد منهم ثروة ولا يدري من يرثها من بعده.","39:7":"والآن، فأي شيء أنتظر يارب؟ إنما فيك رجائي.","39:8":"نجني من جميع معاصي، ولا تجعلني عارا عند الأحمق.","39:9":"صمت. لا أفتح فمي، لأنك أنت فعلت هذا.","39:10":"ارفع عني ضربتك فقد فنيت من صفعة يدك.","39:11":"عندما تؤدب الإنسان بالتوبيخ على الإثم، تتلف بهاءه إتلاف العث. إنما كل إنسان نفخة.","39:12":"يارب اسمع صلاتي. واصغ إلى صراخي، ولا تسكت أمام دموعي، لأني غريب عندك وعابر سبيل كجميع آبائي.","39:13":"حول غضبك عني فأنتعش، قبل أن أموت ويختفي أثري.","40:1":"انتظرت الرب صابرا، فالتفت إلي وسمع صراخ استغاثتي،","40:2":"وانتشلني من هوة الهلاك، من طين المستنقع. وأوقف قدمي على أرض صخرية، فصرت أمشي بخطوات ثابتة.","40:3":"وضع في فمي ترنيمة جديدة، قصيدة تسبيح لإلهنا. يرى ذلك كثيرون فيخافون الرب.","40:4":"طوبى لرجل وضع في الرب ثقته، ولم يلتفت إلى المتكبرين والمنحرفين إلى الكذب.","40:5":"أيها الرب إلهي، ما أكثر أعمالك العجيبة. إن تحدثت عن خططك الرائعة لنا فلن أقدر أن أحصيها. زادت عن أن تعد.","40:6":"لم ترد أو تطلب ذبائح ومحر قات عن الخطيئة، لكنك وهبتني أذنين صاغيتين مطيعتين.","40:7":"عندئذ قلت: «ها أنا أجيء، كما هو مكتوب عني في درج الكتاب:","40:8":"إن مسرتي أن أعمل مشيئتك الصالحة ياإلهي، وشريعتك في صميم قلبي.","40:9":"أعلنت برك وسط جماعة شعبك العظيم، وأنت يارب علمت أنني لم ألجم شفتي.","40:10":"لم أخف برك داخل قلبي، بل أعلنت أمانتك وخلاصك. لم أكتم رحمتك وحقك عن جماعة شعبك العظيم».","40:11":"فأنت يارب لن تمنع مراحمك عني. تنصرني دائما رحمتك وحقك.","40:12":"إن شرورا لا تحصى قد أحاطت بي، وآثامي قد أطبقت علي فأعمتني لأنها أكثر من شعر رأسي، وقلبي قد خذلني.","40:13":"يارب، ارتض أن تنجيني. أسرع يارب لإغاثتي.","40:14":"ليخز وليخجل معا الذين يسعون إلى قتلي. ليدبر وليخز المسرورون بأذيتي.","40:15":"ليذهل خزيا الساخرون مني.","40:16":"وليفرح ويبتهج بك جميع طالبيك، وليقل كل حين محبو خلاصك: «يتعظم الرب».","40:17":"أما أنا فمسكين وبائس. الرب يهتم بي. عوني ومنقذي أنت. فلا تتوان ياإلهي.","41:1":"طوبى للمترفق بالمسكين، فإن الرب ينقذه في يوم الشر.","41:2":"الرب يحفظه ويحييه ويسعده في الأرض، ولا يسلمه إلى مقاصد أعدائه.","41:3":"يعضده الرب على فراش الألم، ويرد عافيته.","41:4":"وأنا قلت: يارب ارحمني! أبريء نفسي لأني قد أخطأت إليك.","41:5":"أعدائي يتآمرون علي بالشر ويقولون: «متى يموت وينقرض اسمه؟»","41:6":"إن أقبل ليراني، يبدي لي نفاقا ويضمر في قلبه شرا يشيعه عني حالما يفارقني.","41:7":"جميع مبغضي يتهامسون علي، ويتآمرون على إيذائي","41:8":"قائلين: «قد اعتراه داء عضال، ولن يقوم من فراشه أبدا».","41:9":"حتى صديقي الملازم لي الذي وثقت به، الآكل من طعامي قد انقلب علي، ورفع علي عقبه.","41:10":"أما أنت يارب فارحمني واشفني، فأجازيهم.","41:11":"قد أدركت أني حظيت برضاك حين (نصرتني) فلم يطلق علي عدوي هتاف الظفر","41:12":"فإنك تدعمني في كمالي، وتقيمني في محضرك إلى الأبد.","41:13":"تبارك الرب إله إسرائيل، من الأزل وإلى الأبد. آمين فآمين.","42:1":"مثلما تشتاق الغزلان إلى جداول المياه، هكذا تشتاق نفسي إليك ياالله .","42:2":"نفسي عطشى إلى الله الإله الحي، فمتى أجيء وأمثل أمام الله؟","42:3":"قد صارت دموعي طعامي الوحيد نهارا وليلا، إذ قيل لي كل يوم: «أين إلهك»؟","42:4":"حين أتأمل في نفسي تعاودني هذه الذكرى: كيف كنت أرافق حشود العابدين المحتفلين بالعيد وأقودهم في الحضور إلى بيت الله، هاتفا معهم فرحا وحمدا.","42:5":"لماذا أنت مكتئبة يانفسي؟ ولماذا أنت قلقة في داخلي؟ ترجي الله، فإني سأظل أحمده، لأنه عوني وإلهي.","42:6":"إلهي، إن نفسي مكتئبة في، لذلك أذكرك من وادي الأردن، ومن جبال حرمون، ومن جبل مصعر.","42:7":"أمواج النكبات توالت علي كما تتوالى مياه شلالاتك.","42:8":"يبدي الرب لي رحمته في النهار، وفي الليل ترافقني ترنيمته، صلاة لإله حياتي.","42:9":"أقول لله صخرتي: «لماذا نسيتني؟ لماذا أطوف نائحا من مضايقة العدو؟","42:10":"لقد عيرني مضايقي وسحقوا عظامي، إذ يقولون لي طول النهار: أين إلهك؟»","42:11":"لماذا أنت مكتئبة يانفسي، ولماذا أنت قلقة؟ ترجي الله ، فإني سأظل أحمده، لأنه عوني وإلهي.","43:1":"ياالله احكم ببراءتي، ودافع عن قضيتي ضد شعب لا يرحم. أنقذني من الغشاش والظالم.","43:2":"لأنك أنت حصني. لماذا رفضتني؟ لماذا أطوف نائحا من مضايقة العدو؟","43:3":"أرسل نورك وحقك فيرشداني، ويأتيا بي إلى جبلك المقدس وإلى مساكنك،","43:4":"فأقبل إلى مذبح الله، إلى الله فرحي وأسبحك بالعود ياإلهي.","43:5":"لماذا أنت مكتئبة يانفسي؟ لماذا أنت قلقة في داخلي؟ ترجي الله فإني سأظل أحمده، لأنه عوني وإلهي.","44:1":"ياالله ، بآذاننا قد سمعنا، وآباؤنا أخبرونا بما عملته في أيامهم القديمة.","44:2":"بيدك اقتلعت الأمم، وغرست آباءنا. حطمت الشعوب وأنميتهم.","44:3":"لم يمتلكوا الأرض بسيفهم ولا بذراعهم خلصوا، ولكن بفضل يمناك وذراعك ونور وجهك، لأنك رضيت عنهم.","44:4":"أنت هو ملكي ياالله ، فأمر بخلاص شعبك.","44:5":"بعونك نطرح خصومنا أرضا، وباسمك ندوس القائمين علينا.","44:6":"فإني لن أتكل على قوسي ولن يخلصني سيفي.","44:7":"فأنت أنقذتنا من مضايقينا وألحقت العار بمبغضينا.","44:8":"بالله نفتخر اليوم كله، ونحمد اسمك إلى الأبد.","44:9":"غير أنك قد رذلتنا وأخجلتنا، ولم تعد ترافق جنودنا إلى الحرب.","44:10":"جعلتنا نتقهقر أمام عدونا. أما مبغضونا فيغنمون لأنفسهم.","44:11":"أسلمتنا كغنم معدة للذبح، وبددتنا بين الأمم.","44:12":"بعت شعبك بلا مال وبثمنهم لم تربح.","44:13":"تجعلنا عارا عند جيراننا، ومثار هزء وسخرية لمن حولنا.","44:14":"تجعلنا مثلا بين الأمم وأضحوكة بين الشعوب.","44:15":"اليوم كله خجلي ماثل أمامي، وخزي وجهي قد غمرني","44:16":"من صوت المعير والمجدف ومرأى العدو المنتقم.","44:17":"هذا كله وقع علينا، فما نسيناك ولا خنا عهدك.","44:18":"لم يرتد قلبنا إلى الوراء، ولا حادت خطواتنا عن طريقك.","44:19":"مع أنك سحقتنا وسط الوحوش، وغمرتنا بظلال الموت.","44:20":"إن كنا قد نسينا اسم إلهنا، وصلينا إلى إله غريب،","44:21":"ألا يعرف الله ذلك وهو علام الغيوب؟","44:22":"ألا أننا من أجلك نعاني الموت طول النهار، وقد حسبنا مثل غنم معدة للذبح.","44:23":"قم يارب. لماذا تتغافى؟ انتبه ولا تنبذنا إلى الأبد.","44:24":"لماذا تحجب وجهك وتنسى مذلتنا وضيقنا؟","44:25":"إن نفوسنا قد انحنت إلى التراب، وبطوننا لصقت بالأرض.","44:26":"هب لنجدتنا وافدنا من أجل رحمتك.","45:1":"فاض قلبي بكلام صالح: إني أخاطب الملك بما قد أنشأته، ولساني فصيح كقلم الكاتب الماهر.","45:2":"أنت أبرع جمالا من كل بني البشر. انسكبت النعمة على شفتيك، لذلك باركك الله إلى الأبد.","45:3":"في جلالك وبهائك تقلد سيفك على فخذك أيها المقتدر،","45:4":"وبجلالك اركب ظافرا لأجل الحق والوداعة والبر، فتقتحم يمينك الأهوال.","45:5":"سهامك مسنونة تخترق أعماق قلوب أعداء الملك، وتسقط الشعوب صرعى تحت قدميك.","45:6":"عرشك ياالله إلى دهر الدهور، وصولجان ملكك عادل ومستقيم.","45:7":"أحببت البر وأبغضت الإثم. من أجل ذلك مسحك الله (ملكا) بدهن الابتهاج أكثر من رفقائك (الملوك).","45:8":"ثيابك كلها معطرة بالمر ودهن اللبان. من قصور العاج صدحت موسيقى الآلات الوترية فأطربتك.","45:9":"أميرات بين حظياتك. جلست الملكة عن يمينك مزينة بذهب أوفير .","45:10":"اسمعي يابنت وانظري، وأرهفي إلي أذنك، وانسي شعبك وبيت أبيك","45:11":"فيشتهي الملك جمالك، لأنه هو سيدك فاسجدي له.","45:12":"بنت صور أغنى الشعوب تسترضيك بهدية.","45:13":"كلها مجد ابنة الملك في قصرها. ثيابها منسوجة بذهب.","45:14":"تزف إلى الملك بحلل مطرزة، ووصيفاتها العذارى يتبعنها قادمات إليك في موكب حافل.","45:15":"يحضرن بفرح وابتهاج. يدخلن إلى قصر الملك.","45:16":"يصبح أبناؤك يوما ملوكا كآبائهم فيتربعون على عروش في كل الأرض.","45:17":"أخلد ذكرى اسمك في كل الأجيال، وتحمدك الشعوب إلى الدهر والأبد.","46:1":"الله لنا ملجأ وقوة، عونه متوافر لنا دائما في الضيقات.","46:2":"لذلك لا نخاف ولو تزحزحت الأرض وانقلبت الجبال إلى قلب البحار.","46:3":"تهيج وتزبد مياهها؛ تتزلزل الجبال من عنف جيشانها.","46:4":"تفرح مدينة الله حيث مساكن العلي بنهر دائم الجريان.","46:5":"الله في وسط المدينة فلن تتزعزع. يعينها الله في الفجر المبكر.","46:6":"ماجت الأمم وهاجت، فتزلزلت الممالك، ولكن ما إن دوى بصوته حتى ذابت الأرض.","46:7":"رب الجنود معنا، ملجأنا إله يعقوب.","46:8":"تعالوا وانظروا أعمال الله الذي صنع عجائب في الأرض","46:9":"يقضي على الحروب في الأرض كلها. يكسر القوس ويشق الرمح، ويحرق المركبات الحربية بالنار.","46:10":"استكينوا واعلموا أني أنا الله ، أتعالى بين الأمم وأتعالى في الأرض.","46:11":"رب الجنود معنا. ملجأنا إله يعقوب.","47:1":"ياجميع الأمم صفقوا بالأيا دي، واهتفوا لله هتاف الابتهاج.","47:2":"لأن الرب علي مخوف، ملك عظيم على كل الأرض.","47:3":"يخضع الشعوب لنا، ويطرح الأمم تحت أقدامنا.","47:4":"يختار لنا ميراثنا، فخر يعقوب الذي أحبه.","47:5":"ارتفع الله وسط الهتاف، ارتفع الرب وسط دوي نفخ البوق.","47:6":"رنموا لله، رنموا. رنموا لملكنا، رنموا.","47:7":"لأن الله هو ملك الأرض كلها. رنموا له قصيدة حمد.","47:8":"ملك الله على الأمم، الله جلس على عرشه المقدس.","47:9":"رؤساء الأمم اجتمعوا مع شعب إله إبراهيم. لأن لله حماة الأرض وهو متعال جدا.","48:1":"ما أعظم الرب وما أجدره بالتسبيح في مدينة إلهنا، في جبل قداسته!","48:2":"جبل صهيون جميل في شموخه، (هو) فرح كل الأرض حتى أقاصي الشمال. هو مدينة الملك العظيم.","48:3":"الله المقيم في قصورها معروف بأنه حصن منيع.","48:4":"هوذا الملوك قد احتشدوا وعبروا معا.","48:5":"رأوا بيت الله فذهلوا. ارتاعوا وفروا.","48:6":"هناك اعترتهم رعدة فتوجعوا كامرأة في مخاضها.","48:7":"تحطم سفن ترشيش بريح شرقية.","48:8":"كما سمعنا رأينا في مدينة رب الجنود، مدينة إلهنا. حقا إن الله يثبتها إلى الأبد.","48:9":"تأملنا ياالله في رحمتك في وسط هيكلك.","48:10":"تسبيحك ياالله مثل اسمك يبلغ أقاصي الأرض. يمينك ملآنة صلاحا.","48:11":"ليفرح جبل صهيون ولتبتهج بنات يهوذا من أجل أحكام قضائك.","48:12":"جولوا في صهيون ودوروا حولها. عدوا أبراجها.","48:13":"تفرسوا في متاريسها وتأملوا قصور ها لتخبروا بها الأجيال القادمة.","48:14":"لأن الله هذا هو إلهنا إلى الدهر والأبد، وهو هادينا حتى الموت.","49:1":"اسمعوا هذا ياجميع الشعوب، أصغوا ياجميع سكان العالم.","49:2":"(اسمعوا) إلي أيها العظماء، الأغنياء والفقراء على السواء.","49:3":"ينطق فمي بالحكمة، وخواطر قلبي بالفهم.","49:4":"أعير أذني لأسمع مثلا، وعلى عزف العود أشرح لغزي.","49:5":"لماذا أخاف في أيام الخطر عندما يحيط بي شر مطاردي؟","49:6":"أولئك المتكلون على ثروتهم، وبوفرة غناهم يفتخرون.","49:7":"لا يقدر أحد أبدا أن يفتدي أخاه أو يقدم لله كفارة عنه.","49:8":"لأن فدية النفوس باهظة يتعذر دفعها مدى الحياة","49:9":"طلبا للخلود على الأرض وتفاديا لرؤية القبر.","49:10":"لكن الحكماء يموتون كما يموت الجاهل والغبي، تاركين ثروتهم لغيرهم.","49:11":"يتوهمون أن بيوتهم خالدة، وأن مساكنهم باقية من جيل إلى جيل، فأطلقوا أسماءهم على أراضيهم (تخليدا لذكرهم).","49:12":"ولكن الإنسان لا يخلد في أبهته. إنه يماثل البهائم التي تباد.","49:13":"هذا هو مصير الجهال الواثقين بأنفسهم، ومصير أعقابهم الذين يستحسنون أقوالهم.","49:14":"يساقون للموت كالأغنام، ويكون الموت راعيهم ويسود المستقيمون عليهم. تبلى صورتهم، وتصير الهاوية مسكنهم.","49:15":"إنما الله يفتدي نفسي من قبضة الهاوية إذ يأخذني إليه.","49:16":"لا تخش إذا اغتنى إنسان، وزاد مجد بيته.","49:17":"فإنه عند موته لا يأخذ معه شيئا، ولا يلحق به مجده إلى قبره.","49:18":"ومع أنه ينعم نفسه بالبركات في أثناء حياته ويطريه الناس إذ أحسن إلى نفسه،","49:19":"إلا أن نفسه ستلحق بآبائه، الذين لا يرون النور إلى الأبد.","49:20":"فالإنسان المتمتع بالكرامة من غير فهم، يماثل البهائم البائدة.","50:1":"الرب الإله القدير تكلم، ودعا الأرض للمحاكمة من مشرق الشمس إلى مغربها.","50:2":"من صهيون الكاملة الجمال أشرق مجد الله.","50:3":"يأتي إلهنا ولا يصمت، تحيط به النار الآكلة والعواصف الثائرة.","50:4":"ينادي السماوات من العلى، والأرض أيضا من تحت لكي يدين شعبه، قائلا:","50:5":"«اجمعوا إلي أتقيائي الذين قطعوا معي عهدا على ذبيحة».","50:6":"فتذيع السماوات عدله لأن الله هو الديان.","50:7":"اسمع ياشعبي فأتكلم. ياإسرائيل إني أشهد عليك: «أنا الله إلهك.","50:8":"لست أوبخك على ذبائحك فإن محرقاتك هي دائما قدامي.","50:9":"فما كنت لآخذ من بيتك ثورا ولا من حظائرك تيسا.","50:10":"لأن جميع حيوانات الغابة ملكي، وكذلك البهائم المنتشرة على ألوف الجبال.","50:11":"أنا عالم بجميع طيور الجبال، وكل مخلوقات البراري هي لي.","50:12":"إن جعت لا ألتمس منك حاجتي لأن لي المسكونة وكل ما فيها.","50:13":"هل آكل لحم الثيران، أو أشرب دم التيوس؟","50:14":"قدم لله ذبائح الحمد وأوف العلي عهودك.","50:15":"ادعني في يوم ضيقك أنقذك فتمجدني».","50:16":"وقال الله للشرير: «بأي حق تحدث بأحكامي، ولماذا تتكلم عن عهدي،","50:17":"وأنت تمقت التأديب ولا تكترث لكلامي؟","50:18":"ترى سارقا فتوافقه، ومع الزناة نصيبك.","50:19":"أطلقت فمك بالشر ولسانك يخترع غشا.","50:20":"تجلس تشهر بأخيك، وعلى ابن أمك تفتري.","50:21":"هذه كلها فعلت وأنا سكت، فظننت أني مثلك. غير أني أوبخك وأصف إثمك أمام عينيك.","50:22":"والآن تنبهوا أيها الناسون الله ، لئلا أمزقكم وليس من ينقذكم.","50:23":"أما من يقدم لي ذبيحة حمد فهو يمجدني، ومن يقوم طريقه أريه خلاص الله».","51:1":"ارحمني ياالله حسب رحمتك، وامح معاصي حسب كثرة رأفتك.","51:2":"اغسلني كليا من إثمي، وطهرني من خطيئتي.","51:3":"فإ نني أقر بمعاصي، وخطيئتي ماثلة أمامي دائما.","51:4":"إليك وحدك أخطأت، والشر قدام عينيك صنعت. لكي تتبرر إذا حكمت وتزكو إذا قضيت.","51:5":"ها إني بالإثم قد ولدت وفي الخطيئة حبلت بي أمي.","51:6":"ها أنت ترغب أن ترى الحق في دخيلة الإنسان، فتعرفني الحكمة في قرارة نفسي.","51:7":"طهرني بالزوفا فأتنقى. اغسلني فأبيض أكثر من الثلج.","51:8":"أسمعني صوت السرور والفرح، فتبتهج عظامي التي سحقتها.","51:9":"احجب وجهك عن خطاياي وامح كل آثامي.","51:10":"قلبا نقيا اخلق في ياالله وروحا مستقيما جدد في داخلي.","51:11":"لا تطردني من حضرتك، ولا تنزع مني روحك القدوس.","51:12":"رد لي بهجتي بخلاصك، وبروح رضية آزرني","51:13":"عندئذ أعلم الأثمة طرقك، فيتوب إليك الخاطئون.","51:14":"أنقذني من سفك الدماء ياالله ، إله خلاصي، فيرنم لساني ببرك.","51:15":"يارب افتح شفتي فيذيع فمي تسبيحك.","51:16":"فإنك لا تسر بذبيحة، وإلا كنت أقدمها. بمحرقة لا ترضى.","51:17":"إن الذبائح التي يطلبها الله هي روح منكسرة. فلا تحتقرن القلب المنكسر والمنسحق ياالله .","51:18":"أحسن إلى صهيون بمقتضى مسرتك. وابن أسوار أورشليم.","51:19":"عندئذ ترضى بذبائح البر، محرقة وتقدمة تامة. حينئذ يقربون على مذبحك عجولا.","52:1":"لماذا تتفاخر بالشر أيها الجبار؟ إن رحمة الله تدوم اليوم كله","52:2":"لسانك يخترع المساويء، ويمارس الغش ويجرح كالموسى المسنونة.","52:3":"أحببت الشر أكثر من الخير، والكذب أكثر من الصدق.","52:4":"أحببت كل كلام مهلك أيها اللسان المنافق.","52:5":"حقا سيدمرك الله إلى الأبد، ويختطفك ويقتلعك من خيمتك، ويستأصلك من أرض الأحياء.","52:6":"فيرى الأبرار ذلك ويخافون؛ يضحكون عليك قائلين:","52:7":"هذا هو الرجل الذي لم يتخذ الله حصنا له، بل اتكل على وفرة غناه واعتز بغوايته.","52:8":"أما أنا فمثل زيتونة خضراء في بيت الله وثقت برحمة الله إلى الدهر والأبد.","52:9":"أحمدك إلى الأبد على ما فعلت، وأنتظر اسمك الصالح في محضر أتقيائك.","53:1":"حدث الجاهل نفسه قائلا: «لا يوجد إله». فسد البشر وارتكبوا المكروهات، وليس بينهم واحد يعمل الصلاح.","53:2":"أشرف الله من السماوات على بني البشر، لينظر هل يوجد بينهم حكيم يطلب الله .","53:3":"فإذا الجميع قد ارتدوا وفسدوا. ليس بينهم من يعمل الصلاح، ليس ولا واحد.","53:4":"أليس لدى فاعلي الإثم معرفة؟ إنهم يأكلون شعبي كمن يأكلون خبزا ويعادون الرب.","53:5":"هناك يدهمهم الرعب حيث لا موجب للرعب، لأنه يبدد عظام أعداء شعبه ويلحق بهم الخزي لأن الله رفضهم.","53:6":"ليت من صهيون خلاص إسرائيل. عندما يرد الله سبي شعبه يفرح يعقوب ويبتهج إسرائيل.","54:1":"ياالله باسمك خلصني، وبقوتك أنصفني.","54:2":"ياالله اسمع صلاتي واصغ إلى كلامي.","54:3":"لأن غرباء قاموا علي، وعتاة يسعون إلى قتلي، ولم يجعلوا الله نصب أعينهم","54:4":"هوذا الله معيني والسيد الرب عاضدي.","54:5":"يرد الشر على أعدائي، وبحق (عدلك) استأصلهم.","54:6":"طوعا أذبح لك، وأحمد اسمك يارب لأنه طيب.","54:7":"فإنه نجاني من كل ضيق ورأيت بعيني (ما حل) بأعدائي.","55:1":"اصغ ياالله إلى صلاتي، ولا تتغافل عن تضرعي.","55:2":"استمع لي واستجب، لأني حائر ومضطرب في كربتي،","55:3":"من تهديدات الأعداء وجور الشرير، لأنهم يجلبون علي المتاعب، وبغضب يضطهدونني.","55:4":"قلبي يتوجع في داخلي، وأهوال الموت أحاطت بي.","55:5":"اعتراني الخوف والارتعاد، وطغى علي الرعب.","55:6":"فقلت: «ليت لي جناحا كالحمامة فأطير وأستريح.","55:7":"كنت أشرد هاربا وأبيت في البرية.","55:8":"كنت أسرع للنجاة من الريح العاصفة، ومن نوء البحر».","55:9":"بلبل ألسنة (أعدائي) يارب وأبكمهم، فإني أرى في المدينة عنفا وعدوانا،","55:10":"يحدقان بأسوارها نهارا وليلا، وفي وسطها الإثم والأذى.","55:11":"المفاسد في وسطها، والظلم والغش لا يفارقان ساحاتها.","55:12":"لو كان عدوي هو الذي يعيرني لكنت أحتمل. ولو كان من يبغضني هو الذي يتجبر علي لكنت أختبيء منه.","55:13":"ولكنك عديلي، وإلفي وصديقي الحميم،","55:14":"الذي كانت لنا عشر ة معه، وكنا نترافق في الحضور إلى بيت الله مع جمهور العابدين.","55:15":"ليفاجيء الموت أعدائي فينزلوا إلى الهاوية أحياء، لأن الشر جاثم في وسط مساكنهم.","55:16":"أما أنا فبالرب أستغيث والرب يخلصني.","55:17":"مساء وصباحا وظهرا أشكو له صارخا ونائحا، فيسمع صوتي.","55:18":"يخلص نفسي بسلام من المعارك الناشبة حولي إذ إن المتألبين علي كثيرون.","55:19":"حقا إن الله الجالس على العرش منذ الأزل يسمع لي فيذل أعدائي، الذين لا يتغيرون ولا يخافون الله .","55:20":"(رفيقي القديم) هاجم أصحابه المسالمين ونقض عهده معهم.","55:21":"كان كلامه أنعم من الزبدة، وفي قلبه يضمر القتال. كلماته ألين من الزيت، ولكنها سيوف مسلولة.","55:22":"ألق على الرب همك وهو يعتني بك: إنه لا يدع الصديق يتزعزع إلى الأبد.","55:23":"وأنت ياالله تطرح الأشرار إلى هوة الهلاك وتقصر أعمار سافكي الدماء والغشاشين. أما أنا فأتكل عليك.","56:1":"ارحمني يارب فإن الإنسان يجد في مطاردتي لاَفتراسي. يحاربني اليوم كله ويضايقني.","56:2":"يتربص بي أعدائي طوال اليوم لاَبتلاعي، وما أكثر الذين يحاربونني بكبرياء المتجبرين.","56:3":"في يوم خوفي أتكل عليك.","56:4":"توكلت على الله الذي أحمده على كلامه، فلا أخاف. ماذا يستطيع أن يصنع بي البشر؟","56:5":"يحرف أعدائي طوال اليوم كلامي. كل أفكارهم تتآمر بالشر علي.","56:6":"يتجمعون علي ويكمنون لي. يترصدون خطواتي ويبتغون نفسي.","56:7":"عاقبهم يارب بمقتضى إثمهم. أخضع بسخط الشعوب ياالله .","56:8":"أنت راقبت تشردي. فاحفظ دموعي في خزانتك. أما هي في كتابك؟","56:9":"عندما أدعوك يتقهقر أعدائي إلى الوراء. وهذا ما تيقنت منه: أن الله معي.","56:10":"أحمد الله على كلامه. أحمد الرب على كلامه.","56:11":"على الله توكلت فلا أخاف. ماذا يستطيع أن يصنع بي الإنسان؟","56:12":"يارب إني أوفي ما علي من نذور، وأقرب لك ذبائح الشكر.","56:13":"لأنك أنقذت نفسي من الموت، وحفظت رجلي من الزلق، لكي أسلك أمام الله في نور الحياة.","57:1":"ارحمني ياالله ارحمني، لأن بك لاذت نفسي، وبظل جناحيك أحتمي إلى أن تعبر المصائب.","57:2":"أصرخ إلى الله العلي، الذي يتمم لي مقاصده،","57:3":"فيرسل من السماوات ويخلصني، ويملأ بالخزي من يريد أن يفترسني. يرسل الله رحمته وحقه.","57:4":"حين أرقد بين نافثي السموم من بني البشر أجد نفسي بين الأسود المفترسة؛ أنيابهم كالرماح والسهام، وألسنتهم كالسيوف المرهفة.","57:5":"لتتعال ياالله على السماوات وليرتفع مجدك على الأرض كلها.","57:6":"نصبوا شبكة لخطواتي، فانحنت نفسي. حفروا أمامي حفرة فسقطوا هم فيها.","57:7":"ثابت قلبي ياالله ، ثابت قلبي. أشدو وأرنم.","57:8":"استيقظي يانفسي. استيقظي يارباب وياعود. سأوقظ الفجر على شدوي.","57:9":"يارب أحمدك بين الشعوب وأشدو لك بين الأمم.","57:10":"لأن رحمتك قد عظمت إلى السماوات، وحقك إلى الغمام.","57:11":"ارتفع ياالله على السماوات، وليرتفع مجدك على الأرض كلها.","58:1":"أحقا تنطقون بالحق أيها الحكام، وتقضون بالاستقامة يابني البشر؟","58:2":"لا! إنما تضمرون الباطل في القلب وترتكب أيديكم الظلم في الأرض.","58:3":"زاغ الأشرار وهم ما برحوا في بطون أمهاتهم، وضلوا ناطقين بالكذب منذ أن ولدوا.","58:4":"فيهم سم كسم الحيات، يسدون آذانهم كالأفاعي الصماء،","58:5":"التي لا تسمع لصوت الحواة، ولا لصوت الساحر الماهر.","58:6":"هشم أسنانهم في أفواههم ياالله . حطم أنياب الأشبال.","58:7":"ليتلاشوا كالماء المراق، ولتتكسر رؤوس سهامهم عندما يصوبونها.","58:8":"ليتلاشوا مثل القواقع في أثناء زحفها، وكالجنين المجهض لا يعاينون الشمس.","58:9":"وقبل أن تحس قدوركم بنار الأشواك تحتها، يكتسح الله كبيرهم وصغيرهم بعاصفة غضبه،","58:10":"يفرح الأبرار حين يرون عقاب الأشرار، ويغسلون أقدامهم بدمهم.","58:11":"فيقول الناس: «حقا إن للصديق مكافأة، وإن في الأرض إلها يقضي».","59:1":"إلهي أنقذني من أعدائي، واحمني من مقاومي.","59:2":"نجني من فاعلي الإثم، وخلصني من سافكي الدماء.","59:3":"قد نصبوا كمينا لنفسي. اجتمع على أقوياء، لا بسبب معصيتي ولا من جراء خطيئتي يارب.","59:4":"يسرعون متأهبين للإيقاع بي، من غير أن أقترف إثما. فانهض لإغاثتي وانظر إلى ما يجري.","59:5":"وأنت يارب ياإله الجنود وإله إسرائيل، استيقظ وحاسب الأمم حسابا عسيرا ولا تترَأف بالغادر الأثيم","59:6":"يرجعون عند المساء يهرون مثل الكلاب، يطوفون في المدينة.","59:7":"تفيض أفواههم سوءا. (ألسنتهم) كسيوف حادة بين شفاههم، قائلين: «من يسمعنا؟»","59:8":"لكنك أنت يارب تضحك منهم. تستهزيء بجميع الأمم.","59:9":"ياقوتي إياك أترجى، لأن الله هو حصني المنيع.","59:10":"إلهي برحمته يوافيني. ويريني هزيمة أعدائي.","59:11":"لا تقتلهم يارب، إنما اجعلهم عبرة لئلا ينسى شعبي، بل بددهم بقدرتك واطرحهم أرضا أيها الرب حامينا،","59:12":"جزاء خطيئة أفواههم وكلام شفاههم. ليسقطوا في فخ كبريائهم لقاء ما ينطقون به من اللعنات والكذب.","59:13":"أفنهم في غضبك واستأصلهم فتدرك أقاصي الأرض أن الله يسود على بني يعقوب.","59:14":"يرجعون عند المساء يهرون مثل الكلاب ويطوفون في المدينة.","59:15":"يهيمون متشردين طلبا للطعام. وإن لم يشبعوا يدمدمون.","59:16":"أما أنا فأترنم بقوتك. أتهلل في الصباح لرحمتك لأنك كنت لي حصنا منيعا وملجأ في يوم ضيقي.","59:17":"لك أسبح ياقوتي لأن الله ملجإي. إله رحمتي.","60:1":"ياالله قد رذلتنا، وبددتنا وسخطت علينا، فردنا إليك.","60:2":"زلزلت الأرض وصدعتها، فاجبر كسرها لأنها تهتز.","60:3":"جعلت شعبك يعاني المشقات. وترنحنا تحت وقع ضرباتك كالسكارى.","60:4":"أعطيت خائفيك راية ترفع لأجل الحق.","60:5":"لكي ينجو أحباؤك. خلص بيمينك واستجب لي.","60:6":"قد تكلم الله في قداسته، لذلك أبتهج وأقسم أرض شكيم وأقيس وادي سكوت،","60:7":"لي جلعاد، ولي منسى. أفرايم خوذة رأسي، ويهوذا صولجاني.","60:8":"موآب مرحضتي، وعلى أدوم ألقي حذائي، وعلى فلسطين أهتف منتصرا.","60:9":"من يقودني لمحاربة المدينة المحصنة؟ من يهديني إلى أدوم؟","60:10":"أليس أنت ياالله الذي أقصيتنا ولم تعد تخرج مع جيوشنا؟","60:11":"هب لنا عونا في الضيق، فعبث هو خلاص الإنسان.","60:12":"(لكن) بعون الله نحارب ببأس، وهو الذي يدوس أعداءنا.","61:1":"استمع ياالله إلى صراخي واصغ إلى صلاتي.","61:2":"من أقصى الأرض أدعوك إذا غشي على قلبي، فتهديني إلى صخرة عالية يتعذر ارتقاؤها.","61:3":"لأنك كنت لي ملجأ وبرجا منيعا يحميني من العدو.","61:4":"لذا أسكن في خيمتك إلى الأبد، وأعتصم بستر جناحيك،","61:5":"لأنك أنت ياالله قد استمعت إلى نذوري. أعطيتني ميراثا كميراث الذين يتقون اسمك.","61:6":"تضيف أياما إلى عمر الملك، فتكون سنو حياته كأجيال عديدة.","61:7":"يبقى على عرشه أمام الله إلى الأبد. واجعل الرحمة والحق يحفظانه.","61:8":"وهكذا أرنم لاَسمك إلى الأبد، وأوفي نذوري دائما.","62:1":"انتظرت نفسي الله وحده. من لدنه يأتي خلاصي.","62:2":"هو وحده صخرتي وخلاصي وحصني المنيع، لذلك لا أتزعزع أبدا.","62:3":"إلى متى توالون الهجوم على الإنسان، وتسعون جميعكم إلى هدمه، كأنه حائط متداع أو سياج مخلخل؟","62:4":"إنما يتآمرون كي يطيحوا به عن مكانته الرفيعة، مبتهجين بالكذب: يباركون بأفواههم ويلعنون بقلوبهم.","62:5":"انتظرت نفسي الله وحده؛ من لدنه يأتي خلاصي.","62:6":"هو وحده صخرتي وخلاصي وحصني المنيع، لذلك لا أتزعزع أبدا.","62:7":"في الله خلاصي ومجدي. والله هو صخرة قوتي وملجإي.","62:8":"ثقوا به في كل حين أيها الشعب. اسكبوا أمامه قلوبكم، الله ملجأنا.","62:9":"ليس البشر جميعا، عظماء وأدنياء، سوى باطل ووهم. إن وضعتهم في كفة ميزان لا يزنون شيئا. إنهم أخف من نسمة.","62:10":"لا تتكلوا على الظلم ولا تتفاخروا بالسرقة. إن كثر الغنى فلا تعتمدوا عليه،","62:11":"مرة تكلم الرب ومرتين سمعت هذا: أن العزة لله،","62:12":"لك الرحمة يارب فأنت تجازي كل إنسان بمقتضى عمله.","63:1":"ياالله أنت إلهي وإياك أطلب باكرا. عطشت إليك نفسي ويشتاق إليك جسمي في أرض قاحلة يابسة لا ماء فيها.","63:2":"حتى أعاين قدرتك ومجدك، مثلما رأيتك في موضعك المقدس.","63:3":"لأن رحمتك خير من الحياة، لذلك تسبحك شفتاي.","63:4":"أحمدك على بركاتك مدى حياتي، وباسمك أرفع يدي مبتهلا.","63:5":"تشبع نفسي كأنها أكلت من الشحم والدسم، ويسبحك فمي بشفتين مبتهجتين","63:6":"أذكرك على فراشي وأتأمل فيك في أثناء الليل.","63:7":"لأنك كنت عونا لي، فإني في ظل جناحيك أرنم مبتهجا.","63:8":"تتعلق نفسي بك. يمينك تدعمني","63:9":"أما طالبو نفسي ليهلكوها فسيدخلون أسفل أعماق الأرض.","63:10":"يسلمون إلى حد السيف ويضحون مأكلا لبنات آوى.","63:11":"أما الملك فيفرح بالله ويفتخر به كل من يقسم (صادقا) لأن أفواه الناطقين بالكذب تسد.","64:1":"ياالله اسمع صوتي حين أشكو إليك أمري، واحفظ حياتي من رهبة عدوي.","64:2":"استرني من مؤامرة الأشرار، ومن هياج جمهور فاعلي الإثم،","64:3":"الذين سنوا ألسنتهم كالسيف، وصوبوا سهام كلامهم المر،","64:4":"ليرموا البريء من مكامنهم. يرمونه فجأة ومن غير رادع.","64:5":"يشددون عزائمهم في أمر شرير، ويكيدون لنصب الفخاخ خفية، قائلين: «من يرانا؟»","64:6":"يدبرون المكائد ثم يقولون: «نحن على أهبة الاستعداد فقد أحكمنا الخطة». فما أعمق ما يضمره قلب الإنسان من أفكار!","64:7":"لكن الله يطلق عليهم سهما فيصابون فجأة بجراح.","64:8":"كلمات ألسنتهم ترتد عليهم، وكل من يراهم يهز رأسه احتقارا،","64:9":"فيخاف جميع البشر ويذيعون ما فعله الله ، معتبرين بصنائعه.","64:10":"يفرح البار بالرب ويحتمي به، ويبتهج جميع أصحاب القلوب المستقيمة.","65:1":"لك ينبغي التسبيح في صهيون ياالله ، ولك يوفى النذر.","65:2":"ياسامع الصلاة إليك يقبل كل إنسان.","65:3":"قد غلبت الآثام علي. أنت وحدك تكفر عنها.","65:4":"طوبى لمن تختاره وتقربه ليسكن في ديارك. فنشبع من خيرات بيتك، خيرات هيكلك المقدس.","65:5":"بمروعات تستجيب لنا أيها الإله مخلصنا، يامن عليه تتوكل جميع أقاصي الأرض وأطراف البحر البعيدة.","65:6":"المرسخ الجبال بقوته، والمتنطق بالقدرة.","65:7":"المهديء اضطراب البحار، عجيج الأمواج، وضجيج الأمم.","65:8":"يخاف الساكنون في الأماكن البعيدة من آياتك العجيبة. فإنك تجعل مطالع الصبح ومغارب المساء تترنم.","65:9":"تعهدت الأرض وجعلتها تفيض غيثا، فأخصبتها. مجرى نهر الله دافق بالماء فتفيض الأرض بالمحاصيل.","65:10":"تروي أتلامها (خطوط المحراث) وتسوي روابيها، فتلينها وتبارك غلتها.","65:11":"كللت السنة بجودك، وآثار صنائعك تفيض خصبا.","65:12":"تموج مراعي البرية بالخير، وتكتسي التلال بالبهجة.","65:13":"تتغطى المروج بالقطعان، وتتوشح الوديان بالحنطة، فيهتف لك الكل فرحا وتسبيحا.","66:1":"اهتفي لله ياكل الأرض.","66:2":"ترنموا بعظمة اسمه واجعلوا تسبيحه مجيدا.","66:3":"قولوا لله: «ما أروع أعمالك». يتملقك أعداؤك لأن قوتك عظيمة.","66:4":"كل الأرض تسجد لك وتسبحك. الجميع يلهجون باسمك.","66:5":"تعالوا انظروا أعمال الله وأفعاله المرهبة مع بني آدم.","66:6":"حول البحر أرضا يابسة، فاجتازوا في النهر بأقدامهم. هناك فرحنا به.","66:7":"يحكم إلى الأبد بقوته، وعيناه تراقبان الأمم، فلا يتشامخ المتمردون.","66:8":"أيها الشعوب باركوا إلهنا. ارفعوا أصواتكم بالتسبيح.","66:9":"هو الذي استحيانا، ولم يدع أرجلنا تزل.","66:10":"فإنك قد اختبرتنا ياالله ، فنقيتنا كما تنقى الفضة.","66:11":"أوقعتنا في الشبكة وألقيت حملا ثقيلا على ظهورنا.","66:12":"سلطت أناسا علينا. اجتزنا في النار والماء، ولكنك أخرجتنا إلى أراض خصيبة.","66:13":"أدخل إلى بيتك بمحرقات وأوفيك نذوري","66:14":"التي نطقت بها شفتاي في وقت ضيقي، وتكلم بها فمي في بليتي.","66:15":"أقرب لك محرقات سمينة من كباش مع بخور. أقدم بقرا مع تيوس.","66:16":"تعالوا اسمعوا ياجميع خائفي الله، فأحدثكم بما فعل لنفسي.","66:17":"صرخت إليه بفمي وعظمته بلساني.","66:18":"إن تعهدت إثما في قلبي لا يستمع لي الرب.","66:19":"ولكن الله قد استجاب لي. أصغى إلى صوت صلاتي.","66:20":"تبارك الله الذي لم يقص عنه صلاتي، ولا حجب عني رحمته.","67:1":"ليترَأف الله علينا وليباركنا، وليضيء بوجهه علينا","67:2":"لكي يعرف في الأرض طريقك، وبين جميع الأمم خلاصك.","67:3":"تحمدك الشعوب ياالله ، تحمدك الشعوب كلها.","67:4":"تفرح وتبتهج الأمم لأنك تدين الشعوب بالاستقامة، وتهدي أمم الأرض.","67:5":"تحمدك الشعوب ياالله ، تحمدك الشعوب كلها.","67:6":"أعطت الأرض غلتها الوفيرة.","67:7":"يباركنا الله إلهنا، فتخافه كل أقاصي الأرض.","68:1":"يقوم الله فيتبدد أعداؤه ويفر مبغضوه من أمامه.","68:2":"كما يتلاشى الدخان تلاشيهم، وكما يذوب الشمع قرب النار يهلك الأشرار في حضرة الله.","68:3":"أما الأبرار فإنهم يفرحون ويبتهجون أمام الله ويغتبطون سرورا.","68:4":"رنموا لله، اشدوا لاسمه. مهدوا طريقا للراكب في القفار ظافرا. إن اسمه «الكائن». وتهللوا في محضره.","68:5":"الله المقيم في مسكنه المقدس هو أبو اليتامى وقاضي الأرامل.","68:6":"يسكن الله المتوحدين بيتا، ويطلق المقيدين إلى النجاح، أما المتمردون فيسكنون أرضا محرقة.","68:7":"ياالله ، عندما خرجت أمام شعبك، وقدتهم في البرية،","68:8":"رجفت الأرض، وهطلت السماء مطرا، وارتعد جبل سيناء من حضرة الله إله إسرائيل.","68:9":"مطرا غزيرا سكبت ياالله على شعبك ميراثك، وعند إعيائه أنت شددته.","68:10":"هناك في البرية حل قطيعك، وأنت بجودك وفرت خيرا للمساكين، ياالله .","68:11":"يصدر السيد أمره فينهزم العدو فيحمل جمع غفير من النساء بشرى النصر.","68:12":"يهرب ملوك الجيوش، نعم يهربون. أما النساء الملازمات البيوت فيقتسمن الغنائم.","68:13":"مع أنكم رقدتم بين الحظائر (كرعاة محتقرين في مصر) تكونون كحمامة أجنحتها مغشاة بالفضة، وريشها بالذهب الأصفر.","68:14":"عندما بدد القدير ملوكا في البرية، ابيضت الأرض (من عظام القتلى) كالثلج في جبل صلمون.","68:15":"جبل باشان هو جبل الله؛ جبل كثير القمم.","68:16":"أيتها الجبال الكثيرة القمم لماذا تتفرسن بحسد في الجبل الذي اشتهاه الله لسكناه؟ إن الله سيسكن فيه إلى الأبد.","68:17":"مركبات الرب كثيرة لا تحصى والرب في وسطها، فصار جبل صهيون مماثلا لجبل سيناء في القداسة.","68:18":"يصعد إلى العلى ويأخذ معه سبايا كثيرين؛ يوزع الغنائم على الناس وحتى على الذين تمردوا قبلا على مقر سكناك، أيها الرب الإله.","68:19":"تبارك الرب الذي يحمل أثقالنا يوما فيوما. إنه إله خلاصنا.","68:20":"إلهنا هو إله الخلاص، وعند الرب السيد منافذ من الموت.","68:21":"حقا سيضرب الرب رؤوس أعدائه، وكذلك الهامة المكسوة شعرا لمن يمعن في طريق المعاصي.","68:22":"يقول السيد: «سأرجع أعداءكم من باشان، سأرجعهم من أعماق البحر،","68:23":"فتغمسون أرجلكم في دمهم، وتأخذ ألسنة الكلاب نصيبها من الأعداء».","68:24":"لقد عاين الشعب موكبك ياالله ، موكب إلهي وملكي المتجه إلى المقدس.","68:25":"سار المغنون في الطليعة، وضاربو الأوتار خلفهم، وفي الوسط صبايا يضربن على الدفوف.","68:26":"باركوا الله السيد في المحافل يانسل إسرائيل.","68:27":"هناك في طليعتهم بنيامين الصغير وعلى أثره رؤساء يهوذا في جماعتهم، ثم رؤساء زبولون ورؤساء نفتالي.","68:28":"قد أعزك الله ، فأظهر ياالله قوتك بما صنعت لنا من معجزات.","68:29":"يقدم الملوك لك الهدايا في أورشليم لأن هيكلك فيها","68:30":"انتهر مصر، الوحش الكامن بين القصب. انتهر الأمم القوية التي تشبه قطيع الثيران؛ حتى يخضعوا ويدفعوا لك جزية فضة. بدد الشعوب المولعة بالحرب.","68:31":"يفد إليك شرفاء من مصر (ليقدموا الولاء) وتبسط الحبشة يديها مسرعة إعرابا عن خضوعها لله.","68:32":"ياممالك الأرض غنوا لله. رنموا للسيد،","68:33":"للراكب على السماوات، السماوات القديمة، منتصرا. ها هو يدوي بصوته عاليا، صوت القدرة.","68:34":"أعطوا مجدا لله فهو بسط جلاله على إسرائيل، وقوته في الغمام.","68:35":"أنت مرهب ياالله من مقادسك. إله إسرائيل نفسه هو الذي يمد شعبه قوة وشدة. تبارك الله .","69:1":"خلصني ياالله ، فإن المياه قد غمرت نفسي.","69:2":"غرقت في حمأة ولا مكان فيها أستقر عليه. خضت أعماق المياه. وطما علي السيل.","69:3":"تعبت من صراخي. جف حلقي. كلت عيناي وأنا أنتظر إلهي.","69:4":"مبغضي من غير علة أكثر عددا من شعر رأسي، وطالبو هلاكي طغاة جائرون. حينئذ رددت مالم أغتصبه.","69:5":"ياالله أنت تعرف حماقتي، ومعاصي لم تخف عنك.","69:6":"أيها السيد رب الجنود، لا تدعني أكون علة خزي ملتمسيك، ولا مثار خجل طالبيك ياإله إسرائيل.","69:7":"لأنني تحملت العار من أجلك، وغطى الخجل وجهي.","69:8":"صرت غريبا في عيون إخوتي، وأجنبيا في نظر بني أمي.","69:9":"لأن الغيرة على بيتك التهمتني وتعييرات الذين يعيرونك وقعت علي.","69:10":"صمت وبكيت فعيروني.","69:11":"اتشحت بالمسوح فصرت عندهم مثلا.","69:12":"صرت حديث الجالسين في باب المدينة، وأغنية للسكارى.","69:13":"أما أنا فإليك صلاتي يارب؛ لأن هذا أوان الرضى، فاستجب لي ياالله برحمتك الغزيرة وبحق خلاصك.","69:14":"أنقذني من الوحل فلا أغرق. نجني من مبغضي وانتشلني من أعماق الميا ه.","69:15":"لا يطم علي سيل المياه، ولا يبتلعني العمق، ولا تطبق الهوة علي فمها.","69:16":"استجب أيها الرب لأن رحمتك صالحة، وبحسب مراحمك الوفيرة التفت إلي.","69:17":"لا تحجب وجهك عن عبدك، لأنني في ضيق، فأسرع واستجب لي.","69:18":"اقترب إلى نفسي، وفكها. افدني (نكاية) بأعدائي","69:19":"أنت عرفت (ما حل بي من) عار وخزي وهوان. أنت تعرف كل مضايقي.","69:20":"كسر العار قلبي فمرضت. التمست عطفا فلم أجد، ومعزين فلم أعثر على أحد.","69:21":"وضعوا علقما في طعامي، وفي عطشي يسقونني خلا.","69:22":"لتصر لهم مائدتهم فخا وعقبة وعقابا.","69:23":"لتظلم عيونهم كي لا يبصروا ولتكن ظهورهم منحنية دائما.","69:24":"صب سخطك عليهم، وليدركهم غضبك المحتدم.","69:25":"ليصر مسكنهم خرابا، ولا يبق في خيامهم ساكن.","69:26":"لأنهم يضطهدون من عاقبته، ويشمتون في وجع الذين جرحتهم.","69:27":"زد إثما على إثمهم ولا تبريء ساحتهم.","69:28":"لتحذف (أسماؤهم) من سجل الحياة ولا تكتب مع الأبرار.","69:29":"أما أنا فمتضايق ومتوجع. فليرفعني خلاصك ياالله .","69:30":"أسبح اسم الله بنشيد وأعظمه بحمد.","69:31":"فيطيب ذلك لدى الرب أكثر من محرقة: ثور أو عجل.","69:32":"يرى الودعاء ذلك فيفرحون. وتحيا نفوسكم ياطالبي الله.","69:33":"لأن الرب يستجيب للمحتاجين ولا يحتقر شعبه الأسير.","69:34":"تسبحه السماوات والأرض والبحار وكل ما يتحرك فيها.","69:35":"لأن الله يخلص صهيون ويبني مدن يهوذا، فيسكن الشعب فيها ويمتلكها.","69:36":"ترثها ذرية عبيده، ومحبو اسمه يسكنون فيها.","70:1":"هلم أنقذني يارب، وأسرع إلى معونتي.","70:2":"ليخز ويخجل الساعون إلى قتلي. ليرتد ويخجل المغتبطون بأذيتي.","70:3":"ليرجع الساخرون مني مجللين بالعار.","70:4":"ليفرح ويبتهج بك جميع طالبيك. وليقل دائما محبو خلاصك: ليتعظم الرب.","70:5":"إنما أنا متضايق ومحتاج، فأسرع اللهم إلي. أنت عوني ومنقذي. يارب لا تتباطأ.","71:1":"يارب بك احتميت فلا تدعني أخزى إلى الأبد.","71:2":"أنقذني وفقا لعدلك ونجني. أرهف إلي أذنك وخلصني.","71:3":"كن لي صخرة ملجأ ألوذ بها دائما. أنت أمرت بخلاصي لأنك صخرتي ومعقلي.","71:4":"ياإلهي أنقذني من يد الشرير، من قبضة الأثيم والظالم.","71:5":"فإنك أنت رجائي أيها السيد، وموضع ثقتي منذ صباي.","71:6":"عليك اعتمدت منذ ولادتي، ومن بطن أمي أخرجتني، فإياك أسبح في كل حين.","71:7":"صرت مثار استهجان عند كثيرين، لكنك أنت ملجإي القوي.","71:8":"ليمتلىء فمي من تسبيحك ومن تمجيدك طول النهار.","71:9":"لا تنبذني في شيخوختي، ولا تخذلني عند اضمحلال قوتي.","71:10":"لأن أعدائي يتكلمون علي والمتربصين بي يتآمرون معا.","71:11":"قائلين: «قد تركه الله ، فطاردوه واقبضوا عليه لأنه لا منقذ له».","71:12":"لا تبتعد عني ياالله . أسرع إلى معونتي ياإلهي.","71:13":"ليخز ويبد خصوم نفسي. ليكتس العار والهوان الملتمسون أذيتي.","71:14":"أما أنا فإياك أرجو دائما، وأكثر من تسبيحك.","71:15":"أخبر ببرك وخلاصك طول النهار، وإن كانا يفوقان إدراكي.","71:16":"أجيء (مؤيدا) بقوة السيد الرب، لأذكر برك وحدك.","71:17":"قد علمتني ياالله منذ صباي، فلم أكف لحظة عن إعلان عجائبك.","71:18":"لا تتركني في الشيخوخة والشيب ياالله ، حتى أخبر هذا الجيل بأعمال قدرتك، وبقوتك (الجيل) الآتي.","71:19":"برك متعال ياالله ، وأعمالك التي صنعت عظيمة، فمن مثلك ياالله !","71:20":"أنت الذي اجتزت بنا ضيقات كثيرة وقاسية، ولكنك تعود فتحيينا، وتصعدنا من جديد من أعماق الأرض.","71:21":"تزيدني شرفا وتطوقني بتعزيتك.","71:22":"سأحمدك وأشيد بحقك على الرباب ياإلهي. أشدو لك على العود ياقدوس إسرائيل.","71:23":"تبتهج شفتاي عندما أرنم لك، وكذلك نفسي التي فديتها.","71:24":"ويلهج لساني ببرك اليوم كله، لأن الساعين إلى أذيتي يحل حتما بهم الخزي والعار.","72:1":"اللهم أعط أحكامك العادلة للملك ولابنه برك،","72:2":"فيقضي لشعبك بالعدل ومساكينك بالإنصاف.","72:3":"لتحمل الجبال للشعب سلاما، والتلال برا.","72:4":"ليحكم الملك بالحق للمساكين، وينقذ بني البائسين، ويحطم الظالم.","72:5":"ليرهبوك مادامت الشمس والقمر، من جيل إلى جيل.","72:6":"ليكن الملك كالمطر المنهمر على المراعي المجزوزة، كالغيوث التي تسقي الأرض.","72:7":"ليزدهر في أيامه الصديق، ويتوافر السلام مادام القمر يضيء.","72:8":"ولتمتد مملكته من البحر إلى البحر، ومن النهر إلى أقاصي الأرض.","72:9":"أمامه يركع أهل البادية، وأعداؤه يلحسون التراب.","72:10":"ملوك ترشيش والجزر يحملون إليه الهدايا. ملوك شبا وسبَإ يقدمون عطايا.","72:11":"ينحني أمامه جميع الملوك. وتتعبد له كل الأمم.","72:12":"لأنه ينقذ المسكين المستغيث البائس الذي لا معين له.","72:13":"يعطف على الفقير والمحتاج ويخلص نفوس المساكين.","72:14":"إذ يفتدي نفوسهم من الظلم والعنف، ويحفظ حياتهم لأنها ثمينة في عينيه.","72:15":"ليحي الملك! ليعط له ذهب شبا. وليصلوا من أجله دائما ويطلبوا له بركة الله كل النهار.","72:16":"لتتكاثر الغلال في الأرض وعلى رؤوس الجبال، وتتماوج مثل أرز لبنان، ويزهر أهل المدينة كعشب الأرض.","72:17":"يخلد اسمه إلى الدهر، ويدوم اسمه كديمومة الشمس، ويتبارك الناس به، وتطوبه كل الأمم.","72:18":"تبارك الرب إله إسرائيل، فهو وحده صانع العجائب.","72:19":"تبارك اسمه المجيد إلى الأبد، ولتمتليء الأرض كلها من مجده. آمين ثم آمين.","72:20":"هنا تنتهي صلوات داود بن يسى.","73:1":"حقا إن الله رفيق بإسرائيل، بذوي القلوب النقية.","73:2":"أما أنا فقد أوشكت قدماي أن تزلا، وخطواتي أن تنزلق،","73:3":"لأني حسدت المتكبرين، إذ شاهدت نجاح الأشرار.","73:4":"فإن أوجاع الموت لا تصيبهم وأجسامهم سمينة.","73:5":"لا يقاسون من أتعاب البشر، ولا يعانون من المصائب كالناس.","73:6":"لذلك لبسوا الكبرياء كقلادة، وارتدوا الظلم كثوب.","73:7":"عيونهم جاحظة من كثرة شحم طمعهم. وشرهم تجاوز ما يتصوره القلب.","73:8":"يستهزئون ويتكلمون بالظلم خبثا، وبكبرياء ينطقون.","73:9":"جدفوا على السماء بأفواههم، ولوثوا الأرض بخبث ألسنتهم.","73:10":"حتى شعب الله يرجعون إليهم، ويصدقون ما يقولونه لهم.","73:11":"أما هم فيقولون: كيف يعلم الله، وهل يدري العلي بما يحدث؟","73:12":"ها هم الأشرار المفلحون في العالم يزدادون ثروة.","73:13":"باطلا قد طهرت قلبي وغسلت يدي بالنقاوة.","73:14":"لقد جعلتني يارب مصابا طول النهار، وأوقعت علي عقابك كل صباح.","73:15":"لو أنني نطقت بمثل هذا، لكنت قد خنت جيل أولادك.","73:16":"وعندما نويت أن أفهم هذا، تعذر الأمر علي،","73:17":"إلى أن دخلت أقداس الله، وتأملت مآل الأشرار","73:18":"حقا إنك أوقفتهم في أماكن زلقة، وأوقعتهم في التهلكات.","73:19":"كيف صاروا للخر اب فجأة؟ انقرضوا وأفنتهم الدواهي.","73:20":"كحلم يتلاشى عند اليقظة هكذا تختفي صورتهم عندما تنهض يارب لمعاقبتهم.","73:21":"عندما تمرمر قلبي ووخزني ضميري،","73:22":"أدركت أنني كنت غبيا لا أعرف شيئا، إذ كنت كبهيمة أمامك.","73:23":"غير أني معك دائما، وأنت قد أمسكت بيدي اليمنى.","73:24":"تهديني بمشورتك، وبعد ذلك تأخذني إلى المجد.","73:25":"من لي في السماء غيرك؟ ولست أبغي في الأرض أحدا معك.","73:26":"إن جسدي وقلبي يفنيان، أما الله فهو صخرة قلبي ونصيبي إلى الدهر.","73:27":"هوذا المبتعدون عنك يهلكون وأنت تدمر كل من يخونك.","73:28":"أما أنا فخير لي أن أقترب إلى الله، لأني على السيد توكلت، لأحدث بجميع عجائبك.","74:1":"ياالله لماذا نبذتنا إلى الأبد؟ لماذا ثار غضبك الشديد على غنم مرعاك؟","74:2":"اذكر جماعتك التي اقتنيتها منذ القدم، والتي افتديتها لتجعلها سبط ميراثك. اذكر جبل صهيون الذي أقمت فيه.","74:3":"سر يارب مسرعا وسط هذه الخرائب الدائمة، فإن العدو قد دمر كل شيء في بيتك المقدس.","74:4":"إن خصومك يزمجرون في وسط محفلك، وينصبون أصنامهم شارات للنصر.","74:5":"يظهر العدو كأنه يهوي بالفؤوس على الأشجار الكثيفة.","74:6":"هدموا منقوشاته كلها بالمطارق والمعاول.","74:7":"أضرموا النار في مقدسك، ودنسوه إذ قوضوا مقر اسمك إلى الأرض.","74:8":"قالوا في أنفسهم: لنبدهم جميعا. وأحرقوا كل محافل الله في البلاد.","74:9":"لم نعد نشهد رموز عبادتنا، ولم يبق نبي بعد، وليس بيننا من يعرف متى تكون خاتمة الأمر.","74:10":"ياالله : إلى متى يعيرنا الخصم؟ أيظل العدو يستهين باسمك إلى الأبد؟","74:11":"لماذا ترفض أن تمد يد العون؟ لماذا تبقي يمينك خلفك؟ أخرجها وأفنهم.","74:12":"إنما الله ملكي منذ القديم، صانع الخلاص في وسط الأرض.","74:13":"أنت فلقت البحر بقوتك وحطمت رؤوس التنانين.","74:14":"أنت مزقت رؤوس فرعون وجيشه، وجعلته قوتا للحيوانات المتوحشة","74:15":"فجرت نبعا وجدولا، وجففت أنهارا دائمة الجريان.","74:16":"لك النهار والليل أيضا. أنت كونت الكواكب المنيرة والشمس.","74:17":"نصبت حدود الأرض، وخلقت الصيف والشتاء.","74:18":"إنما اذكر أن عدوا قد عير الرب، وشعبا جاهلا قد استهان باسمك.","74:19":"لا تسلم للوحش نفس شعبك الضعيف، ولا تنس إلى الأبد حياة جمهورك المضطهد.","74:20":"اذكر العهد الذي قطعته لنا، فإن الظلم كامن في كل ركن مظلم من الأرض.","74:21":"لا تدع المنسحق يرجع بالخزي، بل ليسبح اسمك الفقير والبائس.","74:22":"قم ياالله ودافع عن دعواك. اذكر كيف يعيرك الجاهل طول النهار.","74:23":"لا تنس أصوات خصومك، فإن ضجيج الثائرين عليك يتصاعد دائما.","75:1":"نحمدك ياالله نحمدك، لأن اسمك قريب من شعبك الذي يخبر بما صنعت من عجائب.","75:2":"يقول الله : «أنا أختار ميعادي وبالإنصاف أنا أقضي.","75:3":"عندما تهتز الأرض وما فيها من أحياء، أنا من يوطد أركانها.","75:4":"أقول للمتغطرسين: لا تتفاخروا فيما بعد،","75:5":"وللأشرار: لا تتشامخوا برؤوسكم ولا تتكلموا بأعناق متصلفة","75:6":"فإن الرفعة لا تأتي من المشرق ولا من المغرب. ولا من الشمال ولا من الجنوب.","75:7":"فالله هو الديان، يرفع واحدا ويخفض آخر.","75:8":"في يد الرب كأس خمر مزبدة ممزوجة. يصبها فيشربها كل الأشرار حتى ثمالتها.","75:9":"أما أنا فلن أكف عن الحديث عن إله يعقوب. أرنم له دائما.","75:10":"يحطم قوة الشرير، أما قوة البار فتعظم.","76:1":"الله معروف في يهوذا واسمه معظم في إسرائيل.","76:2":"خيمته في أورشليم ومسكنه في جبل صهيون.","76:3":"هناك حطم السهام البارقة، والترس والسيف وكل أسلحة الحرب.","76:4":"أنت أمجد وأعظم جلالا من الجبال الخالدة","76:5":"سلبت أبطالهم، فناموا نوم الموت، ولم تنفعهم قدراتهم.","76:6":"من زجرك ياإله يعقوب تصرع الفرسان والخيول.","76:7":"إنما أنت مهوب، فمن يقف أمامك في غضبك؟","76:8":"من السماء أصدرت حكما فلما سمعته الأرض فزعت وصمتت.","76:9":"كان ذلك عندما قمت للقضاء لتخلص ودعاء الأرض كلهم.","76:10":"حقا يحمدك غضب الإنسان، وما تبقى من الغضب تتمنطق أنت به.","76:11":"انذروا وأوفوا للرب إلهكم. ياجميع من حوله قدموا هدية للمهوب،","76:12":"فهو يستأصل أرواح رؤساء الأرض، ويرهب ملوكها العظماء.","77:1":"إلى الله أرفع صوتي، إلى الله أصرخ فيصغي إلي.","77:2":"في يوم ضيقي طلبت الرب. انبسطت يدي طول الليل فلم تكل. أبت نفسي العزاء.","77:3":"أذكر الرب فأتنهد، أناجي نفسي فيغشى على روحي.","77:4":"أمسكت أجفاني عن النوم. اعتراني القلق فعجزت عن الكلام.","77:5":"فكرت في الأيام القديمة وفي السنين السحيقة.","77:6":"في الليل أتذكر ترنيمي، وأناجي قلبي، وتجد في البحث نفسي.","77:7":"هل إلى الأبد يرفضنا الرب ولا يرضى عنا أبدا؟","77:8":"هل انتهت رحمته إلى الأبد؟ هل انقطعت عنا مواعيده؟","77:9":"ألعل الله نسي رأفته؟ أم حبس بغضب مراحمه؟","77:10":"ثم قلت: «هذا يسقمني: أن يمين الله العلي قد تحولت (عنا)»","77:11":"أذكر أعمالك يارب. أذكر عجائبك التي عملتها في القديم،","77:12":"وأتأمل جميع أفعالك وأناجي بكل ما صنعته.","77:13":"ياالله ، إن طريقك هي القداسة، فأي إله عظيم مثل الله؟","77:14":"أنت الإله الصانع العجائب، وقد أعلنت قوتك بين الشعوب.","77:15":"بذراعك القديرة افتديت شعبك بني يعقوب ويوسف.","77:16":"رأتك المياه ياالله فارتجفت واضطربت أعماقها أيضا.","77:17":"سكبت الغيوم ماء وأرعدت السحب، وتطايرت سهامك.","77:18":"(زأر) صوت رعدك في الزوبعة، فأضاءت البروق المسكونة، وارتعدت الأرض واهتزت.","77:19":"إنما في البحر طريقك، ومسالكك في المياه الغامرة، وآثار خطواتك لا تتقصى.","77:20":"هديت شعبك كقطيع على يد موسى وهارون.","78:1":"اصغ ياشعبي إلى شريعتي، أرهفوا آذانكم إلى أقوال فمي.","78:2":"أفتح فمي بمثل وأنطق بألغاز قديمة جدا،","78:3":"سمعناها وعرفناها وحدثنا بها آباؤنا.","78:4":"لا نكتمها عن أبنائنا بل نخبر الجيل القادم: عن قوة الرب وعجائبه التي صنع.","78:5":"فإنه أعطى شرائع لبني إسرائيل وأوامر لذرية يعقوب، أوصى فيها آباءنا أن يعرفوا بها أبناءهم.","78:6":"لكي يعرفها الجيل القادم، البنون الذين لم يولدوا بعد، فيعلموها أيضا لأعقابهم.","78:7":"فيضعون على الله اتكالهم ولا ينسون أعماله، بل يحفظون وصاياه.","78:8":"ولا يكونون مثل آبائهم، جيلا عنيدا متمردا، جيلا لم يثبت قلبه ولا كانت روحه أمينة لله.","78:9":"رماة القوس، بنو أفرايم تقهقروا في يوم المعركة.","78:10":"لأنهم لم يراعوا عهد الله، ورفضوا السلوك في شريعته.","78:11":"نسوا أفعاله وعجائبه التي أظهرها لهم،","78:12":"العجائب التي رآها آباؤهم في سهل صوعن في أرض مصر.","78:13":"شق البحر وأجازهم، وجعل المياه تقف كجدار.","78:14":"أرشدهم بالسحاب نهارا وبنور نار الليل كله.","78:15":"شق صخورا في البرية وسقاهم ماء غزيرا كأنه من اللجج.","78:16":"أخرج من الصخرة سواقي، أجرى مياهها كأنهار.","78:17":"لكنهم أوغلوا في غيهم مستثيرين غضب العلي في الصحراء.","78:18":"وجربوا الله في قلوبهم، طالبين طعاما اشتهته نفوسهم","78:19":"وتذمروا على الله قائلين: أيقدر الله أن يبسط لنا مائدة في البرية؟","78:20":"ها هو قد ضرب الصخرة فتفجرت منها المياه وفاضت الأنهار، فهل يقدر أيضا أن يقدم الخبز أو يوفر اللحم لشعبه؟","78:21":"فلما سمع الله ذلك ثار غضبه، واندلعت النار في يعقوب، واشتد السخط على إسرائيل،","78:22":"لأنهم لم يؤمنوا بالله ولم يتكلوا على خلاصه.","78:23":"ومع ذلك أمر السحاب وفتح أبواب السماوات،","78:24":"فأمطر عليهم المن ليأكلوا، وأنزل عليهم حنطة السماوات.","78:25":"فأكل الإنسان خبز الملائكة، إذ أرسل لهم زادا حتى شبعوا.","78:26":"أثار ريحا شرقية في السماوات، وبقوته ساق ريحا جنوبية.","78:27":"فأمطر عليهم لحما كثيرا كالتراب، وطيورا كرمل البحر،","78:28":"جعلها تتساقط في وسط خيامهم حول مساكنهم.","78:29":"فأكلوا حتى شبعوا جدا، وأعطاهم مشتهاهم.","78:30":"وقبل أن يفرغوا من الطعام الذي اشتهوه، وهو بعد في أفواههم،","78:31":"ثار عليهم غضب الله، فقتل أسمنهم وصرع نخبتهم.","78:32":"ومع هذا ظلوا يخطئون، وبالرغم من عجائبه لم يؤمنوا،","78:33":"فأفنى أيامهم بالباطل وسنيهم في الرعب.","78:34":"وعندما قتل بعضهم، رجعوا بحرارة تائبين يلتمسون الله .","78:35":"تذكروا أن الله صخرتهم والإله العلي فاديهم.","78:36":"ولكنهم خادعوه بأفواههم، ونافقوه بألسنتهم.","78:37":"لم يكونوا مخلصين له، ولا كانوا أوفياء لعهده.","78:38":"لكنه كان رحيما، فعفا عن الإثم ولم يهلكهم. وكثيرا ما كبح غضبه عنهم ولم يضرم كل سخطه.","78:39":"ذكر أنهم بشر كالريح التي تذهب ولا تعود.","78:40":"كم تمردوا عليه في البرية وأحزنوه في الصحراء.","78:41":"ثم عادوا يجربون الله ويغيظون قدوس إسرائيل.","78:42":"لم يذكروا قوته يوم أنقذهم من طالبيهم،","78:43":"كيف أجرى آياته في مصر وعجائبه في سهول صوعن.","78:44":"إذ حول أنهارهم وسواقيهم دما حتى لا يشربوا.","78:45":"أرسل عليهم بعوضا فأكلهم، وضفادع فأهلكتهم.","78:46":"أسلم غلتهم لليسارع ومحاصيلهم للجراد ليدمرها.","78:47":"أتلف كرومهم بالبرد وجميزهم بالصقيع،","78:48":"ودفع بهائمهم إلى البرد، ومواشيهم إلى نار البروق.","78:49":"أرسل عليهم حمم غضبه، وسخطه وغيظه، وأطلق عليهم حملة من ملائكة الهلاك.","78:50":"أفلت عنان غضبه، ولم يحفظهم من الموت، بل أهلكهم بالوبإ،","78:51":"وأباد كل أبكار مصر، طلائع ثمار الرجولة في خيام حام.","78:52":"ثم ساق شعبه كالغنم واقتادهم مثل القطيع في الصحراء.","78:53":"هداهم آمنين فلم يفزعوا. أما أعداؤهم فطغى البحر عليهم وغمرهم.","78:54":"وأدخلهم إلى تخوم أرضه المقدسة، إلى الجبل الذي امتلكته يمينه.","78:55":"ثم طرد الأمم من أمامهم وقسم أرضهم بالحبل ليجعلها ميراثا لشعبه، وأسكن في خيامهم أسباط إسرائيل.","78:56":"غير أنهم جربوا الله العلي وتمردوا عليه، ولم يراعوا شهاداته.","78:57":"بل ارتدوا عنه وغدروا كما فعل آباؤهم، وانحرفوا كقوس مخطئة.","78:58":"وأغاظوه بمعابد مرتفعاتهم وأثاروا غيرته بأصنامهم.","78:59":"سمع الله فغضب، وعافت نفسه إسرائيل جدا.","78:60":"هجر مسكنه في شيلوه، تلك الخيمة التي نصبها مسكنا له بين الناس.","78:61":"وأسلم تابوت عهد عزته إلى السبي وجلاله إلى يد العدو.","78:62":"ودفع شعبه إلى السيف وصب نقمته على ميراثه.","78:63":"فالتهمت النار فتيانهم، ولم تنشد لعذاراهم أغنية زواج.","78:64":"سقط كهنتهم صرعى السيف، وأراملهم لم يندبن عليهم.","78:65":"ثم استيقظ الرب كما يستيقظ النائم، مثل جبار يصرخ عاليا من الخمر.","78:66":"فضرب أعداءه وقهرهم، وجعلهم عارا مدى الدهر.","78:67":"رفض السكنى في خيمة يوسف ولم يختر سبط أفرايم.","78:68":"بل اصطفى سبط يهوذا، جبل صهيون الذي أحبه.","78:69":"فشيد هيكله، (كمسكنه) في السماوات العلى. جعله (ثابتا) مثل الأرض التي أسسها إلى الأبد.","78:70":"واصطفى داود عبده، وأخذه من بين حظائر الغنم.","78:71":"من خلف النعاج المرضعة أتى به، ليرعى يعقوب شعبه وإسرائيل ميراثه.","78:72":"فرعاهم بقلب مستقيم، وهداهم بيديه الماهرتين.","79:1":"ياالله ، إن الأمم قد دخلت ميراثك ونجست هيكلك المقدس وجعلت أورشليم أكواما.","79:2":"جعلوا جثث عبيدك مأكلا لطيور السماء، ولحوم قديسيك لوحوش الأرض.","79:3":"سفكوا دماءهم كالماء حول أورشليم، وليس هناك من يدفنهم.","79:4":"قد صرنا عارا عند جيراننا، ومثار هزء وأضحوكة لمن حولنا.","79:5":"إلى متى يدوم هذا يارب؟ أتبقى غاضبا تتقد غيرتك كالنار إلى الأبد؟","79:6":"صب غضبك على الأمم الذين لم يعرفوك، وعلى الممالك التي لم تدع باسمك،","79:7":"فإنهم قد افترسوا يعقوب وقوضوا مسكنه.","79:8":"لا تذكر علينا آثام أجدادنا، بل دع مراحمك توافينا سريعا، لأننا قد تذللنا جدا.","79:9":"أغثنا أيها الإله مخلصنا من أجل مجدك. أنقذنا واغفر لنا خطايانا من أجل اسمك.","79:10":"لماذا تسألنا الأمم: أين إلهكم؟ دعنا نرى كيف يذيع بين الأمم خبر انتقامك لدماء عبيدك المسفوكة.","79:11":"ليتصاعد أمامك أنين المأسور. حافظ بعظمة قوتك على المحكوم عليهم بالموت.","79:12":"رد يارب على الأمم سبع مرات ما عيروك وأهانوك به،","79:13":"فنحمدك نحن شعبك وغنم مرعاك إلى الأبد ونذيع تسبيحك من جيل إلى جيل.","80:1":"اصغ ياراعي إسرائيل، يامن قدت (قوم) يوسف كالقطيع. تجل يامن بنعمتك تجلس على عرشك فوق الكروبيم","80:2":"استثر قوتك العظيمة أمام أفرايم وبنيامين ومنسى، وتعال لإنقاذنا.","80:3":"ياالله ردنا إليك وأنر بوجهك علينا فنخلص.","80:4":"يارب إله الجنود، إلى متى تظل غاضبا على صلاة شعبك.","80:5":"لقد أطعمتهم خبز الدموع وسقيتهم كؤوسا طافحة بالعبرات","80:6":"جعلتنا مصدر نزاع لجيراننا ومثار هزء لأعدائنا.","80:7":"ياإله الجنود ردنا إليك، وأنر بوجهك علينا فنخلص.","80:8":"نقلت كرمة (أي الشعب) من مصر. طردت أمما وغرستها مكانهم.","80:9":"أوسعت لها فتأصلت جذورها في العمق وملأت الأرض.","80:10":"غطى الجبال ظلها، وشابهت أغصانها الأرز العظيم،","80:11":"مدت قضبانها إلى البحر المتوسط وفروعها إلى نهر الفرات.","80:12":"لماذا هدمت سياجها فيقطفها كل عابري الطريق؟","80:13":"يتلفها الخنزير الطالع من الغابة، ويرعاها وحش البراري.","80:14":"ياإله الجنود ارجعن. تطلع من السماوات وانظر إلى هذه الكرمة وتعهدها بنعمتك.","80:15":"(تفقد) هذه الكرمة التي غرستها يمينك، وابن آدم الذي اخترته لنفسك.","80:16":"لقد أحرقها أعداؤنا بالنار. ليتهم من زجر طلعتك يبيدون.","80:17":"لتكن يدك على الإنسان الجالس عن يمينك، على ابن آدم الذي اخترته لنفسك،","80:18":"فلا نرتد عنك. أحينا فندعو باسمك.","80:19":"يارب إله الجنود ردنا إليك، وأنر بوجهك علينا فنخلص.","81:1":"رنموا بفرح لله قوتنا، اهتفوا عاليا لإله يعقوب.","81:2":"أنشدوا نشيدا، وانقروا على الدف واعزفوا على العود المطرب، وعلى الرباب.","81:3":"انفخوا بالبوق في أول الشهر، في الوقت المعين ليوم عيدنا،","81:4":"لأن هذا فريضة مرسومة على إسرائيل، وحكم يوجبه إله يعقوب.","81:5":"جعله شهادة له بين (قوم) يوسف، عندما ضرب مصر، حيث سمعنا لغة لم نعرفها تقول:","81:6":"«أزحت كتفه من تحت الأحمال الثقيلة، وسلمت يداه من حمل السلال.","81:7":"دعوتني في الضيق فنجيتك. استجبت لك من مكمن الرعد. جربتك عند مياه مريبة.","81:8":"اسمع ياشعبي فأحذرك، ياإسرائيل هلا سمعت لي؟","81:9":"لا تكن فيك عبادة لإله غريب، ولا تسجد لإله أجنبي.","81:10":"أنا الرب إلهك الذي أنقذك من أرض مصر: افتح فمك واسعا فأملأه خيرا.","81:11":"غير أن شعبي لم يسمع لي، وإسرائيل لم يرض بي.","81:12":"لذلك أسلمتهم إلى عناد قلوبهم. وسلكوا وفقا لمشورات أنفسهم.","81:13":"لو سمع لي شعبي وسلك إسرائيل في طرقي،","81:14":"لكنت أخضعت أعداءهم سريعا، وحولت يدي نحو خصومهم،","81:15":"ولكان مبغضي يتملقونني، ولطالت حقبة عقابهم إلى الأبد.","81:16":"ولكنت أطعم شعبي أفخر الحنطة، وأشبعهم عسلا من الصخرة».","82:1":"الله يترأس ساحة قضائه، وعلى القضاة يصدر حكما.","82:2":"حتى متى تقضون بالظلم وتنحازون إلى الأشرار؟","82:3":"احكموا للذليل واليتيم. وأنصفوا المسكين والبائس.","82:4":"أنقذوا المسكين والفقير؛ أنقذوهما من قبضة الأشرار.","82:5":"هم من غير معرفة وفهم، يتمشون في الظلمة وتتزعزع أسس الأرض من كثرة الجور.","82:6":"أنا قلت: «إنكم آلهة، وجميعكم بنو العلي.","82:7":"لكنكم ستموتون كالبشر، وتنتهي حياتكم مثل كل الرؤساء».","82:8":"قم ياالله قم. دن الأرض، لأنك أنت تمتلك الأمم بأسرها.","83:1":"ياالله لا تصمت. لا تسكت ولا تهدأ ياالله .","83:2":"هوذا أعداؤك ثائرون، ومبغضوك يشمخون برؤوسهم.","83:3":"يتآمرون بالمكر على شعبك، ويكيدون للإيقاع بمن تحميهم.","83:4":"يقولون: «هلم نستأصلهم من بين الأمم، فلا يذكر اسم إسرائيل فيما بعد».","83:5":"فإنهم قد تآمروا معا بقلب واحد، وعقدوا حلفا ضدك.","83:6":"عشائر أدوم وبنو إسماعيل، نسل موآب وبنو هاجر.","83:7":"جبال وعمون وعماليق، الفلسطينيون وأهل صور،","83:8":"وقوم أشور أيضا انضموا إليهم، صاروا عونا لبني لوط.","83:9":"افعل بهم كما فعلت بمديان وسيسرا ويابين في نهر قيشون.","83:10":"بادوا في عين دور، وصاروا زبلا للأرض.","83:11":"اجعل مصير أشرافهم كمصير غراب وذئب، وجميع أمرائهم مثل زبح وصلمناع، الذين قالوا: لنستول على مساكن الله.","83:12":"","83:13":"ياإلهي، بددهم كالقش المتطاير، وكالتبن في مهب الريح.","83:14":"كما تحرق النار الغابة، وكما يشعل لهيبها الجبال،","83:15":"هكذا طاردهم بعاصفتك، وأفزعهم بزوبعتك.","83:16":"املاء وجوههم خزيا فيلتمسوا اسمك يارب.","83:17":"ليحل بهم العار والرعب إلى الأبد، وليخزوا ويهلكوا.","83:18":"ويعلموا أنك أنت وحدك، يهوه العلي على الأرض كلها.","84:1":"ما أحلى مساكنك يارب الجنود!","84:2":"تتوق بل تحن نفسي إلى ديار الرب. قلبي وجسمي يرنمان بفرح للإله الحي.","84:3":"العصفور أيضا وجد له وكرا، واليمامة عثرت لنفسها على عش تضع فيه فراخها، بجوار مذابحك يارب الجنود، ياملكي وإلهي.","84:4":"طوبى لمن يسكنون في بيتك، فإنهم يسبحونك دائما.","84:5":"طوبى لأناس أنت قوتهم. المتلهفون لاتباع طرقك المفضية إلى بيتك المقدس.","84:6":"وإذ يعبرون في وادي البكاء الجاف، يجعلونه ينابيع ماء، ويغمرهم المطر الخريفي بالبركات.","84:7":"ينمون من قوة إلى قوة، إذ يمثل كل واحد أمام الله في صهيون.","84:8":"يارب إله الجنود اسمع صلاتي، واصغ إلي ياإله يعقوب.","84:9":"ياالله مجننا، انظر بعين الرحمة إلى من مسحته ملكا.","84:10":"إن يوما واحدا أقضيه داخل ديارك خير من ألف يوم خارجها. اخترت أن أكون بوابا في بيت إلهي على السكن في خيام الأشرار.","84:11":"لأن الرب الإله شمس وترس. الرب يعطي نعمة ومجدا؛ لا يمنع أي خير عن السالكين بالاستقامة.","84:12":"يارب الجنود، طوبى للإنسان المتكل عليك.","85:1":"يارب، قد رضيت عن أرضك، وأرجعت سبي يعقوب.","85:2":"إذ غفرت لشعبك إثمهم، وسترت خطاياهم كلها.","85:3":"سكنت كل سخطك. رجعت عن غضبك الرهيب.","85:4":"ردنا إليك ياالله مخلصنا، واصرف غيظك عنا.","85:5":"أتسخط علينا إلى الأبد؟ أتطيل غضبك من جيل إلى جيل؟","85:6":"أما تحيينا من جديد فيفرح بك شعبك؟","85:7":"أظهر لنا رحمتك يارب، وامنحنا خلاصك.","85:8":"إني أسمع ما يتكلم به الله الرب، فإنه يتكلم بالسلام لشعبه ولأتقيائه، فلا يرجعون إلى الجهالة.","85:9":"حقا إن خلاصه قريب من الذين يخافونه، لكي يقيم المجد في أرضنا.","85:10":"الرحمة والحق تلاقيا، البر والسلام تعانقا.","85:11":"ينبت الحق من الأرض، ويشرف البر من السماء.","85:12":"أيضا يعطي الرب الخير، فتنتج الأرض غلاتها الوافرة.","85:13":"يتقدمه البر، ويمهد الطريق لخطواته.","86:1":"أرهف يارب إلي أذنك، استجب لي، فإني مسكين وبائس.","86:2":"احفظ نفسي فإني تقي ياإلهي، خلص أنت عبدك الواثق بك.","86:3":"ارحمني يارب فإني بك أستغيث طوال النهار.","86:4":"فرح نفس عبدك، فإني إليك أيها السيد أرفع نفسي.","86:5":"لأنك أنت يارب طيب وغفور، وكثير الرحمة لجميع الذين يدعونك.","86:6":"يارب اصغ إلى صلاتي واستمع إلى صوت تضرعاتي.","86:7":"في يوم ضيقي أدعوك لأنك تستجيبني.","86:8":"لا نظير لك بين الآلهة يارب، وليس من يعمل كأعمالك.","86:9":"تقبل جميع الأمم التي صنعتها لتسجد أمامك يارب وتمجد اسمك.","86:10":"فإنك عظيم وصانع عجائب. أنت الله وحدك.","86:11":"يارب علمني طريقك فأسلك بموجب حقك. وحد قلبي ليخاف اسمك.","86:12":"أحمدك يارب إلهي بكامل قلبي، وأمجد اسمك إلى الأبد.","86:13":"لأن رحمتك عظيمة نحوي، وقد نجيت نفسي من الهاوية السفلى.","86:14":"ياالله قد ثار علي المتكبرون، وجماعة الظالمين يطلبون قتلي، غير عابئين بك.","86:15":"إنما أنت يارب إله رحيم ورؤوف وبطيء الغضب ووافر الرحمة والحق.","86:16":"التفت إلي وارحمني. أعطني أنا عبدك قوتك، وخلصني أنا ابن أمتك.","86:17":"اصنع معي آية للخير، فيراها مبغضي ويعتريهم الخزي، فإنك أنت يارب قد أعنتني وعزيتني.","87:1":"أسس الله المدينة على الجبال المقدسة.","87:2":"أحب الرب أبواب صهيون أكثر من جميع مساكن بني يعقوب.","87:3":"يتحدثون عنك بأمور مجيدة يامدينة الله.","87:4":"أذكر مصر وبابل بين الذين يعرفونني، وكذلك فلسطين وصور مع الحبشة، فيقولون: هذا ولد في صهيون.","87:5":"حقا عن صهيون يقولون: «هذا الإنسان وهذا الإنسان ولد فيها، والعلي يثبتها».","87:6":"يدون الرب في سجل إحصاء الشعوب أن هذا ولد هناك.","87:7":"المرنمون والعازفون على السواء يقولون: «فيك كل ينابيع سروري».","88:1":"يارب إله خلاصي، أمامك أصرخ نهارا وليلا.","88:2":"لتأت صلاتي أمامك، أمل أذنك إلى صرختي،","88:3":"فإن نفسي شبعت مصائب، وحياتي تقترب من الموت.","88:4":"حسبت في عداد الهابطين إلى قعر هوة الموت، وكرجل لا قوة له.","88:5":"تركوني أموت كقتلى الحرب الممددين في القبر، الذين لا تعود تذكرهم وتكف يدك عن إغاثتهم.","88:6":"قد طرحتني في الهوة السفلى، في الأماكن المظلمة والعميقة.","88:7":"استقر علي غضبك، وبأمواجك الطامية ذللتني.","88:8":"أبعدت عني أصحابي، وجعلتني عارا عندهم. قد حبست فلا نجاة لي.","88:9":"كلت عيناي من فرط البكاء. إياك يارب دعوت كل يوم باسطا إليك يدي.","88:10":"هل تصنع عجائب للأموات، أم تقوم أشباح الموتى فتمجدك؟","88:11":"أفي القبر تعلن رحمتك، وفي الهاوية أمانتك؟","88:12":"هل في الظلام تعرف عجائبك، وفي أرض النسيان يظهر برك؟","88:13":"أما أنا فإليك أصرخ مستغيثا يارب، وفي الصباح تمثل صلاتي أمامك.","88:14":"لماذا يارب ترفض نفسي، وتحجب عني وجهك؟","88:15":"إنني مسكين، ومشرف على الموت منذ صباي، وقد قاسيت أهوالك، وذهلت.","88:16":"اجتاحني غضبك الشديد وأفنتني أهوالك.","88:17":"أحاطت بي طول النهار كالمياه وأطبقت علي كلها.","88:18":"فرقت عني الأصدقاء فصار الظلام ملازمي.","89:1":"أترنم بمراحم الرب إلى الأبد، وأعلن بفمي أمانتك من جيل إلى جيل،","89:2":"لأني قلت إن مراحمك ثابتة إلى الأبد، وقد ثبت في السماوات أمانتك.","89:3":"قد قلت: إني أقمت عهدا مع الملك الذي اخترته، أقسمت لداود عبدي.","89:4":"أثبت نسلك إلى الأبد، وأبقي عرشك قائما من جيل إلى جيل.","89:5":"السماوات نفسها تشيد بعجائبك أيها الرب، والملائكة القديسون بأمانتك.","89:6":"فمن في السماء يعادل الرب؟ ليس بين الكائنات السماوية من يماثله.","89:7":"إنه إله مهوب جدا في محفل الملائكة القديسين، ومخوف كثيرا عند جميع المحيطين به.","89:8":"من مثلك أيها الرب إله الجنود، الرب القدير، وأمانتك محيطة بك؟","89:9":"أنت متسلط على هياج البحر، فتهديء أمواجه عند ارتفاعها.","89:10":"أنت سحقت قوة مصر فصارت كقتيل. وبددت أعداءك بقدرتك العظيمة.","89:11":"أنت ملك السماوات والأرض أيضا. أنت مؤسس المسكونة وكل ما فيها.","89:12":"أنت خالق الشمال والجنوب، وباسمك يترنم جبلا تابور وحرمون.","89:13":"أنت ذو القدرة العظيمة. يدك قوية ويمناك رفيعة.","89:14":"البر والقضاء قاعدتا عرشك، الرحمة والحق يتقدمان حضرتك.","89:15":"طوبى للشعب الذي يستجيب لهتاف البوق فيسلك في نور محياك أيها الرب.","89:16":"باسمك يبتهجون طول النهار، وببرك يسمون.","89:17":"فإنك أنت قوتهم التي بها يفخرون، وبرضاك يعلو شأننا.","89:18":"لأن الرب هو حمايتنا، وملكنا هو قدوس إسرائيل.","89:19":"فبالرؤيا كلمت أنبياءك قديما وقلت لعبيدك الأمناء: هيأت عونا للجبار ورفعت شابا من الشعب.","89:20":"وجدت داود عبدي فمسحته بزيتي المقدس.","89:21":"أثبته بيدي، وأشدده بقوتي.","89:22":"لا يبتزه عدو، ولا يضايقه الإنسان الأثيم.","89:23":"إنما أسحق أعداءه أمامه، وأصرع مبغضيه.","89:24":"أمانتي ورحمتي ترافقانه، وباسمي يعلو شأنه.","89:25":"أطلق يده على البحار ويمينه على الأنهار.","89:26":"هو يدعوني قائلاَ: أنت أبي وإلهي وصخرة خلاصي.","89:27":"أقيمه بكرا يسمو على ملوك الأرض.","89:28":"أحفظ رحمتي له إلى الأبد، ويثبت له عهدي.","89:29":"أديم إلى الأبد نسله وعرشه دوام السماوات.","89:30":"إن انحرف بنوه عن طاعة شريعتي ولم يسلكوا وفق أحكامي،","89:31":"إن نقضوا فرائضي ولم يراعوا وصاياي،","89:32":"فإني أفتقد معصيتهم بالعصا وإثمهم بالبلايا.","89:33":"ولكني لا أنزع رحمتي عنه، ولا أنكث وعدي.","89:34":"عهدي لا أنقضه، ولا أبدل ما نطق به فمي.","89:35":"فقد أقسمت بقداستي مرة، ولا أكذب على داود:","89:36":"نسله يدوم إلى الدهر، وعرشه يبقى أمامي بقاء الشمس.","89:37":"يظل ثابتا إلى الأبد ثبات القمر الشاهد الأمين في السماء.","89:38":"لكنك رفضت ورذلت وغضبت على الملك الذي مسحته،","89:39":"وتنكرت لعهدك مع عبدك، لطخت تاجه بالتراب.","89:40":"هدمت كل أسواره وحولت حصونه خرابا.","89:41":"نهبه كل عابري السبيل، وصار هزأة عند جيرانه.","89:42":"رفعت يمين ظالميه وأبهجت جميع أعدائه.","89:43":"رددت حد سيفه، ولم تنصره في القتال.","89:44":"أبطلت بهاءه وطرحت عرشه أرضا.","89:45":"قصرت أيام شبابه وغطيته بالخزي.","89:46":"حتى متى يارب؟ هل إلى الأبد تظل محتجبا عني، يتقد غضبك كالنار؟","89:47":"اذكر قصر عمري وأنك خلقت كل بني آدم للزوال.","89:48":"أي إنسان يحيا ولا يرى الموت؟ ومن ينجي نفسه من قبضة الهاوية؟","89:49":"أين مراحمك السالفة يارب، التي أقسمت في أمانتك أن تظهرها لداود عبدك؟","89:50":"اذكر يارب عار عبيدك الذي تحملته في صدري من جميع الشعوب،","89:51":"العار الذي عيرنا به أعداؤك يارب، إذ عيروا خطوات الملك الذي مسحته.","89:52":"تبارك الرب إلى الأبد. آمين ثم آمين.","90:1":"يارب أنت كنت ملجَأ لنا نلوذ به جيلا بعد جيل.","90:2":"قبل أن أوجدت الجبال أو كونت المسكونة، أنت الله من الأزل وإلى الأبد.","90:3":"تعيد الإنسان إلى التراب قائلا: عودوا إليه يابني آدم.","90:4":"فإن ألف سنة في عينيك كيوم أمس العابر، أو مثل هزيع من الليل.","90:5":"تجرف البشر كما يجرفهم الطوفان، فيزولون كالحلم عند الصباح مثل العشب الذي ينمو.","90:6":"يزهر في الصباح وينمو، وفي المساء يقطع ويجف.","90:7":"إن غضبك قد أفنانا وسخطك قد روعنا.","90:8":"جعلت آثامنا أمامك وخطايانا الخفية ظاهرة لديك.","90:9":"لأن أيامنا كلها تنقضي في غضبك الشديد، وأعوامنا تتلاشى كزفرة.","90:10":"قد نعيش سبعين سنة، وإن كنا ذوي عافية فثمانين وأفضل أيامنا تعب وبلية، لأنها سرعان ما تزول فنطير.","90:11":"من يعرف شدة غضبك؟ إن سخطك هو بحسب مهابتك؟","90:12":"علمنا إحصاء أيامنا، لعلنا نتعقل بقلب حكيم.","90:13":"إلى متى يطول يارب غضبك؟ ارجع وتعطف على عبيدك.","90:14":"أفض علينا باكرا من رحمتك، فنترنم فرحا ونبتهج طوال أعمارنا.","90:15":"فرحنا بمقدار الأيام التي بليتنا بها، وبمقدار السنين التي رأينا فيها المصائب","90:16":"ليظهر صنيعك أمام عبيدك وجلالك أمام أبنائهم.","90:17":"ولتكن نعمة الرب إلهنا علينا. أنجح عمل أيدينا، نعم أنجح لنا عمل أيدينا.","91:1":"المحتمي بقدس أقداس العلي، في ظل القدير يبيت،","91:2":"أقول للرب: أنت ملجإي وحصني، إلهي الذي به وثقت","91:3":"لأنه ينقذك حقا من فخ الصياد ومن الوباء المهلك.","91:4":"بريشه الناعم يظللك، وتحت أجنحته تحتمي، فتكون لك وعوده الأمينة ترسا ومتراسا،","91:5":"فلا تخاف من هول الليل ولا من سهم يطير في النهار.","91:6":"ولا من وباء يسري في الظلام، ولا من هلاك يفسد في الظهيرة.","91:7":"يتساقط عن جانبك ألف إنسان، وعن يمينك عشرة آلاف، وأنت لا يمسك سوء.","91:8":"إنما تشاهد بعينيك معاقبة الأشرار.","91:9":"لأنك قلت: الرب ملجإي، واتخذت العلي ملاذا،","91:10":"فلن يصيبك شر ولن تقترب بلية من مسكنك","91:11":"فإنه يوصي ملائكته بك لكي يحفظوك في جميع طرقك.","91:12":"على أيديهم يحملونك لئلا تصدم بحجر قدمك.","91:13":"تطأ على الأسد والأفعى، تدوس الشبل والثعبان.","91:14":"قال الرب: أنجيه لأنه تعلق بي. أرفعه لأنه عرف اسمي.","91:15":"يدعوني فأستجيب له، أرافقه في الضيق، أنقذه وأكرمه","91:16":"أطيل عمره، وأريه خلاصي.","92:1":"ما أحسن تقديم الشكر لك يارب والترنيم لاسمك أيها العلي!","92:2":"ما أحسن أن يلهج برحمتك في الصباح، وبأمانتك في الليالي،","92:3":"على أنغام الآلات الموسيقية الوترية، وعلى الرباب وألحان العود العذبة!","92:4":"سأشيد بكل ما عملته يداك لأنك يارب فرحتني بصنيعك.","92:5":"يارب ما أعظم أعمالك! أفكارك عميقة جدا،","92:6":"لا يعرفها الغبي ولا يفهمها الجاهل.","92:7":"إذا زها الأشرار كالعشب، وأزهر جميع فاعلي الإثم فإنهم كالعشب يبادون إلى الأبد.","92:8":"أما أنت يارب فمتعال إلى الأبد.","92:9":"فيارب، ها هم أعداؤك يهلكون إلى الدهر، إذ يتبدد جميع فاعلي الإثم.","92:10":"أما أنا فترفع شأني كما يرتفع قرن الثور الوحشي، وأنتعش كمن تدهن بزيت جديد","92:11":"وتنظر عيناي عقاب أعدائي المتربصين لي، وتسمع أذناي بمصير فاعلي الشر الثائرين علي.","92:12":"الصديق يزهو كالنخلة وينمو كالأرز في لبنان.","92:13":"لأن المغروسين في بيت الرب يزدهرون في ديار بيت إلهنا","92:14":"يثمرون أيضا في الشيخوخة، ويظلون موفوري العافية والنضرة","92:15":"ليشهدوا أن الرب مستقيم. إنه صخرتي وليس فيه سوء.","93:1":"الرب قد ملك مرتديا الجلال. متنطقا بحزام القوة. الأرض تثبتت فلن تتزعزع.","93:2":"عرشك ثابت منذ القديم، لأنك الله منذ الأزل.","93:3":"يارب قد رفعت الأنهار صوتها. ترفع الأنهار صوت موجها الهادر.","93:4":"الرب في العلاء أعظم من صوت المياه الغزيرة ومن أمواج البحر الهائلة.","93:5":"أقوالك ثابتة إلى الأبد، وببيتك أيها الرب تليق القداسة مدى الدهر.","94:1":"يارب أنت إله الانتقام، فتجل بغضبك.","94:2":"قم ياديان الأرض وجاز المتكبرين على أعمالهم.","94:3":"إلى متى يارب يشمت الأشرار فرحين؟","94:4":"إلى متى يهذر عمال الإثم ويتواقحون ويتباهون بأنفسهم؟","94:5":"يسحقون شعبك يارب ويضطهدونه،","94:6":"يقتلون الأرملة والغريب ويذبحون اليتيم.","94:7":"ويقولون: «الرب لا يرى هذا، وإله إسرائيل لا يبالي».","94:8":"افهموا ياأغبياء الشعب! ياجهال متى تتعقلون؟","94:9":"صانع الأذن ألا يسمع؟ جابل العين ألا يبصر؟","94:10":"مؤدب الأمم ألا يزجر وهو الذي يعلم الإنسان الحكمة؟","94:11":"الرب يعلم أفكار الإنسان ويعرف أنها باطلة.","94:12":"طوبى للإنسان الذي تؤدبه، وتعلمه من شريعتك يارب!","94:13":"لتريحه من أيام السوء، إلى أن يموت الشرير ويتوارى في مثواه.","94:14":"لا يرفض الله شعبه، ولا ينبذ خاصته.","94:15":"لأن القضاء يصبح عدلا ويحبه جميع المستقيمي القلوب.","94:16":"من يتولى عني محاربة الأشرار؟ من يجابه عني فاعلي الإثم؟","94:17":"لو لم يكن الرب معيني لسكنت نفسي القبر.","94:18":"قلت: قد زلت قدمي. ولكن رحمتك يارب صارت لي سندا.","94:19":"عند كثرة همومي في داخلي تبتهج نفسي بتعزياتك.","94:20":"أيحالفك ملك الشر المختلق إثما ليجعل الظلم شريعة للقضاء؟","94:21":"يجتمعون معا للقضاء على حياة الصديق، ويحكمون على البريء بالموت.","94:22":"ولكن الرب هو حصني المنيع؛ إلهي هو الصخرة التي بها أحتمي.","94:23":"غير أن الرب إلهنا يعاقبهم على إثمهم، ويبيدهم بشرهم.","95:1":"هيا نرنم عاليا للرب، ونهتف فرحا لصخرة خلاصنا.","95:2":"لنتقدم أمام حضرته بالشكر، ونهتف له بالترنيم.","95:3":"لأن الرب إله عظيم، وملك كبير على جميع الآلهة.","95:4":"في يده أعماق الأرض، وقمم الجبال ملك له.","95:5":"له البحر، وهو قد صنعه، ويداه كونتا اليابسة.","95:6":"تعالوا نسجد وننحني، لنركع أمام الرب صانعنا،","95:7":"فإنه هو إلهنا، ونحن رعيته وقطيعه الذي يقوده بيده. اليوم إن سمعتم صوته،","95:8":"فلا تقسوا قلوبكم، كما حدث في يوم مسة (أي الامتحان) في الصحراء،","95:9":"عندما امتحنني آباؤكم واختبروني وشهدوا جميع عجائبي.","95:10":"أربعين سنة رفضت ذلك الجيل، وقلت: «هم شعب أضلتهم قلوبهم ولم يعرفوا قط طرقي».","95:11":"فأقسمت في غضبي قائلا: «إنهم لن يدخلوا مكان راحتي».","96:1":"رنموا للرب ترنيمة جديدة. رنموا للرب ياساكني الأرض جميعا.","96:2":"رنموا للرب. باركوا اسمه. بشروا بخلاصه يوما فيوما.","96:3":"أعلنوا مجده بين الأمم، وعجائبه بين الشعوب كلها.","96:4":"فإن الرب عظيم وجدير بكل حمد؛ هو مرهوب أكثر جدا من جميع الآلهة.","96:5":"لأن كل آلهة الشعوب أصنام باطلة أما الرب فهو صانع السماوات.","96:6":"الجلال والبهاء أمامه، القوة والجمال في مقدسه.","96:7":"قدموا للرب ياجميع قبائل الشعوب، قدموا للرب مجدا وقوة.","96:8":"قدموا للرب المجد الواجب لاسمه. أحضروا تقدمة وادخلوا هيكله واعبدوه","96:9":"اسجدوا للرب بزينة مقدسة، ارتعدوا أمامه ياجميع ساكني الأرض.","96:10":"نادوا بين الأمم أن الرب قد ملك. هوذا الأرض قد استقرت مطمئنة لأنه يدين الشعوب بالإنصاف.","96:11":"لتفرح السماوات ولتبتهج الأرض وليهدر البحر بهجة بأمواجه وبكل ما يحويه.","96:12":"ليتهلل الحقل وكل ما فيه، فتترنم فرحا جميع أشجار الغابة","96:13":"في حضرة الرب لأنه آت ليدين العالم بالعدل والشعوب بالحق.","97:1":"الرب قد ملك، فلتبتهج الأرض، وليفرح أهل الجزر الكثيرة.","97:2":"حوله الغيوم والضباب، والعدل والحق قاعدة عرشه.","97:3":"تخرج منه نار وتحرق خصومه المحيطين به.","97:4":"أنارت بروقه المسكونة. رأت الأرض ذلك فارتجفت.","97:5":"ذابت الجبال كالشمع من نظرة الرب سيد الأرض كلها.","97:6":"أذاعت السماوات عدله ويرى جميع الشعوب مجده.","97:7":"يخزى كل عابدي التماثيل المنحوتة، المفتخرين بالأصنام. اسجدوا له ياجميع الآلهة.","97:8":"سمعت صهيون ففرحت، وابتهجت بنات يهوذا بأحكامك يارب.","97:9":"لأنك أنت العلي فوق كل الأرض، والمتسامي جدا على كل الآلهة.","97:10":"يامحبي الرب، أبغضوا الشر. الرب حارس نفوس أتقيائه، وهو ينقذهم من أيدي الأشرار.","97:11":"قد زرع نور للصديق وفرح للمستقيمي القلب.","97:12":"افرحوا أيها الصديقون بالرب، وارفعوا الشكر لاسمه الأقدس.","98:1":"رنموا للرب ترنيمة جديدة، لأنه قد صنع عجائب. وبيمينه وذراعه المقدسة أحرز خلاصا.","98:2":"أعلن الرب خلاصه؛ أمام أنظار الأمم كشف بره.","98:3":"ذكر رحمته وأمانته لبيت إسرائيل. رأت كل أقاصي الأرض خلاص إلهنا.","98:4":"اهتفوا للرب ياساكني الأرض، اهتفوا فرحا ورنموا وأنشدوا.","98:5":"أنشدوا للرب بعزف عود وبصوت نشيد.","98:6":"اهتفوا أمام الرب الملك نافخين بأبواق نحاسية وأبواق قرنية.","98:7":"ليهتف البحر بأمواجه وبكل ما فيه، والمسكونة أيضا ومن عليها.","98:8":"لتصفق الأنهار بالأيدي، وتترنم الجبال معا.","98:9":"أمام الرب لأنه جاء ليدين الأرض بالعدل والشعوب بالإنصاف.","99:1":"الرب قد ملك. فارتعدت الشعوب. جلس فوق ملائكة الكروبيم فاهتزت الأرض.","99:2":"ما أعظم الرب في صهيون وهو متعال فوق كل الشعوب.","99:3":"يحمدون اسمك العظيم المرهوب لأنه قدوس!","99:4":"قوة الملك في حب الحق. وأنت يارب ثبت الإنصاف وأجريت الحق والعدل في إسرائيل.","99:5":"عظموا الرب إلهنا واسجدوا عند موطيء قدميه. لأنه قدوس!","99:6":"موسى وهرون بين كهنته، وصموئيل بين الداعين باسمه، دعوا الرب فاستجاب لهم.","99:7":"خاطبهم في عمود السحاب: فأطاعوا أقواله ومارسوا أحكامه التي أعطاهم.","99:8":"أيها الرب إلهنا، أنت استجبت لهم. غفرت لهم إثمهم، وإن كنت قد عاقبتهم جزاء أفعالهم.","99:9":"عظموا الرب إلهنا واسجدوا في جبل المقدس، لأن الرب إلهنا قدوس.","100:1":"اهتفوا للرب ياسكان الأرض جميعا.","100:2":"اعبدوا الرب ببهجة، وامثلوا أمامه مترنمين.","100:3":"اعلموا أن الرب هو الله . هو صنعنا ونحن له، نحن شعبه وقطيع مرعاه.","100:4":"ادخلوا أبوابه حامدين، دياره مسبحين. اشكروه وباركوا اسمه.","100:5":"فإن الرب صالح، إلى الأبد رحمته وأمانته دائمة من جيل إلى جيل.","101:1":"سأشيد برحمتك وعدلك يارب، ولك أرنم.","101:2":"أسلك بتعقل في طريق الكمال. متى تأتي يارب لمعونتي؟ أسلك في وسط بيتي باستقامة قلبي.","101:3":"لن أضع نصب عيني أمرا باطلا، فإني أبغض عمل الضالين لئلا يلتصق بي.","101:4":"ليفارقني القلب المنحرف فلا أرتكب شرا.","101:5":"أبيد كل من يغتاب قريبه سرا؛ وذو العين المتشامخة والقلب المتكبر لا أحتمله.","101:6":"ترعى عيناي الأمناء في الأرض ليسكنوا معي. وخدامي هم السالكون في طريق الكمال.","101:7":"لا يقيم داخل بيتي الغشاشون، والكذبة لا يمثلون أمامي.","101:8":"أقضي في كل صباح على جميع الأشرار في أرضنا، حتى أستأصل من مدينة الرب كل فاعلي الإثم.","102:1":"يارب استمع صلاتي وليصل إليك صراخي.","102:2":"لا تحجب وجهك عني في يوم ضيقي، بل أمل نحوي أذنك. استجب لي سريعا يوم أدعوك،","102:3":"لأن أيامي قد تبددت كالدخان، وعظامي اضطرمت كالوقيد.","102:4":"قلبي منكوب ويابس كالعشب الجاف، حتى غفلت عن أكل طعامي.","102:5":"التصقت عظامي بلحمي من جراء أناتي المرتفعة.","102:6":"صرت أشبه ببجع البراري، ومثل بومة الخرائب.","102:7":"أرقت، وصرت كالعصفور المنفرد على السطح.","102:8":"عيرني أعدائي طول النهار، والساخرون الحانقون علي، جعلوا اسمي لعنة،","102:9":"فقد أكلت الرماد كالخبز، ومزجت شرابي بالدموع،","102:10":"بسبب غضبك وسخطك لأنك قد رفعتني ثم طرحتني بعنف.","102:11":"عمري أشبه بظل متقلص، وأنا مثل العشب أذوي.","102:12":"أما أنت يارب فجالس على عرشك إلى الأبد، وذكرك باق مدى الدهر.","102:13":"أنت تقوم وترحم صهيون لأنه قد أزف وقت إظهار رضاك،","102:14":"فإن عبيدك يسرون بحجارتها، يشتاقون إلى ذرات ترابها.","102:15":"فتخشى الأمم اسم الرب، ويهاب جميع ملوك الأرض مجدك.","102:16":"لأن الرب بنى صهيون وتجلى في مجده.","102:17":"التفت إلى صلاة البائسين ولم يرفض دعاء المتضايقين.","102:18":"يكتب هذا للجيل الآتي الذي سيخلق فيسبح الرب.","102:19":"تطلع الرب من علياء مقدسه، من السماوات نظر إلى الأرض،","102:20":"ليسمع أنين شعبه الأسير ويحرر المقضي عليهم بالموت.","102:21":"لكي يذاع اسم الرب في صهيون، ويسبح أيضا في أورشليم،","102:22":"عندما تجتمع الشعوب والممالك جميعا ليعبدوا الرب.","102:23":"الرب أضعفني وأنا في ريعان قوتي وقصر أيامي.","102:24":"حتى قلت: «يارب أنت حي إلى الأبد. لا تقصفني في منتصف عمري، قبل أن أبلغ الشيخوخة.","102:25":"من قدم أسست الأرض، والسماوات هي صنع يديك.","102:26":"هي زائلة أما أنت فباق. تبلى كلها كالثوب. وتستبدلها كما يستبدل الرداء القديم بالجديد.","102:27":"لكنك أنت الدائم الخالد، وسنوك لن تنتهي.","102:28":"أبناء عبيدك يدومون، ونسلهم يظل ثابتا أمامك».","103:1":"باركي يانفسي الرب، وليحمد كل ما في داخلي اسمه القدوس.","103:2":"باركي يانفسي الرب، ولا تنسي جميع خيراته.","103:3":"إنه يغفر جميع آثامك ويبريء كل أمراضك.","103:4":"ويفدي من الموت حياتك ويتوجك بالرحمة والرأفة.","103:5":"ويشبع بالخير عمرك فيتجدد كالنسر شبابك.","103:6":"الرب يحكم بالعدل وينصف جميع المظلومين.","103:7":"أطلع موسى على طرقه وبني إسرائيل على أفعاله.","103:8":"الرب رحيم ورؤوف، بطيء الغضب ووافر الرحمة.","103:9":"لا يسخط إلى الأبد ولا يحقد إلى الدهر.","103:10":"لم يعاملنا حسب خطايانا ولم يجازنا حسب آثامنا.","103:11":"مثل ارتفاع السماوات فوق الأرض، تعاظمت رحمته على متقيه.","103:12":"وكبعد المشرق عن المغرب أبعد عنا معاصينا.","103:13":"مثلما يعطف الأب على بنيه يعطف الرب على أتقيائه.","103:14":"لأنه يعرف ضعفنا ويذكر أننا جبلنا من تراب.","103:15":"أيام الإنسان مثل العشب وزهر الحقل،","103:16":"تهب عليه الريح فيفنى، ولا يعود موضعه يتذكره فيما بعد.","103:17":"أما رحمة الرب فهي من الأزل وإلى الأبد على متقيه، وعدله يمتد إلى بني البنين،","103:18":"للذين يراعون عهده والذين يتذكرون وصاياه ويمارسونها.","103:19":"الرب ثبت في السماوات عرشه، ومملكته على جميع البشر تسود.","103:20":"باركوا الرب ياملائكته المقتدرين قوة، الفاعلين أمره فور صدور كلمته.","103:21":"باركوا الرب ياجميع جنوده، ياخدامه العاملين رضاه.","103:22":"باركوا الرب ياكل خليقته، في كل مواضع سلطانه. باركي يانفسي الرب.","104:1":"باركي يانفسي الرب. ما أعظمك أيها الرب إلهي فأنت متسربل بالمجد والجلال.","104:2":"أنت اللابس النور كثوب، والباسط السماوات كخيمة.","104:3":"المقيم بيتك فوق المياه العليا، الجاعل من السحب مركبتك، السائر على أجنحة الريح،","104:4":"الصانع ملائكتك رياحا وخدامك لهيب نار.","104:5":"المؤسس الأرض على قواعدها فلا تتزعزع إلى الدهر والأبد.","104:6":"غمرتها باللجج كثوب فتغطت رؤوس الجبال بالمياه.","104:7":"من زجرك تهرب المياه، ومن قصف رعدك تفر.","104:8":"ارتفعت الجبال وغاصت الوهاد، إلى الموضع الذي خصصته لها.","104:9":"وضعت للبحر حدا لا يتعداه حتى لا تعود مياهه تغمر الأرض.","104:10":"أنت المفجر الينابيع في الأودية، فتجري بين الجبال.","104:11":"تسقي جميع حيوانات البرية، وتروي منها حمير الوحش عطشها.","104:12":"إلى جوارها تعشش طيور السماء، وتغرد بين الأغصان.","104:13":"تسقي الجبال من أمطار سمائك، وتمتلىء الأرض من أثمار أعمالك.","104:14":"أنت المنبت عشبا للبهائم وخضرة لخدمة الإنسان، لإنتاج خبز من الأرض،","104:15":"وخمر تفرح قلب الإنسان وتورد وجهه فيلمع كبريق الزيت، وخبز يسند قلبه.","104:16":"ترتوي أشجار الرب، أرز لبنان الذي غرسه.","104:17":"حيث تبني الطيور أوكارها، أما اللقلق ففي السرو مبيته.","104:18":"الجبال العالية موطن الوعول، والصخور ملجأ للوبار.","104:19":"أنت صنعت القمر لتحديد مواقيت الشهور، والشمس تعرف موعد مغربها.","104:20":"تحل الظلمة فيصير ليل يجوس فيه كل حيوان الغابة.","104:21":"تزمجر الأشبال طلبا لفريستها ملتمسة طعامها من عند الله.","104:22":"وما إن تشرق الشمس حتى تعود إلى عرائنها وتربض فيها","104:23":"أما الإنسان فيخرج إلى عمله وشغله حتى المساء.","104:24":"يارب ما أعظم أعمالك، كلها صنعت بحكمة، فامتلأت الأرض من غناك.","104:25":"هذا البحر الكبير الواسع، الذي يعج بمخلوقات لا تحصى من حيوانات مائية صغيرة وكبيرة","104:26":"تجري فيه السفن، تمرح فيه الحيتان التي خلقتها.","104:27":"تلتفت جميعها إليك كي ترزقها طعامها في أوانه.","104:28":"أنت تعطيها وهي تلتقط، تبسط يدك لها فتشبع خيرا.","104:29":"تحجب عنها وجهك فتفزع. تقبض أرواحها فتموت، وإلى ترابها تعود.","104:30":"ترسل روحك فتخلق ثانية وتجدد وجه الأرض.","104:31":"مجد الرب يدوم إلى الأبد. الرب يفرح بأعماله.","104:32":"ينظر إلى الأرض فترتجف، يمس الجبال فتمتليء دخانا","104:33":"أرنم للرب وأشدو لإلهي مادمت حيا.","104:34":"فيلذ له نشيدي، وأنا أفرح بالرب.","104:35":"لينقطع الخطاة من الأرض، وليبد الأشرار. باركي يانفسي الرب. هللويا.","105:1":"قدموا الشكر للرب. ادعوا باسمه. عرفوا بأعماله بين الشعوب.","105:2":"غنوا له، اشدوا له. حدثوا بكل عجائبه.","105:3":"تباهوا باسمه القدوس، لتفرح قلوب طالبي الرب.","105:4":"اطلبوا الرب وقوته، التمسوا وجهه دائما.","105:5":"اذكروا عجائبه التي صنع، معجزاته وأحكامه التي نطق بها.","105:6":"ياذرية إبراهيم عبده، يابني يعقوب الذين اختارهم.","105:7":"هو الرب إلهنا، أحكامه تملأ الأرض كلها.","105:8":"لم ينس عهده قط ولا وعده الذي قطعه إلى ألف جيل،","105:9":"العهد الذي أبرمه مع إبراهيم، والقسم الذي أقسم به لإسحق.","105:10":"ثم ثبته ليعقوب فريضة، ولإسرائيل ميثاقا أبديا،","105:11":"قائلا: «لك أعطي أرض كنعان نصيب ميراث لكم».","105:12":"إذ كانوا قلة بعد، نفرا ضئيلا متغربين في الأرض.","105:13":"متنقلين من أمة إلى أمة، ومن مملكة إلى أخرى.","105:14":"فلم يدع أي إنسان يظلمهم، بل وبخ ملوكا من أجلهم.","105:15":"قائلا: «لا تمسوا مسحائي، ولا تؤذوا أنبيائي».","105:16":"ثم أفشى مجاعة في الأرض، وقطع الخبز قوام طعامهم.","105:17":"لكنه أرسل أمامهم يوسف (منقذهم)، فبيع عبدا.","105:18":"آذوا بالقيود قدميه، وبالحديد طوقوا عنقه.","105:19":"إلى أن تحقق تفسيره للأحلام في أوانه، وبرهنت كلمة الرب صدقه.","105:20":"فأرسل الملك وأطلقه، حاكم الشعب حرر ه.","105:21":"أقامه سيدا على قصره، ومتسلطا على جميع أملاكه.","105:22":"يتصرف بولاته حسب مسرته، ويلقن شيوخه الحكمة.","105:23":"ثم جاء إسرائيل إلى أرض مصر. تغرب يعقوب في بلد حام.","105:24":"فكثر الله شعبه، وجعله أقوى من أعدائه،","105:25":"الذين حول قلوبهم ليبغضوا شعبه، ويكيدوا لعبيده.","105:26":"عندئذ أرسل موسى عبده وهارون مختاره.","105:27":"فأجريا بينهم آياته، وصنعا عجائب في مصر.","105:28":"بعث ظلاما، تغشت به الأرض، ولكن المصريين عاندوا كلمته.","105:29":"حول مياههم إلى دم وأمات أسماكهم.","105:30":"فاضت أرضهم ضفادع حتى بلغت مخادع ملوكهم.","105:31":"أمر فأقبل الذباب والبعوض فانتشر في كل أرضهم","105:32":"أمطر عليهم بردا وألهب أرضهم بالبروق.","105:33":"ضرب كرومهم وتينهم، وهشم كل أشجارهم","105:34":"أمر، فتوافد الجراد الطيار والزحاف بأعداد لا تحصى،","105:35":"فالتهم كل عشب أرضهم، وأكل ثمار حقولهم.","105:36":"ثم قتل الرب جميع أبكار أرضهم، أوائل ثمار خصوبتهم جميعا.","105:37":"وأخرج شعبه محملين بفضة وذهب، ولم يتعثر في المسير من عشائرهم واحد.","105:38":"فرح أهل مصر بخروجهم لأن رعبهم غلب عليهم.","105:39":"نشر سحابة فوق شعبه، غطاء لهم، وأرسل نارا تضيء لهم ليلا.","105:40":"طلبوا طعاما فبعث لهم طيور السلوى ومن خبز السماء أشبعهم.","105:41":"فلق الصخرة وفجر منها المياه، فجرت في الصحراء كأنها نهر.","105:42":"لأنه ذكر كلمته المقدسة التي وعد بها إبراهيم عبده.","105:43":"وهكذا أخرج شعبه من مصر بابتهاج ومختاريه بترانيم الظفر.","105:44":"ووهبهم أراضي الأمم، فامتلكوا غلات تعبت فيها شعوب أخر ى.","105:45":"ليمارسوا فرائضه ويطيعوا شرائعه. هللويا.","106:1":"هللويا. قدموا الشكر للرب فإنه صالح، لأن رحمته إلى الأبد تدوم.","106:2":"من ذا يحدث بأفعال الرب الجبارة، ويخبر بكل تسبيحه؟","106:3":"طوبى للعاملين بالعدل والبر في كل حين.","106:4":"يارب، اذكرني في رضاك على شعبك. تعهدني بخلاصك.","106:5":"لكي أشهد نجاح مختاريك ولأفرح بفرح أمتك، وأفتخر مع ميراثك.","106:6":"قد أخطأنا مع آبائنا وارتكبنا الإثم والشر.","106:7":"لم يفهم آباؤنا في مصر عجائبك، ولم يتذكروا وفرة مراحمك، بل تمردوا عليك عند البحر الأحمر.","106:8":"لكنك خلصتهم من أجل اسمك إعلانا لقوتك العظيمة.","106:9":"انتهرت البحر الأحمر، فجف، واجتزت بهم عبر اللجج كأنهم على أرض جافة","106:10":"أنقذتهم من يد مبغضيهم وافتديتهم من قبضة العدو.","106:11":"غمرت المياه مطارديهم حتى لم يبق منهم واحد.","106:12":"عندئذ آمنوا بكلامه وشدوا بتسبيحه.","106:13":"ولكن سرعان ما نسوا أعماله! لم ينتظروا مشورته.","106:14":"بل انصاعوا لشهوتهم الشديدة في البرية، وتحدوا الله في الصحراء.","106:15":"فلبى سؤلهم ولكنه أصاب نفوسهم بالسقم.","106:16":"ثم حسدوا موسى في المخيم، وأيضا هارون المقدس للرب.","106:17":"انفتحت الأرض وابتلعت داثان، وأطبقت على قوم أبيرام.","106:18":"واشتعلت نار وسط جماعة قورح، أحرق لهيبها الأشرار.","106:19":"صاغوا عجلا في حوريب، وسجدوا لتمثال مسبوك.","106:20":"استبدلوا إلههم المجيد بصورة ثور آكل عشب.","106:21":"نسوا الله مخلصهم الذي صنع العظائم في مصر،","106:22":"المعجزات في أرض حام، والآيات المخيفة عند البحر الأحمر.","106:23":"فأوشك أن يبيدهم كقوله، لولا أن موسى مختاره وقف في الثغرة أمامه يشفع فيهم ليرد غضبه فلا يهلكهم.","106:24":"ثم استهانوا بالأرض الشهية ولم يصدقوا كلام الرب.","106:25":"بل تذمروا داخل خيامهم، غير منصتين لصوت الرب.","106:26":"فأقسم أن يهلكهم في البرية،","106:27":"يسقط ذريتهم بين الأمم، ويشتتهم في البلدان.","106:28":"وتعلقوا ببعل فغور وأكلوا ذبائح الموتى.","106:29":"وأثاروا غضب الرب بأعمالهم الشريرة، فتفشى بينهم وبأ مفاجيء.","106:30":"فوقف فينحاس وأجرى القضاء، فامتنع الوبأ.","106:31":"فحسب له ذلك برا جيلا فجيلا إلى الأبد.","106:32":"ثم أسخطوا الرب عند مياه مريبة (أي الخصومة) حتى تأذى موسى بسببهم،","106:33":"إذ استفزوا روحه فأفرطت شفتاه بالكلام.","106:34":"لم يستأصلوا الشعوب مثلما أمرهم الرب.","106:35":"بل خالطوا الأمم الوثنية وتعلموا أعمالهم.","106:36":"تعبدوا لأوثانهم فصارت لهم فخا.","106:37":"ضحوا بأبنائهم وبناتهم للشياطين.","106:38":"سفكوا دما بريئا، دم بنيهم وبناتهم الذين ذبحوهم لأصنام الكنعانيين، فتدنست الأرض بالدماء.","106:39":"لذلك تنجسوا بأعمالهم، وخانوا الرب بأفعالهم","106:40":"فالتهب غضب الرب على شعبه، ومقت ميراثه.","106:41":"وأسلمهم إلى أيدي الأمم، فتسلط عليهم مبغضوهم.","106:42":"وضايقهم أعداؤهم حتى ذلوا تحت أيديهم.","106:43":"مرات كثيرة أنقذهم، أما هم فعصوه وانحطوا في آثامهم.","106:44":"غير أنه التفت إلى ضيقتهم إذ سمع صراخهم.","106:45":"تذكر عهده لهم ورق لهم حسب كثرة رحمته،","106:46":"فأنالهم حظوة لدى جميع آسريهم.","106:47":"خلصنا أيها الرب إلهنا، واجمع شملنا من بين الأمم لنرفع الشكر لاسمك القدوس ونفتخر بتسبيحك.","106:48":"مبارك الرب إله إسرائيل من الأزل إلى الأبد. وليقل الشعب كله: آمين. هللويا.","107:1":"ارفعوا الشكر للرب لأنه صالح، ورحمته إلى الأبد تدوم.","107:2":"ليقل هذا مفديو الرب، الذين افتداهم من يد ظالمهم.","107:3":"لم شتاتهم من البلدان: من الشرق والغرب، من الشمال والجنوب.","107:4":"تاهوا في البرية، في صحراء بلا طريق، ولم يجدوا مدينة يسكنون فيها.","107:5":"جاعوا وعطشوا حتى خارت نفوسهم في داخلهم.","107:6":"فاستغاثوا بالرب في ضيقهم، فأنقذهم من مصائبهم.","107:7":"وهداهم طريقا مستقيما ليتوجهوا إلى مدينة للسكن.","107:8":"فليرفعوا الشكر للرب على رحمته وعلى عجائبه لبني آدم.","107:9":"لأنه أشبع النفس المتلهفة وملأ النفس الجائعة خيرا.","107:10":"كانوا جالسين كالأسرى في الظلام وظلال الموت، موثقين بالذل والحديد،","107:11":"لأنهم تمردوا على كلام الله، واستهانوا بمشورة العلي.","107:12":"فأذل قلوبهم بالجهد المضني. تعثروا ولم يكن من معين.","107:13":"ثم استغاثوا بالرب في ضيقهم فأنقذهم من مصائبهم.","107:14":"أخرجهم من الظلام وظلال الموت وحطم أصفادهم.","107:15":"فليرفعوا الشكر للرب على رحمته، وعلى عجائبه لبني آدم.","107:16":"لأنه كسر أبواب النحاس، وقطع عوارض الحديد.","107:17":"سفهوا في جهلهم وسقموا من جراء آثامهم.","107:18":"عافت أنفسهم كل طعام، فصاروا على شفا الموت.","107:19":"ثم استغاثوا بالرب في ضيقهم، فأنقذهم من مصائبهم.","107:20":"أصدر أمره فشفاهم، وخلصهم من مهالكهم.","107:21":"فليرفعوا الشكر للرب على رحمته، وعلى عجائبه لبني آدم.","107:22":"وليقربوا له ذبائح الشكر، ويحدثوا بأعماله بترانيم الفرح.","107:23":"ركب بعضهم البحار في السفن التجارية، ليكسبوا رزقهم،","107:24":"ورأوا أعمال الرب وعجائبه في عمق المياه.","107:25":"فإنه بأمره أثار ريحا عاصفة فأهاجت أمواج البحر","107:26":"فارتفعت السفن إلى الأعالي، ثم هبطت إلى الأعماق، حتى ذابت نفوسهم من الفزع.","107:27":"تمايلوا وترنحوا مثل السكران، وأعيتهم الحيلة.","107:28":"ثم استغاثوا بالرب في ضيقهم، فأنقذهم من مصائبهم.","107:29":"هدأ العاصفة الشديدة، وسكن الأمواج.","107:30":"ففرحوا بهدوئها، ثم اقتادهم إلى المرفإ المنشود.","107:31":"فليرفعوا الشكر على رحمته، وعلى عجائبه لبني آدم.","107:32":"وليعظموه في محفل الشعب، وليسبحوه في اجتماع الشيوخ.","107:33":"إنه يحول الأنهار إلى قفار، وينابيع الماء إلى أرض عطشى.","107:34":"يجعل الحقول الخصيبة أرضا ملحة جرداء من جراء شر سكانها.","107:35":"يحول البرية إلى واحة، والأرض القاحلة ينابيع مياه.","107:36":"يسكن هناك الجياع فينشئون مدينة آهلة.","107:37":"ويزر عون حقولا ويغرسون كروما تنتج لهم غلالا وفيرة.","107:38":"ويباركهم أيضا فيتكاثرون جدا، ولا يدع مواشيهم تتناقص.","107:39":"عندما يقل الشعب ويذل بفعل الضيق والبلايا والأحزان،","107:40":"يصب الله الهوان على الرؤساء، ويضلهم في أرض تيه ليس فيها طريق.","107:41":"لكنه ينقذ المحتاجين من البؤس، ويكثر عشائرهم مثل قطعان الغنم.","107:42":"يرى المستقيمون هذا ويفرحون، أما الأثمة فيخرسون.","107:43":"فليتأمل كل حكيم في هذه الأمور، ويمعن النظر في مراحم الرب.","108:1":"إن قلبي ثابت ياالله . أرنم وأشدو لك. فهيا استيقظي يانفسي.","108:2":"استيقظي أيتها الرباب والعود. أنا أستيقظ قبيل الفجر.","108:3":"أحمدك بين الشعوب يارب وأشدو لك بين الأمم.","108:4":"فإن رحمتك قد عظمت فوق السماوات وحقك بلغ الغيوم.","108:5":"ارتفع ياالله فوق السماوات، وليتسام مجدك فوق الأرض كلها.","108:6":"استجب لي وخلص بيمينك المقتدرة كي ينجو أحباؤك.","108:7":"قد تكلم الله في قداسته، لذلك أبتهج وأقسم أرض شكيم وأقيس وادي سكوت،","108:8":"لي جلعاد، ولي منسى؛ أفرايم خوذة رأسي، ويهوذا صولجاني.","108:9":"موآب مرحضتي، وعلى أدوم ألقي حذائي، وعلى فلسطين أهتف منتصرا.","108:10":"من يقودني لمحاربة المدينة المحصنة؟ من يهديني إلى أدوم؟","108:11":"أليس أنت ياالله الذي أقصيتنا ولم تعد تخرج مع جيوشنا؟","108:12":"هب لنا عونا في الضيق، فعبث هو خلاص الإنسان.","108:13":"لكن بعون الله نحارب ببأس، وهو الذي يدوس أعداءنا.","109:1":"ياالله ، يامن أسبحه، لا تعتصم بالصمت.","109:2":"فقد فغر أشرار مخادعون أفواههم ضدي، وتقولوا علي بالكذب،","109:3":"يحاصرونني بكلام بغض، ويهاجمونني من غير علة.","109:4":"يبادلون محبتي بخصام، أما أنا فأصلي من أجلهم.","109:5":"يجازونني شرا مقابل خيري، وبغضا بدل حبي.","109:6":"ول على عدوي قاضيا ظالما، وليقف خصمه عن يمينه يتهمه جورا.","109:7":"عند محاكمته ليثبت عليه ذنبه، ولتحسب له صلاته خطيئة.","109:8":"لتقصر أيامه وليتول وظيفته آخر.","109:9":"ليتيتم بنوه وتترمل زوجته.","109:10":"ليتشرد بنوه ويستعطوا، وليلتمسوا قوتهم بعيدا عن خرائب سكناهم.","109:11":"ليسترهن المداين كل ممتلكاته، ولينهب الغرباء ثمار تعبه.","109:12":"لينقرض من يتراءف عليه، ولينقطع من يتحنن على أيتامه.","109:13":"لينقرض نسله وليمح اسمهم من الجيل القادم.","109:14":"ليذكر الرب إثم آبائه، ولا يغفر خطيئة أمه.","109:15":"لتمثل خطاياهم أمام الرب دائما كي يستأصل من الأرض ذكرهم.","109:16":"لأنه تغافل عن إبداء الرحمة، بل تعقب الفقير المنسحق القلب، ليميته.","109:17":"أحب اللعنة فلحقت به، ولم يسر بالبركة فابتعدت عنه.","109:18":"اكتسى اللعنة كرداء، فتسربت إلى باطنه كالمياه وإلى عظامه كالزيت.","109:19":"فلتكن له كرداء يتلفع به، وكحزام يتنطق به دائما.","109:20":"هذه أجرة مبغضي من عند الرب، الناطقين شرا على نفسي.","109:21":"أما أنت أيها الرب السيد فأحسن إلي من أجل اسمك، وأنقذني لأن رحمتك صالحة.","109:22":"فإني فقير ومسكين وقلبي جريح في داخلي.","109:23":"قد تلاشيت كالظل عند المغيب، وانتفضت كما تنفض جرادة (عن الثوب).","109:24":"وهنت ركبتاي من الصوم، وهزل جسدي كثيرا.","109:25":"صرت عندهم عارا، ينظرون إلي فيهزون رؤوسهم شامتين.","109:26":"أعني يارب إلهي، خلصني بمقتضى رحمتك.","109:27":"فيدركوا أن هذه هي يدك، وأنك أنت يارب قد فعلت هذا الأمر.","109:28":"هم يلعنونني أما أنت فتباركني. ليخز المشتكون علي، فأفرح أنا عبدك.","109:29":"ليكتس خصومي خجلا، وليتلفعوا بخزيهم كالرداء.","109:30":"بهتاف أرفع للرب شكرا عظيما، وفي وسط جمهور غفير أسبحه.","109:31":"لأنه يقف عن يمين المظلوم ليخلصه من الحاكمين عليه بالموت.","110:1":"قال الرب لربي: «اجلس عن يميني حتى أضع أعداءك موطئا لقدميك».","110:2":"يجعل الرب صهيون منطلقا لسلطانك، ويقول: «احكم في وسط أعدائك».","110:3":"في يوم محاربة أعدائك يتطوع شعبك. يجيء شبابك إلى التلال المقدسة كالندى في قلب الفجر.","110:4":"أقسم الرب ولن يتراجع: «أنت كاهن إلى الأبد على رتبة ملكيصادق».","110:5":"الرب واقف عن يمينك. في يوم غضبه يحطم ملوكا.","110:6":"يقضي بين الأمم، فيملأ الأرض الرحبة بجثث رؤسائها.","110:7":"يشرب الملك من النهر المجاور للطريق، لذلك يشمخ برأسه منتصرا.","111:1":"هللويا! أشكر الرب من كل قلبي في محفل أتقياء الشعب.","111:2":"ماأعظم أعمال الرب! يتأملها جميع المسرورين بها.","111:3":"صنيعه جلال وبهاء، وعدله ثابت إلى الأبد.","111:4":"جعل لعجائبه ذكرا، فالرب حنان ورحيم.","111:5":"أعطى متقيه طعاما، لأنه لا ينسى عهده أبدا.","111:6":"أظهر قوته لشعبه حين أورثهم أرض الأمم.","111:7":"أعمال يديه حق وعدل. وكل وصاياه أمينة.","111:8":"راسخة أبد الدهر، مصنوعة بالحق والاستقامة.","111:9":"افتدى شعبه وكرس عهده معه إلى الأبد، قدوس ومهوب اسمه.","111:10":"رأس الحكمة مخافة الرب. والعامل بها ذو فطنة شديدة. تسبيح الرب دائم إلى الأبد.","112:1":"هللويا! طوبى لمن يخشى الرب ويبتهج جدا بوصاياه.","112:2":"ذريته تكون قوية في الأرض، جيل المستقيمين يكون مباركا.","112:3":"يمتليء بيته مالا وغنى، وبره يدوم إلى الأبد.","112:4":"يشرق نور في الظلمة للمستقيمين لأن الرب حنان ورحيم وصديق.","112:5":"سعيد هو الرجل الذي يتحنن ويقرض مجانا ويدبر شؤونه بالحيطة والعدل.","112:6":"فإنه لن يتزعزع أبدا. ذكر الصديق يخلد إلى الأبد.","112:7":"لن يخاف من خبر سوء، فقلبه ثابت متكل على الرب.","112:8":"قلبه ثابت لا تعتريه المخاوف، ويشهد عقاب مضطهديه.","112:9":"يوزع بسخاء ويعطي الفقراء، وبره يدوم إلى الأبد، فيرتفع رأسه باعتزاز.","112:10":"يرى الشرير ذلك فيغتاظ، يصر بأسنانه ويذوب إذ شهوة الشرير لا تتحقق.","113:1":"هللويا. سبحوا ياعبيد الرب، سبحوا اسم الرب.","113:2":"ليكن اسم الرب مباركا من الآن وإلى الأبد.","113:3":"ليسبح باسم الرب من مشرق الشمس إلى مغربها.","113:4":"الرب متسام على جميع الأمم، ومجده فوق السماوات.","113:5":"من هو نظير الرب إلهنا الساكن في الأعالي؟","113:6":"المطل من عليائه إلى أسفل ليرى السماوات والأرض.","113:7":"ينهض المسكين من التراب، ويرفع البائس من المزبلة،","113:8":"ليجلسه مع أشراف شعبه.","113:9":"يرزق العاقر أولادا. يجعلها أما سعيدة. هللويا.","114:1":"عند خروج بني إسرائيل من مصر، وآل يعقوب من بين شعب غريب اللسان.","114:2":"صار يهوذا هيكلا مقدسا له، وإسرائيل مقر سلطانه.","114:3":"رأى البحر الأحمر ذلك فهرب، وتراجع نهر الأردن إلى الوراء.","114:4":"قفزت الجبال كأنها كباش، والتلال كأنها حملان.","114:5":"ما لك يابحر قد هربت، وياأردن قد رجعت إلى الوراء؟","114:6":"مالك ياجبال تقفزين كالكباش، وياتلال كالحملان؟","114:7":"تزلزلي ياأرض في حضرة الرب إله يعقوب.","114:8":"الذي حول الصخرة إلى جداول، والصوان إلى ينابيع مياه.","115:1":"لا تمجدنا يارب، بل مجد اسمك، من أجل رحمتك وحقك.","115:2":"لماذا تسألنا الأمم: أين هو إلهكم؟","115:3":"إن إلهنا في السماوات. كل ما شاء صنع.","115:4":"أما أوثانهم فهي فضة وذهب من صنع أيدي البشر.","115:5":"لها أفواه لكنها لا تنطق. لها عيون ولكنها لا تبصر.","115:6":"وآذان لكنها لا تسمع. وأنوف لكنها لا تشم.","115:7":"لها أيد لكنها لا تلمس. وأرجل لكنها لا تمشي، ولا تصدر من حناجرها صوتا.","115:8":"مثلها يصير صانعوها وكل من يتوكل عليها.","115:9":"اتكلوا على الرب يابني إسرائيل، هو عونكم وترسكم.","115:10":"اتكلوا على الرب يابيت هارون: هو عونكم وترسكم.","115:11":"اتكلوا على الرب ياخائفي الرب: هو عونكم وترسكم.","115:12":"الرب ذكرنا ويباركنا. يبارك شعب إسرائيل، يبارك الرب آل هارون.","115:13":"يبارك كل من يتقيه، صغارهم وكبارهم.","115:14":"ليزد الرب بركته عليكم وعلى أولادكم.","115:15":"ليبارككم الرب، خالق السماوات والأرض.","115:16":"السماوات للرب وحده، أما الأرض فوهبها لبني آدم.","115:17":"لا يسبح الأموات الرب، ولا الهاجعون في القبور.","115:18":"أما نحن فنبارك الرب من الآن وإلى الدهر. هللويا.","116:1":"إني أحب الرب لأنه يسمع ابتهالي ويستجيب إلى تضرعاتي.","116:2":"أمال أذنه إلي لذلك أدعوه مادمت حيا.","116:3":"طوقتني حبال الموت. أطبق علي رعب الهاوية. قاسيت ضيقا وحزنا.","116:4":"فدعوت الرب: آه يارب نج نفسي!","116:5":"الرب حنون وبار. إلهنا رحيم.","116:6":"الرب حافظ البسطاء. تذللت فخلصني.","116:7":"عودي يانفسي إلى طمأنينتك، لأن الرب قد أحسن إليك.","116:8":"لأنك يارب أنقذت نفسي من الموت، وعيني من الدمع، وقدمي من التعثر،","116:9":"لذلك أسلك بطاعة أمام الرب في ديار الأحياء.","116:10":"آمنت لذلك تكلمت مع الرب. أنا عانيت كثيرا.","116:11":"وقلت في حيرتي: «جميع البشر كاذبون».","116:12":"ماذا أرد للرب مقابل كل ما أبداه نحوي من حسن الصنيع؟","116:13":"سأتناول كأس الخلاص، وأدعو باسم الرب.","116:14":"أوفي نذوري للرب أمام كل شعبه.","116:15":"عزيز في عيني الرب موت قديسيه.","116:16":"آه يارب أنا عبدك. أنا عبدك وابن أمتك. أنت حللت قيودي.","116:17":"لك أقدم ذبائح الشكر، وأدعو باسمك.","116:18":"أوفي نذوري للرب أمام كل شعبه.","116:19":"في ديار بيت الرب، في وسطك ياأورشليم. هللويا.","117:1":"سبحوا الرب يا جميع الأمم، ومجدوه يا كل الشعوب.","117:2":"لأن رحمته غلبت علينا، وأمانة الرب إلى الأبد تدوم. هللويا!","118:1":"اشكروا الرب لأنه صالح، ورحمته إلى الأبد تدوم.","118:2":"ليقل بنو إسرائيل: إن رحمته إلى الأبد تدوم.","118:3":"ليقل بيت هرون: إن رحمته إلى الأبد تدوم.","118:4":"ليقل خائفو الرب: إن رحمته إلى الأبد تدوم.","118:5":"دعوت الرب في الضيق فأجابني وفرج عني.","118:6":"الرب معي فلا أخاف. ماذا يصنع بي البشر؟","118:7":"الرب معي. هو معين لي. سأرى هزيمة أعدائي.","118:8":"اللجوء إلى الرب خير من الاعتماد على البشر.","118:9":"اللجوء إلى الرب خير من الاعتماد على العظماء.","118:10":"حاصرتني جميع الأمم، لكني باسم الرب أبيدهم.","118:11":"حاصروني وضيقوا علي، لكني باسم الرب أبيدهم.","118:12":"حاصروني كالنحل، (اشتعلوا) ثم انطفأوا كنار الشوك. باسم الرب أبيدهم.","118:13":"دفعت بعنف كي أسقط، لكن الرب عضدني.","118:14":"الرب قوتي وترنيمي وقد صار لي خلاصا.","118:15":"صوت هتاف النصر والخلاص في مساكن الأبرار. يمين الرب مقتدرة في فعلها.","118:16":"يمين الرب مرتفعة. يمين الرب مقتدرة في فعلها.","118:17":"لا أموت بل أحيا وأذيع أعمال الرب.","118:18":"تأديبا أدبني الرب، وإلى الموت لم يسلمني.","118:19":"افتحوا لي أبواب البر، فأدخل فيها، وأشكر الرب.","118:20":"هذا الباب هو مدخل الأبرار إلى محضر الرب.","118:21":"أشكرك لأنك استجبت لي وصرت لي مخلصا.","118:22":"الحجر الذي رفضه البناؤون قد صار رأس الزاوية.","118:23":"من لدى الرب كان هذا، وهو مدهش في أعيننا.","118:24":"هذا هو اليوم الذي أعده الرب، فيه نبتهج ونفرح.","118:25":"آه يارب خلص. يارب اكفل لنا النجاح.","118:26":"مبارك الآتي باسم الرب. باركناكم من بيت الرب.","118:27":"الرب هو الله وبنوره أضاء لنا. اربطوا الذبيحة بحبال إلى زوايا المذبح.","118:28":"إلهي أنت، وإياك أشكر. إلهي أنت وإياك أعظم.","118:29":"اشكروا الرب لأنه صالح، ورحمته إلى الأبد تدوم.","119:1":"طوبى للسالكين في طريق الكمال، طريق شريعة الرب.","119:2":"طوبى لمن يحفظون وصايا الرب، الذين يطلبونه بكل القلب،","119:3":"ولا يرتكبون إثما، إنما في طرقه يسيرون.","119:4":"أنت أوصيت بحفظ وصاياك والعمل بها كلها.","119:5":"ليتك توجه طرقي لممارسة فرائضك.","119:6":"عندئذ لا أخزى إذا تأملت في جميع وصاياك.","119:7":"أحمدك بقلب مستقيم لأني أدركت أحكامك العادلة.","119:8":"سأحفظ وصاياك، فلا تتركني أبدا.","119:9":"بماذا يزكي الشاب مسلكه؟ بطاعته لكلمتك.","119:10":"لذلك طلبتك بكل قلبي، فلا تدعني أضل عن وصاياك.","119:11":"خبأت كلامك في قلبي، لئلا أخطيء إليك.","119:12":"مبارك أنت يارب. علمني فرائضك.","119:13":"بشفتي أعلنت جميع الأحكام التي نطقت بها.","119:14":"بطريق شهاداتك قد سررت أكثر من سرور الحائز على كل غنى.","119:15":"أتأمل وصاياك، وأحفظ سبلك.","119:16":"بفرائضك أتلذذ، ولا أنسى كلمتك.","119:17":"أحسن إلي أنا عبدك، فأحيا وأعمل بكلمتك.","119:18":"افتح عيني فأرى عجائب من شريعتك.","119:19":"غريب أنا في الأرض فلا تحجب عني وصاياك.","119:20":"تتلهف نفسي شوقا إلى أحكامك دائما.","119:21":"أنت تزجر المتكبرين الملعونين الذين يضلون عن وصاياك.","119:22":"انتزع عاري وهواني، لأنني أراعي وصاياك.","119:23":"جلس الرؤساء وتآمروا علي. أما أنا عبدك فبقيت أتأمل في فرائضك.","119:24":"وصاياك الشاهدة أيضا هي مسرتي، وأنا أستشيرها دائما.","119:25":"(أنا يائس) أرقد ملتصقا بالتراب، فأحيني حسب وعدك.","119:26":"اعترفت بما جنيت فاستجبت لي. علمني فرائضك.","119:27":"فهمني طريق أوامرك، فأتأمل في أعمالك العجيبة.","119:28":"نفسي ذائبة من الحزن. قوني بحسب وعدك.","119:29":"أبعد عني طريق الغواية وبرحمتك لقني شريعتك.","119:30":"قد اخترت طريق الحق، إذ وضعت أحكامك أمامي.","119:31":"التزمت بوصاياك الشاهدة لك يارب فلا تخزني.","119:32":"أجد مسرعا في طريق وصاياك، لأنك تشرح قلبي.","119:33":"يارب، علمني طريق فرائضك فأراعيها إلى النهاية.","119:34":"أعطني فهما لأحفظ شريعتك وأعمل بها بكل قلبي.","119:35":"اهدني في سبيل وصاياك، ففيها بهجتي.","119:36":"اجتذب قلبي نحو شهاداتك بعيدا عن مطامع المال.","119:37":"حول عيني عن رؤية الباطل، وفي طريقك أحيني.","119:38":"حقق لعبدك قولك، الذي وعدت به متقيك.","119:39":"أزل عني العار الذي أخشاه، لأن أحكامك صالحة.","119:40":"ها قد رغبت في وصاياك. بعدلك أحيني.","119:41":"أنعم علي يارب برحمتك وخلاصك حسب كلامك.","119:42":"فأرد على معيري، لأني أثق بوعدك.","119:43":"لا تنزع كلمة الحق من فمي لأن رجائي في أحكامك،","119:44":"فأحفظ شريعتك دائما، إلى الدهر والأبد،","119:45":"وأسلك في رحابة الحرية، لأني التمست أوامرك.","119:46":"سأتحدث بشهاداتك أمام الملوك ولا يعتريني الخزي،","119:47":"وأتلذذ بوصاياك التي أحببتها،","119:48":"وأرفع كفي إلى وصاياك التي أحببتها وأتأمل في فرائضك.","119:49":"حقق لعبدك وعدك الذي جعلتني أنتظره.","119:50":"وعدك ينعشني إذ هو تعزيتي في ضيقي.","119:51":"جاوز المتكبرون الحد في السخرية بي، لكن عن شريعتك لم أمل.","119:52":"تذكرت أحكامك منذ الدهر يارب، فتعزيت.","119:53":"تولاني الغيظ من الأشرار الذين نبذوا شريعتك.","119:54":"صارت فرائضك ترنيمات لي في أرض غربتي.","119:55":"ذكرت في الليل اسمك يارب، وحفظت شريعتك.","119:56":"هذا ما حظيت به لأني راعيت وصاياك.","119:57":"أنت يارب نصيبي، فأعدك بطاعة شريعتك.","119:58":"طلبت وجهك من كل قلبي: ارحمني حسب وعدك.","119:59":"تأملت في انحرافي فعدت وتحولت نحو شهاداتك.","119:60":"أسرعت من غير توان إلى العمل بوصاياك.","119:61":"قام الأشرار بالإيقاع بي، ولكني لم أنس شريعتك.","119:62":"أستيقظ في منتصف الليل لأحمدك من أجل أحكامك العادلة.","119:63":"رفيق أنا لكل الذين يتقونك، ولحافظي وصاياك.","119:64":"رحمتك يارب قد عمت الأرض فعلمني فرائضك.","119:65":"صنعت خيرا يارب معي أنا عبدك كما وعدت.","119:66":"هبني روح تمييز ومعرفة، لأني آمنت بوصاياك.","119:67":"ضللت قبل أن أدبتني، أما الآن فحفظت كلامك.","119:68":"أنت صالح ومحسن فعلمني فرائضك.","119:69":"لفق المتكبرون علي أقوالا كاذبة، أما أنا فبكل قلبي أحفظ وصاياك.","119:70":"غلظ قلبهم وتقسى، أما أنا فأتمتع بشريعتك.","119:71":"كان ما ذقت من هوان لخيري فتعلمت فرائضك.","119:72":"شريعة فمك خير لي من كل ذهب العالم وفضته.","119:73":"يداك صنعتاني وكونتاني، فهبني فهما لأتعلم وصاياك.","119:74":"فيراني متقوك ويفرحون، لأني انتظرت كلامك.","119:75":"قد علمت يارب أن أحكامك عادلة، وأنك بالحق أدبتني.","119:76":"فلتكن رحمتك تعزية لي، بمقتضى وعدك لعبدك.","119:77":"لتأتني مراحمك فأحيا، لأن شريعتك هي متعتي.","119:78":"ليخز المتكبرون لأنهم افتروا علي زورا، أما أنا فأتأمل في وصاياك.","119:79":"لينضم إلي متقوك وعارفو شهاداتك.","119:80":"ليكن قلبي متعلقا بكامل فرائضك، فلا أخزى.","119:81":"تتلهف نفسي إلى خلاصك. رجائي هو كلمتك.","119:82":"كلت عيناي في انتظار كلامك، وأنا أقول: متى تعزيني؟","119:83":"أصبحت متغضنا كزق خمر من الحرارة والدخان، ولكني لم أنس فرائضك.","119:84":"كم هي أيام عمر عبدك؟ متى تنزل القضاء بالذين يضطهدونني؟","119:85":"المتكبرون الذين يعصون شريعتك حفروا لي حفرا.","119:86":"وصاياك كلها صادقة. زورا يضطهدونني فأغثني.","119:87":"لولا قليل لأفنوني من الأرض","119:88":"أحيني بمقتضى رحمتك، فأطيع شرائعك.","119:89":"يارب كلمتك تدوم ثابتة في السماوات إلى الأبد.","119:90":"من جيل إلى جيل أمانتك. أنت أسست الأرض فلن تتزعزع.","119:91":"بموجب أحكامك تثبت اليوم، لأن الكل خدام لك.","119:92":"لو لم تكن شريعتك متعتي، لهلكت في مذلتي،","119:93":"لن أنسى وصاياك أبدا، لأنك بها وهبتني الحياة.","119:94":"أنا لك، فخلصني، لأني التمست وصاياك.","119:95":"تربص بي الأشرار ليهلكوني، لكني أتأمل في شهاداتك.","119:96":"رأيت لكل كمال حدا، أما وصيتك فلا حد لها.","119:97":"كم أحببت شريعتك، إنها موضوع تأملي طول النهار.","119:98":"وصيتك جعلتني أحكم من أعدائي، لأنها نصيبي إلى الأبد.","119:99":"صرت أكثر فهما من معلمي، لأن شهاداتك هي موضوع تأملي.","119:100":"صرت أكثر فطنة من الشيوخ، لأني راعيت وصاياك.","119:101":"منعت قدمي عن سلوك كل طريق شر، لكي أحفظ كلامك.","119:102":"لم أبتعد عن أحكامك لأنك هكذا علمتني.","119:103":"ما أحلى أقوالك لمذاقي. إنها أحلى من العسل في فمي.","119:104":"من وصاياك اكتسبت فطنة لذلك أبغضت كل طريق باطل.","119:105":"سراج لرجلي كلامك ونور لسبيلي.","119:106":"أقسمت يمينا موثقة أن أحفظ أحكامك العادلة.","119:107":"قاسيت جدا فأنعشني يارب بمقتضى وعدك.","119:108":"تقبل يارب صلوات شكري، وعلمني أحكامك.","119:109":"نفسي دائما في كفي، لكني لا أنسى شريعتك.","119:110":"نصب الأشرار لي فخا فتفاديته لأني لم أضل عن وصاياك.","119:111":"اتخذت شهاداتك ميراثا إلى الأبد، لأنها بهجة قلبي.","119:112":"لقد عزمت أن أتمم فرائضك إلى أن أموت.","119:113":"أبغضت ذوي الرأي المتقلب، أما شريعتك فأحببت.","119:114":"أنت ملجإي وترسي، وأملي في كلمتك.","119:115":"ابتعدوا عني يافاعلي الشر، فأحفظ وصايا إلهي.","119:116":"كن سندي كما وعدت، فأحيا ولا يخيب رجائي.","119:117":"اعضدني فأخلص، وأراعي فرائضك دائما.","119:118":"احتقرت الضالين عن فرائضك، ومكرهم لا يجديهم نفعا.","119:119":"رذلت جميع أشرار الأرض كأنهم نفاية، لذلك أحببت شهاداتك.","119:120":"اقشعر بدني رعبا منك وجزعت من أحكامك.","119:121":"أجريت قضاء وعدلا، فلا تسلمني إلى ظالمي.","119:122":"كن ضامنا لخير عبدك، فلا يجور علي المتكبرون.","119:123":"كلت عيناي اشتياقا إلى خلاصك وإلى تحقيق وعدك الأمين.","119:124":"عامل عبدك بمقتضى رحمتك، وعلمني فرائضك.","119:125":"عبدك أنا، فهبني فهما لأعرف شهاداتك.","119:126":"يارب آن لك أن تعمل، فقد نقضوا شريعتك.","119:127":"لذلك أحب وصاياك أكثر من الذهب الخالص،","119:128":"ولأني أحسب كل فرائضك مستقيمة في كل شيء، أبغض كل طريق باطل.","119:129":"ما أعجب شهاداتك. لذلك تراعيها نفسي.","119:130":"فتح كلامك ينير الذهن، ويهب البسطاء فهما.","119:131":"فغرت فمي لاهثا اشتياقا إلى وصاياك.","119:132":"التفت إلي وتحنن علي، كما تفعل دائما مع محبيك.","119:133":"ثبت خطواتي في كلمتك، ولا تدع أي إثم يتسلط علي.","119:134":"حررني من ظلم الإنسان، فأحفظ وصاياك.","119:135":"أضىء بوجهك على عبدك، وعلمني فرائضك.","119:136":"فاضت من عيني ينابيع دمع، لأنهم لم يراعوا شريعتك.","119:137":"عادل أنت يارب، وأحكامك مستقيمة.","119:138":"أصدرت أوامرك بعدل وبأقصى الأمانة.","119:139":"أتميز غيرة في داخلي، لأن أعدائي تغاضوا عن كلامك.","119:140":"أقوالك ممحصة نقية، وعبدك أحبها.","119:141":"صغير الشأن أنا وحقير ومع ذلك لم أنس وصاياك.","119:142":"عدلك عدل أبدي وشريعتك حق.","119:143":"استولى علي الضيق والشدة، ولا لذة لي إلا بوصاياك.","119:144":"شهاداتك عدل إلى الأبد. فهمني إياها فأحيا.","119:145":"صرخت إليك من كل قلبي، فاستجب لي يارب، وسأراعي شرائعك.","119:146":"إياك دعوت فخلصني لأطيع شهاداتك.","119:147":"استيقظت قبل الفجر واستغثت؛ رجائي في كلامك.","119:148":"الليل كله أظل مستيقظا، أتأمل في أقوالك","119:149":"استمع لي يارب بمقتضى رحمتك، وأحيني بموجب أحكامك.","119:150":"اقترب مني الساعون وراء الرذيلة، البعيدون عن شريعتك.","119:151":"إنما أنت يارب أقرب إلي، ووصاياك كلها حق.","119:152":"منذ القديم عرفت من شهاداتك أنك وضعتها لتثبت إلى الأبد.","119:153":"انظر إلى مذلتي وأنقذني، لأني لم أنس شريعتك.","119:154":"تول قضيتي وافدني، أحيني حسب كلمتك.","119:155":"الخلاص بعيد عن الأشرار، لأنهم لا يطلبون فرائضك.","119:156":"ما أكثر مراحمك يارب. أحيني بمقتضى أحكامك.","119:157":"كثيرون هم أعدائي ومضطهدي، ولكني لم أحد عن شهاداتك.","119:158":"نظرت إلى الغادرين شزرا، لأنهم لم يطيعوا كلمتك.","119:159":"انظر كيف أحببت وصاياك فأحيني يارب بمقتضى رحمتك.","119:160":"كلامك بأسره حق، وكل أحكامك إلى الأبد عادلة.","119:161":"اضطهدني رؤساء من غير علة، لكن قلبي لا يهاب سوى كلامك.","119:162":"أبتهج بكلامك كبهجة من عثر على غنيمة جزيلة.","119:163":"أبغضت الكذب ومقته، أما شريعتك فأحببتها.","119:164":"سبع مرات سبحتك في النهار على أحكامك العادلة.","119:165":"سلام جزيل لمحبي شريعتك، ولن يعثرهم بفضلها شيء","119:166":"رجوت خلاصك يارب ووصاياك عملت.","119:167":"حفظت نفسي شهاداتك وأنا أحبها جدا.","119:168":"راعيت وصاياك وشهاداتك، وجميع أعمالي ماثلة أمامك.","119:169":"ليصل صراخي إليك يارب. هبني فهما حسب كلامك.","119:170":"لتمثل طلبتي أمامك. أنقذني بموجب وعدك.","119:171":"تفيض شفتاي تسبيحا إذ تعلمني فرائضك.","119:172":"يشدو لساني بأقوالك، لأن جميع وصاياك عدل.","119:173":"لتغثني يدك لأني اخترت وصاياك.","119:174":"اشتقت إلى خلاصك يارب؛ شريعتك هي مسرتي.","119:175":"لتحي نفسي فتسبحك ولتكن أحكامك لي عونا.","119:176":"تهت كخروف ضال. فابحث عن عبدك، فإني لم أنس وصاياك.","120:1":"صرخت إلى الرب في ضيقي فاستجاب لي.","120:2":"نج نفسي يارب من الشفاه الكاذبة واللسان المنافق.","120:3":"أي نفع يأتيني من اللسان الغشاش؟","120:4":"إنه كسهام الجبار الحادة وكالجمر الأحمر الملتهب.","120:5":"ويلي لأني تغربت في ماشك، وسكنت في خيام قيدار.","120:6":"طال سكني مع أناس يبغضون السلام.","120:7":"أنا رجل سلام، وكلما دعوت إليه هبوا هم للحرب.","121:1":"أرفع عيني إلى الجبال. من أين يأتي عوني؟","121:2":"يأتي عوني من عند الرب، صانع السماوات والأرض.","121:3":"لا يدع قدمك تزل. لا ينعس حافظك.","121:4":"لا ينعس ولا ينام حافظ إسرائيل.","121:5":"الرب هو حافظك، الرب ستر لك عن يمينك.","121:6":"لن تضربك الشمس بحرها نهارا ولا القمر بنوره ليلا.","121:7":"يقيك الرب من كل شر. يقي نفسك.","121:8":"الرب يحفظ ذهابك وإيابك من الآن وإلى الأبد.","122:1":"فرحت بالقائلين لي: لنذهب معا إلى بيت الرب.","122:2":"تقف أقدامنا الآن داخل أبوابك ياأورشليم.","122:3":"أورشليم المبنية كمدينة متماسكة متحدة.","122:4":"إليها صعدت الأسباط، أسباط الرب لترفع الشكر له بحسب أوامره.","122:5":"هناك نصبت عروش القضاء، عروش آل داود.","122:6":"صلوا لأجل سلام أورشليم. ليفلح محبوك ويطمئنوا.","122:7":"ليكن السلام داخل أسوارك، والأمان داخل قصورك.","122:8":"من أجل إخوتي وأصحابي أقول: ليسد فيك سلام.","122:9":"من أجل الرب إلهنا ألتمس لك خيرا.","123:1":"إليك رفعت عيني ياساكنا في السماوات.","123:2":"كما تتعلق عيون العبيد بأيدي سادتهم، وعينا الجارية بيد سيدتها، هكذا تتعلق أنظارنا بالرب إلهنا حتى يتحنن علينا.","123:3":"ارحمنا يارب، ارحمنا، فقد شبعنا احتقارا.","123:4":"شبعت نفوسنا كثيرا من هزء المطمئنين وازدراء المتكبرين.","124:1":"لو لم يكن الرب معنا ليقل إسرائيل،","124:2":"لو لم يكن الرب معنا، عندما قام الناس علينا.","124:3":"لابتلعونا ونحن أحياء، عندما احتدم غضبهم علينا،","124:4":"ولجرفتنا المياه، ولطما السيل علينا،","124:5":"ولطغت المياه العاتية على أنفسنا.","124:6":"مبارك الرب الذي لم يجعلنا فريسة لأسنان أعدائنا.","124:7":"نجت نفوسنا كالعصفور من فخ الصيادين: انكسر الفخ ونجونا.","124:8":"عوننا باسم الرب صانع السماوات والأرض.","125:1":"الواثقون بالرب هم مثل جبل صهيون الراسخ الذي لا يتزعزع إلى الأبد.","125:2":"كما تحيط الجبال بأورشليم، كذلك يحيط الرب بشعبه من الآن وإلى الأبد،","125:3":"فلا يتسلط الأشرار على نصيب الأبرار لئلا يمد الأبرار أيديهم إلى الإثم.","125:4":"أحسن يارب إلى الأخيار وإلى ذوي القلوب المستقيمة.","125:5":"أما الذين يحيدون إلى طرق ملتوية، فإن الرب يسوقهم إلى الهلاك مع فاعلي الإثم. ليكن السلام لشعب إسرائيل.","126:1":"عندما أرجع الرب أهل أورشليم من السبي، صرنا كمن يرى حلما.","126:2":"عندئذ امتلأت أفواهنا ضحكا، وألسنتنا ترنما. عندئذ قالت الأمم: إن الرب قد أجرى أمورا عظيمة مع هؤلاء.","126:3":"نعم، إن الرب قد صنع أمورا عظيمة لنا، ففرحنا.","126:4":"أرجعنا يارب من سبينا، كما ترجع السيول إلى النقب.","126:5":"فمن يزرع بالدموع يحصد غلاته بالابتهاج.","126:6":"ومن يذهب باكيا حاملا بذاره يرجع مترنما حاملا حزم حصيده.","127:1":"إن لم يبن الرب البيت، فباطلا يتعب البناؤون. وإن لم يحرس الرب المدينة فباطلا يسهر الحارس.","127:2":"باطلا تكدون من الفجر المبكر وإلى وقت متأخر من الليل في سبيل لقمة العيش، فإن الرب يسد حاجة أحبائه حتى وهم نيام.","127:3":"هوذا البنون ميراث من عند الرب، والأولاد ثواب منه.","127:4":"أبناء الشبيبة مثل سهام في يد جبار متمرس.","127:5":"طوبى للذي ملأ جعبته منهم، فإنهم لا يخيبون حين يواجهون الخصوم في مجلس القضاء عند بوابة المدينة.","128:1":"طوباك يامن تتقي الرب وتسلك في طرقه.","128:2":"لأنك تأكل من تعب يديك وتتمتع بالسعادة والخير.","128:3":"تكون امرأتك ككرمة مثمر ة في جوانب بيتك، وأبناؤك كأغراس الزيتون حول مائدتك.","128:4":"هكذا يبارك الرجل الذي يتقي الرب.","128:5":"يباركك الرب من صهيون، حتى تشهد خير أورشليم كل أيام حياتك،","128:6":"وتعيش لترى أحفادك. وليكن لشعب إسرائيل سلام.","129:1":"ما أكثر ما ضايقوني في حداثتي يقول إسرائيل.","129:2":"ما أكثر ما ضايقوني في حداثتي، لكنهم لم يتغلبوا علي.","129:3":"جرحوا ظهري (في أرض مصر) جروحا عميقة، فصار كالأتلام (خطوط المحراث) الطويلة في حقل محروث.","129:4":"الرب عادل، كسر أغلال عبودية الأشرار.","129:5":"فليخز وليدبر جميع مبغضي صهيون.","129:6":"ليكونوا كالعشب النابت على السطوح، الذي يجف قبل أن ينمو،","129:7":"فلا يملأ الحاصد منه يده، ولا الحازم حضنه.","129:8":"ولا يقول عابرو السبيل لهم: «لتكن عليكم بركة الرب: نبارككم باسم الرب».","130:1":"أيها الرب إياك أدعو من الأعماق.","130:2":"فاسمع يارب صوتي، ولتكن أذناك مرهفتين إلى صوت تضرعي.","130:3":"إن كنت يارب تترصد الآثام، فمن يستطيع الوقوف في محضرك؟","130:4":"ولأنك مصدر الغفران فإن جميع الناس يهابونك.","130:5":"انتظرتك يارب. نفسي تنتظرك، وفي كلمتك رجائي.","130:6":"نفسي تنتظر الرب بلهفة أكثر من لهفة الحراس مترقبي الصبح.","130:7":"ليترج إسرائيل الرب، لأن منه الرحمة والفداء الكثير.","130:8":"وهو يفدي إسرائيل من جميع آثامه.","131:1":"يارب لم يشمخ قلبي ولا استعلت عيناي ولا حفلت بالعظائم وما يفوق إدراكي.","131:2":"ولكني سكنت نفسي وهدأتها، فصار قلبي مطمئنا كطفل مفطوم مستسلم بين ذراعي أمه","131:3":"ليترج إسرائيل الرب من الآن وإلى الأبد.","132:1":"اذكر يارب داود وكل معاناته.","132:2":"اذكر كيف أقسم للرب ونذر لإله يعقوب القدير:","132:3":"«لن أدخل بيت سكناي، ولن أعلو فراشي،","132:4":"ولن أعطي عيني نوما ولا أجفاني نعاسا،","132:5":"حتى أبني مقاما لتابوت الرب، ومسكنا لإله يعقوب القدير».","132:6":"في أفراتة سمعنا به، وفي حقول الوعر وجدناه،","132:7":"فقلنا: «لندخل إلى بيت الرب، ولنسجد عند موطيء قدميه».","132:8":"عد إلى هيكلك يارب، أنت وتابوت عزتك.","132:9":"ليرتد كهنتك البر ثوبا، وليهتف أتقياؤك فرحا.","132:10":"من أجل داود عبدك لا ترفض طلب ملكك الممسوح.","132:11":"قد أقسم الرب لداود قسما صادقا لا يرجع عنه: من ثمرة بطنك أقيم ملكا على عرشك.","132:12":"إذا حفظ بنوك عهدي وشهاداتي التي أعلمهم إياها، يجلس بنوهم أيضا على عرشك إلى الأبد.","132:13":"لأن الرب قد اختار أورشليم ورغب أن تكون له مسكنا.","132:14":"وقال: «هذه مقر راحتي إلى الأبد، فيها أسكن لأني أحببتها».","132:15":"أبارك غلاتها بركة جزيلة، وأشبع مساكينها خبزا.","132:16":"ألبس كهنتها ثوب الخلاص، فيهتف قديسوها مترنمين.","132:17":"أقيم هناك ملكا عظيما من أصل داود، وأعد سراجا منيرا لمن أمسحه.","132:18":"أكسو أعداءه خزيا. أما هو، فعلى رأسه يتألق تاجه».","133:1":"ما أحسن وما أبهج أن يسكن الإخوة معا (بوئام).","133:2":"فذلك مثل زيت المسحة العطر المسكوب على الرأس، النازل على اللحية، على لحية هارون، الجاري إلى أطراف ثوبه،","133:3":"بل مثل ندى حرمون المتقاطر على جبل صهيون. فإنه هناك أمر الرب أن تحل البركة والحياة إلى الأبد.","134:1":"هيا باركوا الرب ياجميع عبيده القائمين على خدمة بيته في الليالي.","134:2":"ارفعوا أيديكم نحو المقدس وباركوا الرب.","134:3":"يباركك الرب من صهيون، صانع السماوات والأرض.","135:1":"هللويا. سبحوا اسم الرب. سبحوه ياعبيد الرب،","135:2":"القائمين على الخدمة في بيت الرب، في ديار بيت إلهنا.","135:3":"سبحوا الرب فإنه صالح. اشدوا لاسمه، فإن ذاك حلو.","135:4":"لأن الرب قد اختار يعقوب لنفسه، واتخذ إسرائيل شعبا خاصا له.","135:5":"قد عرفت أن الرب عظيم، وأن سيدنا أسمى من جميع الآلهة.","135:6":"كل ما شاء صنع في السماوات، وفي الأرض والبحار، وفي كل الأغوار العميقة.","135:7":"يصعد الأبخرة من أقاصي الأرض، ويحدث بروقا للمطر، ويطلق الريح من خزائنه.","135:8":"هو الذي ضرب أبكار مصر، أبكار الناس والبهائم.","135:9":"وهو الذي أجرى آيات ومعجزات في وسطك يامصر، وعلى فرعون وجميع عبيده.","135:10":"ضرب أمما عظيمة، وقتل ملوكا مقتدرين:","135:11":"سيحون ملك الأموريين، وعوج ملك باشان، وجميع ممالك كنعان.","135:12":"ووهب أرضهم ميراثا لإسرائيل شعبه.","135:13":"اسمك خالد إلى الأبد. ذكرك يار ب من جيل إلى جيل.","135:14":"لأن الرب يحاكم شعبه بعدل ويعطف على عبيده.","135:15":"أما أصنام الأمم فهي من فضة وذهب، صنعة أيدي الناس.","135:16":"لها أفواه لكنها لا تتكلم، وعيون لكنها لا ترى.","135:17":"وآذان لكنها لا تسمع. وليس في أفواهها نسمة حياة.","135:18":"مثلها يصير صانعوها وكل من يتوكل عليها.","135:19":"يابيت إسرائيل باركوا الرب. يابيت هارون باركوا الرب.","135:20":"يابيت لاوي باركوا الرب. ياخائفي الرب باركوا الرب.","135:21":"مبارك الرب من صهيون، الرب الساكن في أورشليم. هللويا.","136:1":"ارفعوا الشكر للرب لأن رحمته إلى الأبد تدوم.","136:2":"ارفعوا الشكر لإله الآلهة، لأن رحمته إلى الأبد تدوم.","136:3":"ارفعوا الشكر لرب الأرباب، لأن رحمته إلى الأبد تدوم.","136:4":"الصانع العجائب العظام وحده، لأن رحمته إلى الأبد تدوم.","136:5":"الصانع السماوات بحكمة، لأن رحمته إلى الأبد تدوم.","136:6":"الباسط الأرض فوق المياه، لأن رحمته إلى الأبد تدوم.","136:7":"الصانع الأنوار العظيمة لأن رحمته إلى الأبد تدوم.","136:8":"الشمس لتضيء نهارا، لأن رحمته إلى الأبد تدوم.","136:9":"والقمر والكواكب لتنير ليلا، لأن رحمته إلى الأبد تدوم.","136:10":"الذي ضرب مصر مع أبكارها، لأن رحمته إلى الأبد تدوم.","136:11":"وأخرج بني إسرائيل من وسطهم، لأن رحمته إلى الأبد تدوم.","136:12":"بيد شديدة وذراع قديرة، لأن رحمته إلى الأبد تدوم.","136:13":"الذي فلق البحر الأحمر إلى شطرين، لأن رحمته إلى الأبد تدوم.","136:14":"وأجاز الإسرائيليين في وسطه، لأن رحمته إلى الأبد تدوم.","136:15":"ودفع فرعون وجيشه إلى البحر، لأن رحمته إلى الأبد تدوم.","136:16":"الذي قاد شعبه في البرية، لأن رحمته إلى الأبد تدوم.","136:17":"الذي أطاح بملوك عظماء. لأن رحمته إلى الأبد تدوم.","136:18":"وقتل ملوكا ذوي شهرة، لأن رحمته إلى الأبد تدوم.","136:19":"كسيحون ملك الأموريين، لأن رحمته إلى الأبد تدوم.","136:20":"وعوج ملك باشان، لأن رحمته إلى الأبد تدوم.","136:21":"وأعطى أرضهم ميراثا، لأن رحمته إلى الأبد تدوم.","136:22":"ميراثا لإسرائيل عبده، لأن رحمته إلى الأبد تدوم.","136:23":"الذي ذكرنا في مذلتنا، لأن رحمته إلى الأبد تدوم.","136:24":"وخلصنا من أعدائنا، لأن رحمته إلى الأبد تدوم.","136:25":"الذي يرزق خبزا كل بشر لأن رحمته إلى الأبد تدوم.","136:26":"ارفعوا الشكر لإله السماوات، لأن رحمته إلى الأبد تدوم.","137:1":"على ضفاف أنهار بابل جلسنا، وبكينا عندما تذكرنا أورشليم.","137:2":"هناك علقنا أعوادنا على أشجار الصفصاف.","137:3":"هناك طلب منا الذين سبونا أن نشدو بترنيمة، والذين عذبونا أن نطربهم قائلين: «أنشدوا لنا من ترانيم صهيون».","137:4":"كيف نشدو بترنيمة الرب في أرض غريبة؟","137:5":"إن نسيتك ياأورشليم، فلتنس يميني مهارتها.","137:6":"ليلتصق لساني بحنكي إن لم أذكرك ولم أفضلك على ذروة أفراحي.","137:7":"اذكر يارب لبني أدوم ما فعلوه يوم خراب أورشليم، إذ قالوا: «اهدموا اهدموا حتى يتعرى أساسها».","137:8":"يابنت بابل المحتم خرابها، طوبى لمن يجازيك بما جزيتنا به.","137:9":"طوبى لمن يمسك صغارك ويضرب بهم الصخرة.","138:1":"أسبحك من كل قلبي، وأشدو لك أمام الملائكة.","138:2":"أسجد في هيكل قدسك، وأحمد اسمك من أجل رحمتك وحقك، لأنك عظمت كلمتك واسمك فوق كل شيء","138:3":"يوم دعوتك استجبت لي، وشجعتني إذ زدتني قوة في داخلي.","138:4":"يحمدك جميع ملوك الأرض يارب، متى سمعوا وعودك.","138:5":"ويشيدون بكل أعمالك لأن مجدك عظيم.","138:6":"فمع تعاليك، تلتفت إلى المتواضعين، أما المتكبر فتعرفه من بعيد.","138:7":"ولو سلكت في وسط الضيق فإنك تحييني، إذ بيدك تدفع عني غضب أعدائي ويمينك تخلصني.","138:8":"الرب ينجز مقاصده لي. رحمتك يارب إلى الأبد تدوم، فلا تتخل عني لأني صنع يديك.","139:1":"يارب قد فحصتني وعرفتني.","139:2":"أنت عرفت قعودي ونهوضي. فهمت فكري من بعيد.","139:3":"أنت تقصيت مسلكي ومرقدي، وتعرف كل طرقي.","139:4":"عرفت كل كلمة من قبل أن يتفوه بها لساني.","139:5":"لقد طوقتني (بعلمك) من خلف ومن أمام وبسطت يدك فوقي.","139:6":"ما أعجب هذا العلم الفائق، إنه أسمى من أن أدركه.","139:7":"أين المهرب من روحك؟ أين المفر من حضرتك؟","139:8":"إن صعدت إلى السماوات فأنت هناك، وإن جعلت فراشي في عالم الأموات فهناك أنت أيضا.","139:9":"إن استعرت أجنحة الفجر وطرت، وسكنت في أقصى أطراف البحر","139:10":"فهناك أيضا يدك تهديني ويمناك تمسكني.","139:11":"إن قلت في نفسي: ربما الظلمة تحجبني والضوء حولي يصير ليلا،","139:12":"فحتى الظلمة لا تخفي عنك شيئا، والليل كالنهار يضيء، فسيان عندك الظلام والضوء.","139:13":"لأنك أنت قد كونت كليتي. نسجتني داخل بطن أمي.","139:14":"أحمدك لأنك صنعتني بإعجازك المدهش. ما أعجب أعمالك ونفسي تعلم ذلك يقينا.","139:15":"لم يخف عليك كياني عندما كونت في السر، وجبلت في أعماق الأرض.","139:16":"رأتني عيناك وأنا مازلت جنينا؛ وقبل أن تخلق أعضائي كتبت في سفرك يوم تصورتها.","139:17":"ما أثمن أفكارك ياالله عندي! ما أعظم جملتها!","139:18":"إن أحصيتها زادت على الرمل عددا. عندما أستيقظ أجدني مازلت معك.","139:19":"ليتك ياالله تقتل الأشرار، فيبتعد عني سافكو الدماء.","139:20":"فإنهم يتحدثون عنك بالمكر والكذب، لأنهم أعداؤك.","139:21":"يارب ألا أبغض مبغضيك، وأكره الثائرين عليك؟","139:22":"بغضا تاما أبغضهم، وأحسبهم أعداء لي.","139:23":"تفحصني ياالله واعرف قلبي. امتحني واعرف أفكاري.","139:24":"وانظر إن كان في طريق سوء، واهدني الطريق الأبدي.","140:1":"أنقذني يارب من الأشرار واحفظني من الظالمين،","140:2":"الذين ينوون على الشر في قلوبهم ويثيرون الحرب دائما،","140:3":"سنوا ألسنتهم كالحية، وسم الأصلال تحت شفاههم.","140:4":"احمني يارب من قبضة الشرير، وأنقذني من الظالمين المتآمرين على عرقلة خطواتي.","140:5":"أخفى لي المتكبرون فخا، ونشروا شبكة بجانب الطريق، ونصبوا لي أشراكا.","140:6":"قلت للرب: «أنت إلهي» فيارب أصغ إلى صوت تضرعي.","140:7":"أيها الرب السيد، ياقوة خلاصي، أنت وقيت رأسي في يوم القتال.","140:8":"لا تحقق يارب رغبات الأشرار، ولا تنجح مكيدتهم لئلا يستكبروا.","140:9":"رد على رؤوس من يحاصرونني مكائد شفاههم.","140:10":"ليسقط عليهم جمر ملتهب، وليطرحوا إلى النار، وإلى غمرات اللجج، فلا ينهضوا أيضا.","140:11":"لا تدع ذا اللسان السليط يثبت في الأرض: فالشر يتصيد رجل الظلم ليهلكه.","140:12":"قد علمت أن الرب ينصف دعوى المساكين ويحكم بالحق للمحتاجين.","140:13":"نعم، إن الصديقين يحمدون اسمك، والصالحين يقيمون في حضرتك.","141:1":"يارب إليك دعوت، فأسرع لإغاثتي. أصغ إلى صوتي عندما أصرخ إليك.","141:2":"لتكن صلاتي أمامك كالبخور، ورفع يدي مثل تقدمة المساء.","141:3":"أقم يارب حارسا لفمي، واحفظ باب شفتي.","141:4":"لا تدع قلبي يتعلق بشيء رديء، فيمارس أعمال الشر مع فاعلي الإثم. ولا تدعني آكل من أطايبهم.","141:5":"ليضربني الصديق فذلك رحمة، وليوبخني فذلك زيت عاطر لرأسي. أما الأشرار فإني أصلي دائما (كي تحفظني من أفعالهم الأثيمة).","141:6":"عندما يلقى بقضاتهم الظالمين من على الصخرة، آنئذ يسمعون لكلماتي إذ يوقنون أنها حق.","141:7":"تتناثر عظامهم عند فم القبر كشظايا الحطب المشققة المبعثرة على الأرض.","141:8":"لكن نحوك أيها الرب السيد رفعت عيني، وبك لذت، فلا تترك نفسي عرضة للموت.","141:9":"احفظني من الفخ الذي نصبوه لي، ومن أشر اك فاعلي الإثم.","141:10":"ليسقط الأشرار في أشراكهم حتى أنجو تمام النجاة.","142:1":"بصوتي إلى الرب أصرخ. بصوتي إلى الرب أتضرع.","142:2":"أبثه شكواي وأحدثه بضيقي.","142:3":"عندما غشي على روحي في داخلي كنت أنت عالما بمسلكي. في الطريق التي سلكتها نصبوا لي فخا.","142:4":"التفت نحو يميني فلا تجد من يحفل بي، لم يبق لي ملاذ أو من يسأل عني.","142:5":"إياك دعوت يارب قائلا: أنت ملجإي، أنت نصيبي في أرض الأحياء.","142:6":"أصغ إلى صراخي لأنني قد تذللت جدا. أنقذني من مضطهدي لأنهم أشد مني.","142:7":"أفرج كربة نفسي لأسبح باسمك، فيلتف الصديقون حولي ثوابا لي منك.","143:1":"يارب اسمع صلاتي، وأصغ إلى تضرعاتي. استجب لي بفضل أمانتك وعدلك.","143:2":"لا تحاكم عبدك، فلن يتبرر أمامك إنسان.","143:3":"العدو يضطهدني، يسحق حياتي. زجني في سجن مظلم، فصرت مثل الذين ماتوا واندثر ذكرهم.","143:4":"غشي على روحي في داخلي، وتحير قلبي في أعماقي.","143:5":"تذكرت الأيام السالفة متأملا في جميع أعمالك، متفكرا في صنيع يديك.","143:6":"بسطت إليك يدي.. عطشت إليك نفسي كأرض ظامئة.","143:7":"أجبني مسرعا يارب. وهنت روحي فلا تحجب وجهك عني، لئلا أصير كالمنحدرين إلى القبر.","143:8":"أسمعني في الصباح رحمتك، فإني عليك توكلت. عرفني الطريق التي أسلكها، لأني إليك رفعت نفسي.","143:9":"أنقذني من أعدائي يارب، لأنني بك استعذت.","143:10":"علمني أن أعمل ما يرضيك لأنك أنت إلهي، وليهدني روحك الصالح إلى أرض مستوية.","143:11":"أحيني يارب من أجل اسمك، وبعدلك أفرج ضيق نفسي.","143:12":"برحمتك لي استأصل أعدائي، وأهلك جميع ظالمي، لأني أنا خادمك.","144:1":"مبارك الرب صخرتي، الذي يدرب يدي على القتال وأصابعي على الحرب.","144:2":"هو رحمتي ومعقلي، حصني ومنقذي، ترسي ومتكلي، والمخضع شعبي لي.","144:3":"يارب، من هو الإنسان حتى تعبأ به وابن الإنسان حتى تكترث له؟","144:4":"إنما الإنسان أشبه بنفخة. أيامه كظل عابر.","144:5":"يارب طأطىء سماواتك وانزل. المس الجبال فتدخن.","144:6":"أرسل بروقك وبددهم، أطلق سهامك النارية وأزعجهم.","144:7":"مد يديك من العلاء. أنجدني وأنقذني من لجج المياه، من أيدي الغرباء،","144:8":"الذين نطقت أفواههم بالكذب، ويمينهم يمين زور.","144:9":"ياالله ، أرنم لك ترنيمة جديدة. أشدو لك على رباب ذات عشرة أوتار.","144:10":"يامن تعطي الملوك خلاصا، وتنقذ داود عبدك من السيف القاتل.","144:11":"أنجدني وأنقذني من أيدي الغرباء، الذين تنطق أفواههم بالكذب، ويمينهم يمين زور.","144:12":"حتى يكون أبناؤنا كأغراس نامية في حداثتها، وبناتنا مثل أعمدة زوايا القصور المنحوتة.","144:13":"مخازننا ملآنة تفيض بشتى الأصناف، وأغنامنا تنتج ألوفا، وعشرات الألوف في مراعينا،","144:14":"وأبقارنا حاملة، ولا يكون هناك اقتحام غاز، ولا هجوم عدو، ولا شكوى خصم في شوارعنا.","144:15":"طوبى لشعب هكذا حالته. طوبى لشعب إلهه الرب.","145:1":"ياإلهي الملك، إني أعظمك وأبارك اسمك إلى الدهر والأبد.","145:2":"في كل يوم أباركك، وأسبح اسمك إلى الدهر والأبد.","145:3":"عظيم هو الرب، وله جزيل التسبيح، ولا استقصاء لعظمته.","145:4":"يمدح أعمالك جيل ماض لجيل آت، معلنين أفعالك المقتدرة.","145:5":"أتحدث عن بهاء مجدك الجليل، وأتأمل في أعمالك الخارقة.","145:6":"هم يخبرون بجبروت أفعالك الرهيبة، وأنا أذيع أعمالك العظيمة.","145:7":"يفيضون بذكر صلاحك العميم وبعدلك يترنمون.","145:8":"الرب حنان ورحيم، بطيء الغضب ووافر الرأفة.","145:9":"الرب يغمر الجميع بصلاحه، ومراحمه تعم كل أعماله.","145:10":"كل أعمالك تسبح بحمدك يارب، وأتقياؤك يباركونك،","145:11":"يخبرون بمجد ملكك، ويتحدثون عن قدرتك.","145:12":"لكي يطلعوا الناس على أفعالك المقتدرة، وعلى بهاء ملكك المجيد.","145:13":"ملكك ملك سرمدي، وسلطانك من جيل إلى جيل يدوم.","145:14":"يسند الرب كل العاثرين، وينهض كل المنحنين.","145:15":"بك تتعلق أعين الناس راجية وأنت ترزقهم طعامهم في أوانه.","145:16":"تبسط يدك فتشبع رغبة كل مخلوق حي.","145:17":"الرب عادل في جميع طرقه، ورحيم في كل أعماله.","145:18":"الرب قريب من جميع الذين يدعونه بصدق،","145:19":"يجيب سؤل جميع خائفيه، ويسمع تضرعهم فيخلصهم.","145:20":"يحافظ الرب على كل محبيه، أما الأشر ار فيبيدهم جميعا.","145:21":"يشدو فمي بتسبيح الرب، وليبارك كل إنسان اسمه القدوس، إلى أبد الآبدين.","146:1":"هللويا! سبحي يانفسي الرب.","146:2":"أسبح الرب مادمت حيا، وأشدو لإلهي مادمت موجودا.","146:3":"لا تتوكلوا على الرؤساء، ولا على ابن آدم الذي لا يستطيع أن يخلصكم.","146:4":"تنطلق روحه منه فيعود إلى ترابه، وآنئذ تندثر تدابيره.","146:5":"طوبى لمن يكون إله يعقوب معينه، ورجاؤه في الرب إلهه،","146:6":"خالق السماوات والأرض والبحر وكل ما فيها، الأمين إلى الأبد.","146:7":"منصف المظلومين ورازق الجياع طعاما. يحرر الرب المأسورين.","146:8":"الرب يفتح أعين العمي. الرب ينهض المنحنين. الرب يحب الصديقين.","146:9":"الرب يحفظ الغرباء، يعضد اليتامى والأرامل، ولكنه يحبط مساعي الأشرار.","146:10":"الرب يملك إلى الأبد. يملك إلهك ياصهيون من جيل إلى جيل. هللويا.","147:1":"سبحوا الرب، فإن الترنم لإلهنا طيب، وتسبيحه ملذ ولائق.","147:2":"يبني الرب أورشليم، ويجمع شمل المنفيين من إسرائيل.","147:3":"إنه يشفي منكسري القلب ويضمد جراحهم.","147:4":"يحصي عدد الكواكب ويدعوها جميعها بأسمائها.","147:5":"عظيم هو سيدنا، وفائقة هي قوته، ولا حد لحكمته.","147:6":"يرفع الرب الودعاء، ويطرح الأشرار إلى الأرض.","147:7":"ردوا على الرب بحمد، رنموا لإلهنا على العود.","147:8":"فهو يكسو السماوات سحابا ويمطر على الأرض، وينبت العشب على الجبال.","147:9":"يهب الطعام للبهائم، ولفراخ الغربان الناعقة.","147:10":"لا تستهويه قوة الخيل، ولا تسره ساقا العداء.","147:11":"إنما يرضى الرب بخائفيه، الراجين رحمته.","147:12":"مجدي الرب ياأورشليم، وسبحي إلهك ياصهيون.","147:13":"فإنه ثبت عوارض أبوابك (في وجه الأعداء)، وبارك بنيك في داخلك.","147:14":"هو الذي يجعل حدودك آمنة، ومن أفضل الحنطة يشبعك خبزا.","147:15":"يصدر أمره إلى الأرض فتنفذه بسرعة فائقة.","147:16":"ينثر الثلج كالصوف، ويذري الجليد كالرماد.","147:17":"يلقي برده كفتات الخبز. من يصمد في وجه صقيعه؟","147:18":"ثم يصدر أمره فيذيبها. يرسل ريحه فتسيل المياه.","147:19":"يعلن ليعقوب كلمته ولإسرائيل فرائضه وأحكامه.","147:20":"لم يعامل أمة أخرى هكذا، ولم يعرفها أحكامه هللويا.","148:1":"هللويا! سبحوا الرب من السماوات. سبحوه في الأعالي.","148:2":"سبحوه ياجميع ملائكته. سبحوه ياجميع أجناده.","148:3":"سبحيه ياشمس وياقمر. سبحيه ياجميع الكواكب المشرقة.","148:4":"سبحيه ياسماء السماوات، ويا أيتها السحب التي فوق الجلد.","148:5":"لتسبح هذه اسم الرب، لأنها بأمره خلقت،","148:6":"وثبتها إلى الدهر والأبد، واضعا لها حدا لا تتجاوزه.","148:7":"سبحي الرب من على الأرض ياوحوش البحر وياكل اللجج.","148:8":"أيتها النار والبرد، والثلج والضباب، الريح العاصفة المنفذة لأمره،","148:9":"الجبال والتلال جميعا، الأشجار المثمرة والأرز كله،","148:10":"الحيوانات البرية والمواشي كلها، الزواحف والطيور.","148:11":"ملوك الأرض وجميع الشعوب وحكام الأرض وجميع الرؤساء،","148:12":"الفتيان والفتيات والشيوخ والشبان،","148:13":"ليسبحوا اسم الرب، لأنه وحده متعال. مجده فوق الأرض والسماوات.","148:14":"يرفع رأس شعبه إكراما لكل أتقيائه، لبني إسرائيل الشعب المقرب إليه. هللويا.","149:1":"هللويا! رنموا للرب ترنيمة جديدة. تغنوا بتسبيحه في محفل الأتقياء.","149:2":"ليفرح شعب إسرائيل بصانعه، وليبتهج بنو صهيون بملكهم.","149:3":"ليسبحوا اسمه بالرقص، ليرنموا له على عزف الدف والعود.","149:4":"لأن الرب يسر بشعبه، يجمل الودعاء بالخلاص.","149:5":"ليبتهج الأتقياء بهذا المجد. ليهتفوا فرحا في أسرتهم.","149:6":"ليهتفوا مسبحين الرب ملء أفواههم وليتقلدوا بسيف ذي حدين في أيديهم،","149:7":"لتنفيذ الانتقام في الأمم، ومعاقبة الشعوب.","149:8":"ليقيدوا ملوكهم بالسلاسل وشرفاءهم بأغلال من حديد.","149:9":"ليتم فيهم حكم الله المكتوب، فيكون هذا تكريما لجميع قديسيه. هللويا.","150:1":"هللويا! سبحوا الله في هيكله. سبحوه في السماء التي صنعها بقدرته","150:2":"سبحوه من أجل أعماله المقتدرة. سبحوه حسب عظمته الفائقة.","150:3":"سبحوه بصوت بوق. سبحوه بالرباب والعود.","150:4":"سبحوه بالدف والرقص. سبحوه بأوتار ومزمار.","150:5":"سبحوه على وقع الصنوج. سبحوه بالصنوج المداوية.","150:6":"لتسبح الرب كل نسمة. هللويا."};
